import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`Controles del entorno de ejecución de ACP para habilitar el despacho, seleccionar backends, restringir los agentes de destino permitidos y seleccionar el comportamiento de proyección de turnos en streaming.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Agentes permitidos de ACP`},help:{"v1-f2mw0d-3a":`Lista de identificadores de agentes de destino de ACP permitidos para las sesiones del entorno de ejecución de ACP. Si está vacía, no se aplica ninguna restricción adicional de lista de permitidos.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`Backend de ACP`},help:{"v1-1s1l6bz-2v":`Identificador del backend predeterminado del entorno de ejecución de ACP (por ejemplo: acpx). Debe coincidir con el backend de un complemento registrado del entorno de ejecución de ACP.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`Agente predeterminado de ACP`},help:{"v1-7donnu-2c":`Identificador del agente de destino de ACP que se usa como alternativa cuando las creaciones de instancias de ACP no especifican un destino explícito.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`Despacho de ACP habilitado`},help:{"v1-1ug9t9m-3w":`Control independiente de despacho para los turnos de sesión de ACP (valor predeterminado: true). Establécelo en false para mantener disponibles los comandos de ACP y bloquear la ejecución de turnos de ACP.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP habilitado`},help:{"v1-1uonl1v-2a":`Control global de la función ACP. Mantenlo deshabilitado a menos que el entorno de ejecución y la política de ACP estén configurados.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`Backends alternativos de ACP`},help:{"v1-1wvdifq-5m":`Lista ordenada de identificadores de backends alternativos de ACP que se prueban cuando el backend principal falla con UNAVAILABLE (por ejemplo: límite de solicitudes / cuota agotada). Cada entrada debe coincidir con un backend de complemento de ejecución de ACP registrado.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Comando de instalación del entorno de ejecución de ACP`},help:{"v1-1jjuv9m-39":"Comando opcional de instalación/configuración para el operador que muestran `/acp install` y `/acp doctor` cuando falta la conexión con el backend de ACP."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`Transmisión de ACP`},help:{"v1-1bka5p-2v":`Controles de proyección de la transmisión de ACP para el tamaño de los fragmentos, la visibilidad de los metadatos y el comportamiento de entrega sin duplicados.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Modo de entrega de la transmisión de ACP`},help:{"v1-19gdmx1-3s":`Estilo de entrega de ACP: live transmite la salida proyectada de forma incremental; final_only almacena en búfer toda la salida proyectada de ACP hasta los eventos de finalización del turno.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Supresión de repeticiones en la transmisión de ACP`},help:{"v1-manh32-3d":`Cuando es true (valor predeterminado), suprime las líneas repetidas de proyección de estado/herramientas de ACP en un turno sin modificar los eventos sin procesar de ACP.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Visibilidad de etiquetas en la transmisión de ACP`},help:{"v1-1ybhx22-34":`Ajustes de visibilidad específicos por sessionUpdate para la proyección de ACP (por ejemplo, usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Agentes`},help:{"v1-2rc4v8-55":`Raíz de la configuración del entorno de ejecución de los agentes. Los elementos del mismo nivel que la raíz controlan la infraestructura y los valores predeterminados comunes a los agentes; agents.defaults controla el comportamiento del bucle del agente; las entradas de cada agente pueden sobrescribir cualquiera de estos ajustes cuando se admita.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Valores predeterminados del agente`},help:{"v1-1af7k5b-5a":`Configuración predeterminada compartida que heredan los agentes, salvo que se sobrescriba en cada entrada de agents.entries. Usa los valores predeterminados para garantizar un comportamiento base coherente y reducir la configuración duplicada por agente.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Destino de la herencia de autenticación`},help:{"v1-2d16wl-2x":`Propietario del almacén de credenciales heredado para mantener la compatibilidad durante la actualización, hasta que las credenciales se reubiquen por agente.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Propietario de la herencia de autenticación`},help:{"v1-1a1s7nm-4s":`Agente cuyo almacén de credenciales antiguo sigue siendo la fuente de herencia tras la retirada del marcador predeterminado. Se escribe automáticamente durante la actualización cuando el propietario anterior no era main.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Máximo de caracteres de inicialización`},help:{"v1-drlo3i-37":`Máximo de caracteres de cada archivo de inicialización del espacio de trabajo que se inyectan en el prompt del sistema antes de truncarlo (valor predeterminado: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Máximo total de caracteres de inicialización`},help:{"v1-1evwsjb-2c":`Máximo total de caracteres entre todos los archivos de inicialización del espacio de trabajo inyectados (valor predeterminado: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Compactación`},help:{"v1-1qxdwz8-5p":`Comportamiento de compactación cuando el contexto se acerca a los límites de tokens, incluida la estrategia y el comportamiento de volcado de memoria previo a la compactación. Usa esta opción cuando las sesiones prolongadas necesiten una continuidad estable con ventanas de contexto reducidas.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Compactación automática integrada`},help:{"v1-1et7vwu-5l":`Activa la compactación automática proactiva integrada (valor predeterminado: true). Establece false para detener la compactación integrada basada en umbrales y conservar la recuperación por desbordamiento de OpenClaw, la compactación previa y el comando manual /compact.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Política de identificadores de compactación`},help:{"v1-hby01l-4l":`Política de conservación de identificadores para los resúmenes de compactación: "strict" antepone las instrucciones integradas para conservar identificadores opacos (valor predeterminado), mientras que "off" desactiva este prefijo.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Tokens recientes que conservar en la compactación`},help:{"v1-tgysub-5h":`Cantidad mínima de tokens que se conservan de la ventana de conversación más reciente durante la compactación. Usa valores más altos para proteger la continuidad del contexto inmediato y valores más bajos para conservar más historial antiguo.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`Umbral de tamaño de la transcripción activa para la compactación`},help:{"v1-u715n1-90":`Umbral en bytes que activa la compactación local previa normal cuando la ventana de transcripción que ve el modelo (desde la última compactación o el último restablecimiento) alcanza este tamaño (bytes o cadenas como "20mb"). Establécelo en 0 o déjalo sin configurar para desactivarlo. También limita las transcripciones nativas de ejecución de Codex app-server; los hilos nativos que superan el tamaño permitido se reinician desde cero.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Volcado de memoria previo a la compactación`},help:{"v1-18q0ve9-55":`Ajustes del volcado de memoria previo a la compactación, que hacen que el agente escriba en la memoria antes de una compactación intensiva. Mantén esta opción activada en sesiones largas para guardar el contexto relevante antes de un recorte agresivo.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Guardado de memoria previo a la compactación activado`},help:{"v1-9xllgp-5o":`Activa el guardado de memoria previo a la compactación antes de que el entorno de ejecución realice una reducción más intensa del historial al acercarse a los límites de tokens. Mantenga esta opción activada, salvo que desee desactivar los efectos secundarios sobre la memoria en entornos con recursos limitados.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`Umbral de tamaño de la transcripción para el guardado de memoria previo a la compactación`},help:{"v1-1rzov1e-93":`Fuerza el guardado de memoria previo a la compactación cuando la ventana de transcripción visible para el modelo alcanza este umbral (en bytes o cadenas como "2mb"). Después de la compactación, esto incluye el tramo final conservado y los turnos posteriores, en lugar del historial descartado. Use esta opción para evitar bloqueos en sesiones largas incluso cuando los contadores de tokens estén desactualizados; establezca el valor en 0 para desactivarla.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`Modelo alternativo para el guardado de memoria previo a la compactación`},help:{"v1-1r3ctyu-7w":`Configuración opcional de proveedor/modelo que se usa únicamente en los turnos de guardado de memoria previos a la compactación. Establezca un modelo local como ollama/qwen3:8b cuando la extracción de memoria persistente deba evitar el modelo de pago de la sesión activa. Esta configuración se aplica de forma exacta y no hereda la cadena de modelos de respaldo del modelo activo.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Umbral flexible para el guardado de memoria previo a la compactación`},help:{"v1-1dqo2l1-5c":`Margen hasta la compactación (en tokens) que activa la ejecución del guardado de memoria previo a la compactación. Use umbrales más anticipados para una persistencia más segura, o umbrales más ajustados para reducir la frecuencia de guardado.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Comprobación previa de compactación durante el turno`},help:{"v1-am6gbh-6x":`Comprobación previa opcional del bucle de herramientas integrado de OpenClaw que detecta la presión sobre el contexto después de añadir el resultado de una herramienta y antes de la siguiente llamada al modelo. Cuando está habilitada, OpenClaw reutiliza el mecanismo de recuperación de la comprobación previa existente para truncar los resultados de las herramientas o compactar antes de reintentar.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Comprobación previa de compactación durante el turno habilitada`},help:{"v1-engbwe-5u":`Habilita las comprobaciones estructuradas de presión sobre el contexto durante el turno para los bucles de herramientas integrados de OpenClaw. Valor predeterminado: false. Mantén esta opción deshabilitada, salvo que las sesiones largas con uso intensivo de herramientas excedan el límite de contexto antes de que pueda ejecutarse la compactación habitual al final del turno.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Modo de compactación`},help:{"v1-1unahwc-76":`Modo de estrategia de compactación: "safeguard" (el valor predeterminado efectivo cuando no se especifica) aplica medidas de protección para conservar el contexto reciente, mientras que "default" utiliza un resumen básico sin ellas. Establece "default" solo si el resumen con medidas de protección causa problemas con tu proveedor.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Modelo alternativo para compactación`},help:{"v1-cfeys9-6q":`Proveedor/modelo opcional o alias sin prefijo configurado que se utiliza únicamente para generar resúmenes de compactación. Los alias sin prefijo se resuelven antes del envío; un ID de modelo literal configurado tiene prioridad si coincide con un alias. Déjalo sin especificar para seguir utilizando el modelo principal del agente.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Notificar al usuario sobre la compactación`},help:{"v1-lvymm8-bv":`Cuando está activado, envía al usuario avisos breves sobre el mantenimiento del contexto: cuando la compactación comienza y termina (por ejemplo, '🧹 Compactando el contexto...' y '🧹 Compactación completada'), y cuando se agotan los intentos de volcado de memoria previo a la compactación y la respuesta continúa en un estado degradado (por ejemplo, '⚠️ El mantenimiento de la memoria ha fallado temporalmente; continuamos con tu respuesta.'). Está desactivado de forma predeterminada para que el mantenimiento del contexto sea silencioso y no intrusivo.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Secciones de contexto posteriores a la compactación`},help:{"v1-1n0ln2u-5f":`Nombres de las secciones H2/H3 de AGENTS.md que se reinsertan tras la compactación si se habilita esta opción. Deja el valor sin configurar o establece [] para desactivar la reinserción. Establece explícitamente ["Session Startup", "Red Lines"] para habilitar el par predeterminado anterior.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Sincronización del índice tras la compactación`},help:{"v1-ekpjeq-6l":`Controla el modo de reindexación de la memoria de la sesión tras la compactación: "off", "async" o "await" (predeterminado: "async"). Usa "await" para garantizar la máxima actualización, "async" para reducir la latencia de compactación y "off" solo cuando la sincronización de la memoria de la sesión se gestione por otro medio.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Proveedor de compactación`},help:{"v1-kiwk91-86":`Identificador de un complemento proveedor de compactación registrado que se utiliza para generar resúmenes. Si se configura y el proveedor está registrado, se llama a su método summarize() en lugar de usar el flujo integrado summarizeInStages. Si el proveedor falla, se recurre a la función integrada. Deja el valor sin configurar para usar la generación de resúmenes integrada predeterminada.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Control de calidad de la compactación`},help:{"v1-u9ognp-4k":`Configuración de reintentos de auditoría de calidad para los resúmenes de compactación en modo de protección. El modo de protección activa esta función de forma predeterminada; establece enabled: false para omitir las auditorías y la regeneración de resúmenes.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Control de calidad de compactación activado`},help:{"v1-1xk2vt3-36":`Activa las auditorías de calidad de los resúmenes y los reintentos de regeneración para la compactación en modo de protección. Valor predeterminado: true en modo de protección.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Máximo de reintentos del control de calidad de compactación`},help:{"v1-n7l46y-3y":`Número máximo de reintentos de regeneración tras una auditoría de calidad fallida de un resumen en modo de protección. Usa valores bajos para limitar la latencia adicional y el coste de tokens.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Turnos recientes que conservar en la compactación`},help:{"v1-y34ihi-5k":`Número de turnos más recientes del usuario y del asistente que se conservan textualmente sin incluirlos en el resumen del modo de protección (valor predeterminado: 3). Aumenta este valor para conservar el contexto exacto del diálogo reciente o redúcelo para maximizar el ahorro de la compactación.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Nivel de razonamiento de compactación`},help:{"v1-1vafgaw-g1":`Nivel de razonamiento utilizado solo para los resúmenes de compactación integrados de OpenClaw: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" o "inherit". De forma predeterminada, se usa la preferencia de compactación del proveedor o, en su defecto, "low"; la integración nativa local de Ollama prefiere "off". Establece "inherit" para reutilizar el nivel de la sesión. Los ajustes explícitos prevalecen sobre los valores predeterminados del proveedor, y el nivel seleccionado se limita a lo que admiten el modelo y el entorno de ejecución de compactación reales. La compactación nativa de Codex app-server ignora este ajuste porque su solicitud de compactación no permite modificar el nivel de razonamiento por operación, y OpenClaw registra una advertencia.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Tiempo de espera de compactación (segundos)`},help:{"v1-2bhn29-7m":`Plazo de seguridad en segundos para cada solicitud al modelo de compactación integrado (predeterminado: 180). La compactación en varias etapas renueva el plazo al iniciar cada solicitud secuencial, por lo que la compactación completa puede tardar más; la compactación gestionada por un complemento recibe un único plazo para toda la operación.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Inyección de contexto`},help:{"v1-u18x0-7u":`Controla la inyección de archivos de inicialización del espacio de trabajo en el entorno de ejecución integrado: "always" usa la inyección normal (opción predeterminada), "continuation-skip" omite los turnos de continuación aptos después de un turno registrado de inicialización completa y "never" desactiva la inyección. No controla la preparación de prompts mediante CLI.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Límites de contexto predeterminados`},help:{"v1-1coeez8-5d":`Valores predeterminados específicos del presupuesto de contexto de cada agente para determinados fragmentos de gran volumen y bloques de prompt inyectados. Úsalos para ajustar los tamaños limitados de lectura e inyección sin volver a habilitar rutas de llamadas sin límites.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Máximo predeterminado de caracteres de memory_get`},help:{"v1-1qb40qv-4v":`Número máximo predeterminado de caracteres devueltos por memory_get antes de añadir los metadatos de truncamiento y el aviso de continuación. Auméntalo para aproximarte a los fragmentos más extensos de versiones anteriores, pero mantén un límite.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Máximo predeterminado de caracteres tras la compactación`},help:{"v1-64qo8g-5r":`Número máximo predeterminado de caracteres conservados de AGENTS.md durante la inyección de actualización del contexto tras la compactación. Redúcelo para disminuir el coste de la recuperación tras la compactación, o auméntalo para los agentes que dependan de instrucciones de inicio más extensas.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Directorio de trabajo`},help:{"v1-1y8wlxn-6a":`Directorio de trabajo para las ejecuciones de respuesta del agente, independiente de los archivos de inicialización y memoria del espacio de trabajo. El cwd específico del agente y el cwd de las sesiones generadas tienen prioridad. Admite ~ y rutas relativas; un cwd distinto requiere una ejecución fuera del entorno aislado.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Modelo de decisión`},help:{"v1-7nd7ze-64":`Proveedor/modelo opcional para elecciones tipadas, puntuaciones y probabilidades booleanas. Si no se configura o se deja vacío, se desactivan las llamadas de decisión. Los complementos compatibles envían a este proveedor un conjunto limitado de datos de la tarea; los modelos de chat y de utilidad no cambian.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`OpenClaw integrado`},help:{"v1-1keek32-3k":`Controles de refuerzo de seguridad del ejecutor de OpenClaw integrado que determinan cómo se confía en la configuración del agente local al espacio de trabajo y cómo se aplica en las sesiones de OpenClaw.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Conmutación por error por políticas de ciberseguridad`},help:{"v1-xvv6wl-2r":`Escalamiento automático a Daybreak ante rechazos por políticas de ciberseguridad de OpenAI que permiten reintentos seguros en el entorno de ejecución integrado.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Tiempo de espera de la conmutación por error por políticas de ciberseguridad`},help:{"v1-16smtrl-25":`Durante cuánto tiempo se omite un destino de escalamiento no disponible en la sesión actual.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Modo de conmutación por error por políticas de ciberseguridad`},help:{"v1-rzsd2b-2h":`Activa el escalamiento automático ("auto", predeterminado) o mantén los rechazos del proveedor como definitivos ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`Modelo de conmutación por error por políticas de ciberseguridad`},help:{"v1-1aaj8nn-1t":`Proveedor/modelo de destino utilizado para el escalamiento automático por políticas de ciberseguridad.`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Contrato de ejecución de OpenClaw integrado`},help:{"v1-1fch2ig-66":`Contrato de ejecución de OpenClaw integrado: "default" mantiene el comportamiento estándar del ejecutor, mientras que "strict-agentic" habilita el seguimiento estructurado de planes y la recuperación no visible de turnos para las ejecuciones compatibles de la familia GPT-5 de OpenAI/OpenAI Codex.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Política de configuración del proyecto de OpenClaw integrado`},help:{"v1-fdyy04-65":'Cómo gestiona OpenClaw integrado el archivo `.openclaw/settings.json` local del espacio de trabajo: "sanitize" (predeterminado) elimina shellPath/shellCommandPrefix, "ignore" desactiva por completo la configuración del proyecto y "trusted" aplica la configuración del proyecto tal cual.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Opciones experimentales del agente`},help:{"v1-cvv5cl-2w":`Opciones experimentales predeterminadas del agente. Manténgalas desactivadas salvo que esté probando deliberadamente una funcionalidad preliminar.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Activar el modo ligero de modelo local (experimental)`},help:{"v1-gj06u6-7b":`Ajuste avanzado de resolución de problemas que restringe herramientas opcionales como browser, automations y message. Está desactivado de forma predeterminada; los entornos de ejecución locales compatibles usan Tool Search automáticamente sin esta restricción. Se mantienen los permisos explícitos de herramientas y las herramientas de entrega obligatorias.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Modo rápido predeterminado del agente`},help:{"v1-zv4y98-2z":`Política predeterminada del modo rápido para el bucle del agente ("auto", true o false). Las entradas de cada agente tienen prioridad sobre ella.`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`Agente de latidos`},help:{"v1-1jynxej-3w":`Agente responsable de las ejecuciones de latidos en segundo plano cuando no existe una configuración de latidos por agente. Déjelo sin definir para conservar el enrutamiento predeterminado configurado.`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Política de entrega directa de latidos`},help:{"v1-nhyxa9-41":`Controla si la entrega de latidos puede dirigirse a chats directos o privados: "allow" (predeterminado) permite la entrega de mensajes privados y "block" impide los envíos a destinos directos.`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Tiempo de espera del latido (segundos)`},help:{"v1-1se21py-5f":`Tiempo máximo en segundos permitido para un turno del agente de latido antes de cancelarlo. Déjelo sin definir para usar agents.defaults.timeoutSeconds si está configurado; de lo contrario, se usará el intervalo de latido con un límite de 600 segundos.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Retraso humano máximo (ms)`},help:{"v1-vnmvli-1m":`Retraso máximo en ms para humanDelay personalizado (predeterminado: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Retraso humano mínimo (ms)`},help:{"v1-5nrtr5-1l":`Retraso mínimo en ms para humanDelay personalizado (predeterminado: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Modo de retraso humano`},help:{"v1-k7hyg3-1n":`Estilo de retraso para respuestas por bloques ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Dimensión máxima de imagen (px)`},help:{"v1-vju8x-2u":`Longitud máxima del lado de la imagen en píxeles al sanear los datos de imágenes de transcripciones o resultados de herramientas (predeterminado: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Modelos de imagen alternativos`},help:{"v1-1kgx5i9-1b":`Modelos de imagen alternativos en orden de prioridad (proveedor/modelo).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Modelo de imagen`},help:{"v1-dstqyh-2c":`Modelo de imagen opcional (proveedor/modelo) que se usa cuando el modelo principal no admite imágenes como entrada.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Calidad de imagen`},help:{"v1-1uyxc5s-6u":`Preferencia de compresión de medios de la herramienta de imágenes: "auto" se adapta a los límites del proveedor/modelo y a la cantidad de imágenes, "efficient" ahorra tokens y bytes, "balanced" mantiene el equilibrio actual y "high" conserva más detalles en capturas de pantalla e imágenes de documentos.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Modelos alternativos de generación de imágenes`},help:{"v1-oljfk4-1m":`Modelos alternativos de generación de imágenes por orden de prioridad (proveedor/modelo).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Modelo de generación de imágenes`},help:{"v1-g4yw0h-2o":`Modelo opcional de generación de imágenes (proveedor/modelo) que utiliza la función compartida de generación de imágenes.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Tiempo de espera de generación de imágenes (ms)`},help:{"v1-9yesfj-31":`Tiempo de espera predeterminado de las solicitudes al proveedor, en milisegundos, para las llamadas a image_generate. El valor de timeoutMs de cada llamada sustituye este valor.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Modelos alternativos de generación de música`},help:{"v1-wyg9xe-1m":`Modelos alternativos de generación de música por orden de prioridad (proveedor/modelo).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Modelo de generación de música`},help:{"v1-xs1e2h-2o":`Modelo opcional de generación de música (proveedor/modelo) que utiliza la función compartida de generación de música.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Modelos alternativos de generación de vídeo`},help:{"v1-wpbf1e-1m":`Modelos alternativos de generación de video en orden de prioridad (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Modelo de generación de video`},help:{"v1-hfmlbl-2o":`Modelo opcional de generación de video (provider/model) utilizado por la función compartida de generación de video.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Tiempo de espera de generación de video (ms)`},help:{"v1-1bqj80s-4i":`Tiempo de espera predeterminado de las solicitudes al proveedor, en milisegundos, para las llamadas a video_generate. El valor de timeoutMs de cada llamada tiene prioridad sobre este valor, y este valor tiene prioridad sobre los valores predeterminados definidos por el proveedor.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Modelos alternativos`},help:{"v1-t4djq2-24":`Modelos alternativos en orden de prioridad (provider/model). Se utilizan cuando falla el modelo principal.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Modelo principal`},help:{"v1-1i8a1v4-v":`Modelo principal (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Política de modelos`},help:{"v1-z0txb7-2e":`Política explícita para la sustitución de modelos. Omítala o deje allow vacío para permitir cualquier modelo.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Modelos permitidos`},help:{"v1-1fqace-3x":`Referencias de modelos permitidos para sustituciones. Acepta alias, referencias completas "provider/model" y comodines de proveedor como "openai/*". Si se deja vacío, permite cualquier modelo.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Modelos`},help:{"v1-13cvq23-4i":`Catálogo de modelos configurados y ajustes por modelo. Las entradas proporcionan alias, parámetros, metadatos de ejecución y ajustes específicos de Code Mode; no restringen las sustituciones de modelos.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Entorno de ejecución del modelo del agente predeterminado`},help:{"v1-6km9kx-41":`Política de ejecución opcional por modelo para el agente predeterminado. Úsala para definir excepciones de ejecución específicas de cada modelo en lugar de configurar un entorno de ejecución para todo el agente.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`ID del entorno de ejecución del modelo del agente predeterminado`},help:{"v1-1co96w7-4a":`ID del entorno de ejecución del modelo del agente predeterminado: "openclaw", "auto", un ID de arnés de plugin registrado como "codex", o un alias de backend de CLI compatible como "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Modo de código`},help:{"v1-rsdl5o-6x":`Modo de código de OpenClaw para este proveedor/modelo exacto: Activado fuerza su activación, Desactivado lo deshabilita y Predeterminado hereda tools.codeMode.enabled. Los ajustes de activación específicos del agente tienen prioridad. Esto no cambia el entorno de ejecución seleccionado ni el modo de código nativo de Codex.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Ámbito de selección del modelo`},help:{"v1-sj8owq-bl":`Ámbito de los comandos de chat y las actualizaciones del modelo de sesión de Gateway sin un ámbito explícito: "session" (predeterminado) cambia solo la sesión actual, "agent" también actualiza el modelo principal de ese agente y "global" también actualiza el modelo de respaldo compartido agents.defaults.model. Los indicadores de ámbito explícitos tienen prioridad; los cambios en los valores predeterminados configurados requieren permisos de propietario o administrador. Los selectores de las devoluciones de llamada de Telegram y la TUI local integrada siguen limitados a la sesión.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Tamaño máximo del PDF (MB)`},help:{"v1-1uig1dr-1u":`Tamaño máximo del archivo PDF en megabytes para la herramienta de PDF (predeterminado: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Máximo de páginas del PDF`},help:{"v1-11na7hp-1y":`Número máximo de páginas PDF que procesará la herramienta de PDF (predeterminado: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Modelos alternativos para PDF`},help:{"v1-89ebd8-19":`Modelos alternativos para PDF en orden de prioridad (proveedor/modelo).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`Modelo para PDF`},help:{"v1-2ktkxt-2y":`Modelo opcional para PDF (proveedor/modelo) para la herramienta de análisis de PDF. De forma predeterminada, se usa imageModel y, en su defecto, el modelo de la sesión.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Raíz del repositorio`},help:{"v1-j3sh74-2h":`Raíz opcional del repositorio que se muestra en la línea de información de ejecución del prompt del sistema (anula la detección automática).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Rango de puertos de origen CDP del navegador del entorno aislado`},help:{"v1-1jkowdc-2b":`Lista opcional de rangos CIDR permitidos para el tráfico CDP entrante en el límite del contenedor (por ejemplo, 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Red del navegador del entorno aislado`},help:{"v1-8m74ud-5w":`Red de Docker para los contenedores del navegador del entorno aislado (predeterminada: openclaw-sandbox-browser). Use la red dedicada predeterminada o una red de puente personalizada; "none" no es compatible porque el control del navegador requiere puertos CDP publicados.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Permitir la unión al espacio de nombres de otro contenedor en Docker del entorno aislado`},help:{"v1-qm39de-4c":`Excepción de emergencia PELIGROSA que permite el modo de red container:<id> de Docker en el entorno aislado. Esto une el contenedor al espacio de nombres de otro contenedor y debilita el aislamiento.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`GPU de Docker en el entorno aislado`},help:{"v1-jj0yhw-4k":`Valor opcional de acceso directo a GPU de Docker que se pasa a --gpus, por ejemplo, "all" o "device=GPU-uuid". Requiere un entorno de ejecución compatible en el host, como NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Destino del almacén de sesiones heredado`},help:{"v1-1xkej6i-2g":`Propietario de compatibilidad durante la actualización para las filas retiradas del agente principal y los almacenes de sesiones heredados fijos.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Propietario del almacén de sesiones heredado`},help:{"v1-ommm7e-5w":`Agente propietario de las filas retiradas del agente principal o de las filas sin ámbito en un almacén de sesiones heredado fijo tras la retirada del marcador predeterminado. Se escribe automáticamente durante la actualización cuando el propietario anterior no era main ni el único agente.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Lista opcional de habilidades permitidas por defecto que heredan los agentes que omiten agents.entries.*.skills. Omítala para permitir habilidades sin restricciones, establezca [] para que los agentes que la hereden no tengan habilidades y recuerde que una configuración explícita de agents.entries.*.skills sustituye este valor predeterminado en lugar de combinarse con él.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Omitir la creación de archivos de inicialización del espacio de trabajo`},help:{"v1-kbstgw-5v":`Omite la creación automática de archivos de inicialización del espacio de trabajo, no la inyección de archivos existentes. Para el entorno de ejecución integrado, establece agents.defaults.contextInjection en "never" para desactivar la inyección, salvo que se anule esta configuración para un agente específico.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Archivos opcionales de inicialización omitidos`},help:{"v1-1j2z4yj-4c":`Archivos opcionales de inicialización que no deben crearse en los espacios de trabajo de los agentes. Valores válidos: SOUL.md, USER.md, IDENTITY.md (se acepta HEARTBEAT.md, pero no tiene ningún efecto).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Contexto de inicio`},help:{"v1-1ugsihy-5o":`Preámbulo del primer turno gestionado por el entorno de ejecución para "/new" y "/reset" sin argumentos. Úsalo para controlar si los archivos recientes de memoria diaria se precargan en el primer prompt, en lugar de pedirle al modelo que decida qué leer.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Aplicar contexto de inicio a`},help:{"v1-wav4a5-36":`Elige qué comandos de reinicio sin argumentos reciben el contexto de inicio: incluye "new", "reset" o ambos (valor predeterminado: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Días de memoria diaria del contexto de inicio`},help:{"v1-4i5xcm-3p":`Número de archivos de memoria fechados que se cargarán contando hacia atrás desde hoy en la zona horaria configurada del usuario (valor predeterminado: 2, para hoy y ayer).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Activar contexto de inicio`},help:{"v1-1d5vz2u-4i":`Activa el preámbulo de contexto de inicio para los reinicios de sesión sin argumentos (valor predeterminado: true). Desactívalo para volver al comportamiento basado únicamente en el prompt, sin memoria diaria cargada por el entorno de ejecución.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Máximo de bytes por archivo del contexto de inicio`},help:{"v1-11cbian-41":`Máximo de bytes permitidos por archivo de memoria diaria al crear el contexto de inicio (valor predeterminado: 16384). Se omiten los archivos que superan este límite de lectura segura.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Máximo de caracteres por archivo del contexto de inicio`},help:{"v1-10z53s-2u":`Máximo de caracteres conservados de cada archivo de memoria diaria cargado en el preámbulo de inicio (valor predeterminado: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Máximo total de caracteres del contexto de inicio`},help:{"v1-sf676u-54":`Número máximo total de caracteres conservados entre todos los archivos de memoria diaria cargados en el preámbulo de inicio (predeterminado: 2800). Los archivos adicionales se truncan en el preámbulo una vez alcanzado este límite.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Modo de delegación a subagentes`},help:{"v1-pqewbk-5o":`Nivel de insistencia en la delegación a subagentes, aplicado solo mediante el prompt. El valor predeterminado es "prefer" en la sesión principal de cada agente y "suggest" en las demás; "prefer" indica firmemente al agente que delegue el trabajo no trivial mediante sessions_spawn.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Destino del agente del sistema`},help:{"v1-1wwimo9-34":`Configuración de destino para la inferencia en segundo plano del agente del sistema de OpenClaw y de Custodian, además de determinadas consultas de lectura del operador sin ámbito específico.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Propietario del agente del sistema`},help:{"v1-15rvt92-8c":`Agente cuyo modelo y credenciales se usan para las consultas en segundo plano del agente del sistema y de Custodian. También se usa cuando models.list, models.authStatus, skills.status, doctor.memory.status o un comando de la CLI infer que resuelve el modelo o el estado de autenticación del agente omiten agentId o --agent; el agentId explícito de la solicitud siempre tiene prioridad.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Intervalo del indicador de escritura (segundos)`},help:{"v1-1y701ox-42":`Controla la frecuencia de actualización, en segundos, que mantiene activo el indicador de escritura de cada agente. Aumente este valor para reducir la frecuencia de actualización en todos los canales que admiten indicadores de escritura.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Modo del indicador de escritura`},help:{"v1-m2hvpw-3m":`Controla cuándo se activa el indicador de escritura de los agentes: "never", "instant", "thinking" o "message". El valor de typingMode de cada agente anula este valor predeterminado.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Modelo auxiliar`},help:{"v1-1wg7h1a-7s":`Modelo opcional de menor coste (provider/model o alias) para tareas internas breves, como la generación de títulos y la descripción del progreso. Si no se configura, se utiliza el modelo pequeño declarado por el proveedor principal, si está disponible (de lo contrario, el modelo principal); establece una cadena vacía para desactivar el enrutamiento al modelo auxiliar.`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Modelos de voz alternativos`},help:{"v1-faazv4-1b":`Modelos de voz alternativos en orden de prioridad (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Modelo de voz`},help:{"v1-1yeh3h4-2t":`Modelo de voz opcional (provider/model) utilizado por las funciones de síntesis de voz, transcripción y voz en tiempo real.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Tiempo de espera de voz (ms)`},help:{"v1-1sbergs-32":`Tiempo de espera predeterminado de las solicitudes al proveedor, en milisegundos, para las operaciones del modelo de voz cuando el componente que realiza la llamada admite tiempos de espera.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Espacio de trabajo`},help:{"v1-1lssx8l-5w":`Espacio de trabajo predeterminado del agente para los archivos de inicialización y memoria. También se utiliza como directorio de trabajo cuando agents.defaults.cwd no está configurado. Configúralo explícitamente al ejecutar desde envoltorios para que la resolución de rutas siga siendo determinista.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Lista de agentes`},help:{"v1-yurood-5l":`Lista explícita de agentes configurados con identificadores y ajustes opcionales de modelo, herramientas, identidad y espacio de trabajo. Mantén los identificadores estables a lo largo del tiempo para que las vinculaciones, las aprobaciones y el enrutamiento de sesiones sigan siendo deterministas.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Entorno de ejecución heredado del agente`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`ID del entorno de ejecución heredado del agente`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Máximo de caracteres de inicialización del agente`},help:{"v1-rsf1es-4j":`Valor específico por agente para el máximo de caracteres de cada archivo de inicialización del espacio de trabajo que se inserta en el prompt del sistema de este agente. Omítelo para heredar agents.defaults.bootstrapMaxChars.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Máximo total de caracteres de inicialización del agente`},help:{"v1-1bal68p-4y":`Valor específico por agente para el máximo total de caracteres de todos los archivos de inicialización del espacio de trabajo que se insertan en el prompt del sistema de este agente. Omítelo para heredar agents.defaults.bootstrapTotalMaxChars.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Inserción de contexto del agente`},help:{"v1-1j68ys8-50":`Configuración específica por agente para la inyección de archivos de inicialización del espacio de trabajo en el entorno de ejecución integrado. Omítela para heredar agents.defaults.contextInjection. No controla la preparación de prompts mediante la CLI.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Límites de contexto del agente`},help:{"v1-f1qxq8-3c":`Valores opcionales específicos por agente para los parámetros del presupuesto de contexto focalizado. Los campos omitidos heredan agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Máximo de caracteres de memory_get del agente`},help:{"v1-12hlmsv-1v":`Valor específico por agente para el presupuesto máximo predeterminado de caracteres de memory_get.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Máximo de caracteres del agente tras la compactación`},help:{"v1-15s0npd-1w":`Ajuste por agente del límite de longitud del extracto de AGENTS.md tras la compactación.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Directorio de trabajo del agente`},help:{"v1-mv43ak-6a":`Directorio de trabajo para las ejecuciones de respuesta de este agente. Tiene prioridad sobre agents.defaults.cwd, pero no sobre el cwd definido al crear la sesión; los archivos de inicialización y memoria permanecen en el espacio de trabajo. Admite ~ y rutas relativas; un cwd distinto requiere una ejecución fuera del entorno aislado.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Modelo de decisión del agente`},help:{"v1-1mih8bf-3j":`Modelo de decisión por agente. Si no se configura, se hereda agents.defaults.decisionModel; una cadena vacía desactiva las llamadas de decisión para este agente.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`OpenClaw integrado del agente`},help:{"v1-uoomza-4b":`Ajustes opcionales por agente de OpenClaw integrado. Permiten activar un comportamiento de ejecución de GPT-5 más estricto para agentes específicos sin cambiar el valor predeterminado global.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Contrato de ejecución de OpenClaw integrado del agente`},help:{"v1-1d1jaoi-7k":`Ajuste opcional por agente del contrato de ejecución de OpenClaw integrado. Establece "strict-agentic" para habilitar el seguimiento estructurado del plan y la recuperación no visible de turnos para ese agente en ejecuciones compatibles de la familia GPT-5 de OpenAI/OpenAI Codex, o "default" para heredar el comportamiento estándar del ejecutor.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Opciones experimentales del agente`},help:{"v1-1r06jov-2a":`Opciones experimentales por agente. Los campos omitidos heredan agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Modo ligero de modelo local del agente`},help:{"v1-5o3tgx-58":`Ajuste de resolución de problemas por agente para el modo reducido de modelos locales. Actívalo solo cuando restringir las herramientas opcionales resuelva un fallo comprobado del modelo, sin reducir las herramientas de todos los agentes.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Modo rápido predeterminado del agente`},help:{"v1-1ujydjc-3o":`Valor predeterminado opcional por agente para el modo rápido ("auto", true o false). Se aplica cuando no se ha establecido una anulación del modo rápido para el mensaje o la sesión.`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Política de entrega directa de latidos`},help:{"v1-11gl9l0-41":`Anulación por agente de la política de entrega de latidos mediante mensajes directos; usa "block" para los agentes que solo deban enviar alertas de latido a destinos que no sean mensajes directos.`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Tiempo de espera de latidos (segundos)`},help:{"v1-kdetv4-6s":`Tiempo máximo por agente, en segundos, permitido para un turno de latido del agente antes de que se cancele. Déjalo sin establecer para heredar el tiempo de espera de latidos combinado; en su defecto, se usa agents.defaults.timeoutSeconds si está establecido y, de lo contrario, el intervalo de latidos con un límite de 600 segundos.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Avatar de identidad`},help:{"v1-pzp9gr-1t":`Avatar del agente (ruta relativa al espacio de trabajo, URL http(s) o URI de datos).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Política de modelos del agente`},help:{"v1-17d5je8-2r":`Política de anulación de modelos por agente. Una lista explícita de modelos permitidos reemplaza la política predeterminada de este agente.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Modelos permitidos del agente`},help:{"v1-v1ueke-5b":`Referencias de modelos permitidas para las anulaciones de este agente. Acepta alias, referencias completas "provider/model" y prefijos con comodines al final, como "provider/*" o "provider/namespace/*"; si está vacío, permite cualquier modelo.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Anulaciones de modelos del agente`},help:{"v1-nld1vq-1v":`Anulaciones del catálogo de modelos por agente, indexadas por los ID completos de proveedor/modelo.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Entorno de ejecución del modelo del agente`},help:{"v1-7b59y-3s":`Política opcional de entorno de ejecución por modelo para este agente. Úsela para establecer excepciones de modelo específicas del agente en lugar de configurar un entorno de ejecución para todo el agente.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`ID del entorno de ejecución del modelo del agente`},help:{"v1-1ckfc39-46":`ID del entorno de ejecución del modelo por agente: "openclaw", "auto", un ID de adaptador de plugin registrado como "codex" o un alias de backend de CLI compatible como "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Modo de código`},help:{"v1-91zu7f-7m":`Modo de código de OpenClaw para este agente y el proveedor/modelo exacto: Activado fuerza su activación, Desactivado lo desactiva y Predeterminado hereda primero la configuración de activación del agente, después la anulación compartida del modelo y, por último, tools.codeMode.enabled. Esto no cambia el entorno de ejecución seleccionado ni el modo de código nativo de Codex.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Visibilidad predeterminada del razonamiento del agente`},help:{"v1-13ly0xf-3m":`Visibilidad predeterminada opcional del razonamiento por agente (on|off|stream). Se aplica cuando no se ha establecido ninguna anulación del razonamiento por mensaje o sesión.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Entorno de ejecución del agente`},help:{"v1-avjgkf-3l":`Descriptor opcional del entorno de ejecución para este agente. Use embedded para la ejecución predeterminada de OpenClaw o acp para los valores predeterminados del adaptador ACP externo.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Entorno de ejecución ACP del agente`},help:{"v1-91zvdk-3i":`Valores predeterminados del entorno de ejecución ACP para este agente cuando runtime.type=acp. Las anulaciones de ACP a nivel de vinculación siguen teniendo prioridad en cada conversación.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Agente del arnés ACP para este agente`},help:{"v1-1pm98vp-37":`ID opcional del agente del arnés ACP que se usará para este agente de OpenClaw (por ejemplo, codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Backend ACP del agente`},help:{"v1-1u3cdsg-2n":`Anulación opcional del backend ACP para las sesiones ACP de este agente (si no se especifica, se usa el valor global de acp.backend).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Directorio de trabajo ACP del agente`},help:{"v1-d9p9rf-1t":`Directorio de trabajo predeterminado opcional para las sesiones ACP de este agente.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Modo ACP del agente`},help:{"v1-yatuk4-21":`Modo de sesión ACP predeterminado opcional para este agente (persistent u oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Tipo de entorno de ejecución del agente`},help:{"v1-139fbk6-2r":`Tipo de entorno de ejecución para este agente: "embedded" (entorno de ejecución predeterminado de OpenClaw) o "acp" (valores predeterminados del arnés ACP).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`Rango de origen CDP del navegador del entorno aislado del agente`},help:{"v1-1q1qyso-1d":`Anulación por agente de la lista de rangos CIDR de origen permitidos para CDP.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Red del navegador del entorno aislado del agente`},help:{"v1-13bdfww-4c":`Configuración específica por agente de la red Docker del navegador del entorno aislado. Usa una red de puente; "none" no es compatible porque el control del navegador requiere puertos CDP publicados.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Permitir la unión al espacio de nombres de un contenedor en Docker del entorno aislado del agente`},help:{"v1-1xtnseb-2i":`Configuración específica por agente PELIGROSA para unirse a espacios de nombres de contenedores en el modo de red Docker del entorno aislado.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`GPU de Docker del entorno aislado del agente`},help:{"v1-1kek1n2-1t":`Configuración específica por agente del acceso directo a GPU de Docker para los contenedores del entorno aislado.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Filtro de habilidades del agente`},help:{"v1-igchue-6v":`Lista opcional de habilidades permitidas para este agente. Si se omite, el agente hereda agents.defaults.skills cuando esté configurado; de lo contrario, las habilidades no tendrán restricciones. Establece [] para no permitir ninguna habilidad. Una lista explícita sustituye por completo los valores predeterminados heredados en lugar de combinarse con ellos.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Límites de Skills del agente`},help:{"v1-1sv10v9-4y":`Configuraciones específicas opcionales por agente para los límites de recursos del subsistema de habilidades. Úsalas cuando un agente necesite un límite distinto para el prompt de habilidades sin introducir una segunda vía genérica de límites de contexto.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Máximo de caracteres del prompt de Skills del agente`},help:{"v1-dys63y-52":`Anulación por agente del límite de caracteres del prompt de habilidades. Amplía la ruta existente skills.limits.maxSkillsPromptChars en lugar de gestionar el mismo límite mediante contextLimits.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Modo de delegación de subagentes`},help:{"v1-1rkgh6p-4s":`Anulación por agente del grado de preferencia por la delegación a subagentes. Omita este ajuste para usar "prefer" en la sesión principal de este agente y "suggest" en las demás; un valor explícito de "prefer" o "suggest" siempre tiene prioridad.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Nivel de razonamiento predeterminado del agente`},help:{"v1-173q7vy-43":`Nivel de razonamiento predeterminado opcional por agente. Sustituye agents.defaults.thinkingDefault para este agente cuando no se ha establecido una anulación por mensaje o sesión.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Adiciones a la lista de herramientas permitidas del agente`},help:{"v1-1550ui9-46":`Lista adicional de herramientas permitidas por agente que se suma a las políticas globales y de perfil. Manténgala limitada para evitar ampliar accidentalmente los privilegios de los agentes especializados.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Política de herramientas del agente por proveedor`},help:{"v1-mthxv9-4t":`Anulaciones de la política de herramientas por agente y proveedor para controlar las capacidades en el ámbito del canal. Use este ajuste cuando un agente necesite restricciones más estrictas para un proveedor que para los demás.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Modo de código del agente`},help:{"v1-118t8u5-65":`Opciones del modo de código por agente. Un valor explícito de enabled prevalece sobre los valores predeterminados de activación globales y del modelo compartido; una configuración específica de codeMode del modelo para el agente tiene prioridad. Las demás opciones se combinan con tools.codeMode sin cambiar la activación.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Tiempo de espera de ejecución del agente (segundos)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Configuración de identidad de GitHub CLI específica del agente`},help:{"v1-mjwdh4-38":`Configuración completa de la identidad administrada de GitHub CLI y del autor de Git específica de este agente. Omítala para heredar la identidad del sistema.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`Correo electrónico del autor de Git del agente`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Nombre del autor de Git del agente`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Tipo de credencial de GitHub del agente`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Versión del perfil de GitHub del agente`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Lista de acciones de mensajes permitidas del agente`},help:{"v1-1g5gov3-67":`Lista de acciones de mensajes permitidas por agente para la herramienta message. Establezca una lista mínima como ["send"] para los agentes públicos en entornos aislados, de modo que las acciones de lectura, edición, eliminación, reacción y otras acciones de mensajes específicas del proveedor permanezcan ocultas y bloqueadas.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Mensajería entre contextos del agente (entre proveedores)`},help:{"v1-pehesn-49":`Configuración por agente para permitir envíos entre proveedores. Hereda la configuración global (valor predeterminado: true). Establece el valor en false para bloquear los mensajes entre proveedores para este agente.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Mensajería del agente entre contextos (mismo proveedor)`},help:{"v1-s9u09h-4t":`Control de mensajes por agente para enviar a otras conversaciones del mismo proveedor. Establece tanto esta opción como allowAcrossProviders en false para los agentes públicos que deban limitarse a la conversación actual.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Perfil de herramientas del agente`},help:{"v1-1du76ix-57":`Configuración específica por agente para seleccionar el perfil de herramientas cuando un agente necesita un conjunto básico de capacidades diferente. Úsala con moderación para que las diferencias de políticas entre agentes sean deliberadas y se puedan revisar.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Enjambre del agente`},help:{"v1-420ljs-2c":`Configuración específica del enjambre por agente. Los valores se combinan con la configuración de nivel superior tools.swarm y tienen prioridad sobre ella.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Modo de escritura del agente`},help:{"v1-oxir52-2e":`Sustituye la política predeterminada de inicio del indicador de escritura para un agente sin modificar los demás.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Modelo auxiliar del agente`},help:{"v1-1v9oskz-2z":`Configuración opcional del modelo auxiliar por agente para tareas internas breves. Sustituye agents.defaults.utilityModel.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Generación de titularidad de agentes`},help:{"v1-m2hp61-8g":`Marcador persistente de generación de titularidad para múltiples agentes. "explicit" significa que los canales de entorno, los latidos, las consultas al agente del sistema, Talk, cron y las operaciones directas de CLI deben determinar un titular específico de la interfaz o bloquearse por seguridad. OpenClaw establece este marcador automáticamente al crear o migrar una flota; omítelo si hay un solo agente.`}},approvals:{label:{"v1-1m405m7-9":`Aprobaciones`},help:{"v1-4y3in-5w":`Controles de enrutamiento de aprobaciones para reenviar solicitudes de aprobación de exec y plugins a destinos de chat fuera de la sesión de origen. Mantén estos controles desactivados salvo que los operadores necesiten visibilidad explícita de las aprobaciones por un canal alternativo.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Reenvío de aprobaciones de exec`},help:{"v1-1r2mozk-5v":`Agrupa las opciones de reenvío de aprobaciones de exec, incluidas la activación, el modo de enrutamiento, los filtros y los destinos explícitos. Configura estas opciones cuando las solicitudes de aprobación deban llegar a los canales operativos y no solo al hilo de origen.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Filtro de agentes para aprobaciones`},help:{"v1-xbuhd3-5i":'Lista opcional de ID de agentes autorizados para el reenvío de aprobaciones, por ejemplo, `["primary", "ops-agent"]`. Úsala para limitar el alcance del reenvío y evitar notificaciones en canales sobre agentes no relacionados.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Reenviar aprobaciones de exec`},help:{"v1-1t0whe8-5s":`Activa el reenvío de solicitudes de aprobación de exec a los destinos de entrega configurados (valor predeterminado: false). Mantén esta opción desactivada en configuraciones de bajo riesgo y actívala solo cuando las personas encargadas de aprobar necesiten solicitudes visibles en los canales.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Modo de reenvío de aprobaciones`},help:{"v1-1dedfo4-69":`Controla adónde se envían las solicitudes de aprobación: "session" usa el chat de origen, "targets" usa los destinos configurados y "both" las envía por ambas vías. Usa "session" como opción base y amplía el alcance solo cuando el flujo de trabajo operativo requiera redundancia.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Filtro de sesiones para aprobaciones`},help:{"v1-smeg8e-5u":'Filtros opcionales de claves de sesión que coinciden por subcadena o mediante patrones de tipo expresión regular, por ejemplo `["discord:", "^agent:ops:"]`. Usa patrones específicos para que solo los contextos de aprobación previstos se reenvíen a destinos compartidos.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Destinos de reenvío de aprobaciones`},help:{"v1-17ah848-5u":`Destinos de entrega explícitos que se usan cuando el modo de reenvío incluye destinos, cada uno con los detalles del canal y del destino. Aplica el principio de mínimo privilegio a las listas de destinos y valida cada destino antes de habilitar el reenvío generalizado.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`ID de cuenta del destino de aprobaciones`},help:{"v1-16zopng-5e":`Selector de cuenta opcional para configuraciones de canales con varias cuentas cuando las aprobaciones deben enrutarse a través del contexto de una cuenta específica. Úsalo solo cuando el canal de destino tenga varias identidades configuradas.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Canal de destino de aprobaciones`},help:{"v1-ji1igl-59":`ID de canal o proveedor que se usa para entregar las aprobaciones reenviadas, como discord, slack o un ID de canal de un plugin. Usa solo IDs de canal válidos para evitar que las aprobaciones fallen silenciosamente debido a rutas desconocidas.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`ID de hilo del destino de aprobaciones`},help:{"v1-1axynw7-59":`Hilo o tema de destino opcional para canales que admiten la entrega de aprobaciones reenviadas en hilos. Úsalo para mantener el tráfico de aprobaciones en hilos operativos en lugar de en los canales principales.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Destino de entrega de aprobaciones`},help:{"v1-1ijng7e-5n":`Identificador de destino dentro del canal de destino (ID de canal, ID de usuario o raíz del hilo, según el proveedor). Verifica la semántica de cada proveedor, ya que el formato de destino varía entre las integraciones de canales.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Reenvío de aprobaciones de plugins`},help:{"v1-1m6pzxv-6b":`Agrupa el comportamiento de reenvío de aprobaciones de plugins, incluida la habilitación, el modo de enrutamiento, los filtros y los destinos explícitos. Es independiente del reenvío de aprobaciones de ejecución. Configura esta sección cuando las solicitudes de aprobación de plugins deban llegar a los canales operativos.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Filtro de agentes para aprobaciones de plugins`},help:{"v1-jb1bra-4b":'Lista opcional de IDs de agentes permitidos para el reenvío de aprobaciones de plugins, por ejemplo, `["primary", "ops-agent"]`. Úsala para limitar el alcance del reenvío.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Reenviar aprobaciones de plugins`},help:{"v1-1ntctaf-3v":`Habilita el reenvío de solicitudes de aprobación de plugins a los destinos de entrega configurados (valor predeterminado: false). Es independiente de approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Modo de reenvío de aprobaciones de plugins`},help:{"v1-1h62vy4-3z":`Controla adónde se envían las solicitudes de aprobación de plugins: "session" usa el chat de origen, "targets" usa los destinos configurados y "both" las envía por ambas vías.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Filtro de sesiones para aprobaciones de plugins`},help:{"v1-1eppxmt-57":'Filtros opcionales de claves de sesión que se comparan como subcadenas o patrones de expresiones regulares, por ejemplo, `["discord:", "^agent:ops:"]`. Usa patrones específicos para que solo se reenvíen los contextos de aprobación previstos.'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Destinos de reenvío de aprobaciones de plugins`},help:{"v1-o92qze-3k":`Destinos de entrega explícitos que se usan cuando el modo de reenvío de aprobaciones de plugins incluye destinos, cada uno con detalles del canal y del destino.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`ID de cuenta de destino de aprobaciones de plugins`},help:{"v1-1wf3lqn-3j":`Selector de cuenta opcional para configuraciones de canales con varias cuentas cuando las aprobaciones de plugins deben enrutarse a través del contexto de una cuenta específica.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Canal de destino de aprobaciones de plugins`},help:{"v1-1mzhzi9-34":`ID del canal o proveedor utilizado para entregar las aprobaciones de plugins reenviadas, como discord, slack o un ID de canal de plugin.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`ID del hilo de destino de aprobaciones de plugins`},help:{"v1-1scaw9c-2v":`Hilo o tema de destino opcional para los canales que admiten la entrega en hilos de aprobaciones de plugins reenviadas.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Destino de aprobaciones de plugins`},help:{"v1-sh5te1-31":`Identificador del destino dentro del canal de destino (ID del canal, ID del usuario o raíz del hilo, según el proveedor).`}},attachments:{label:{"v1-8925gh-b":`Archivos adjuntos`},help:{"v1-1xvgkss-40":`Comportamiento de retención de nivel superior compartido entre proveedores y herramientas que almacenan contenido multimedia de forma persistente. Usa ttlHours cuando el contenido multimedia preparado temporalmente necesite un plazo limitado de conservación.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`TTL de retención de archivos adjuntos (horas)`},help:{"v1-1g90day-9e":`Periodo de retención opcional, en horas, para los archivos multimedia persistidos que gestiona la limpieza general por mtime. Déjelo sin configurar para desactivar esa limpieza, o establezca valores como 24 (1 día) o 168 (7 días) para eliminar periódicamente los archivos multimedia preparados más antiguos. Los archivos multimedia salientes gestionados (adjuntos generados en el chat) quedan excluidos y siguen su propia política de retención basada en SQLite y en las transcripciones.`}},audio:{label:{"v1-11wczsp-5":`Audio`}},auth:{label:{"v1-5xz433-4":`Autenticación`},help:{"v1-1eu3aud-5c":`Raíz de los perfiles de autenticación utilizada para las credenciales de proveedores con varios perfiles y el orden de conmutación por error basado en periodos de espera. Mantenga los perfiles mínimos y explícitos para que el comportamiento de conmutación automática por error siga siendo auditable.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Orden de los perfiles de autenticación`},help:{"v1-1x6kknp-1w":`ID de perfiles de autenticación ordenados por proveedor (se utilizan para la conmutación automática por error).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Perfiles de autenticación`},help:{"v1-kzoqcn-1j":`Perfiles de autenticación con nombre (proveedor + modo + correo electrónico opcional).`}},bindings:{label:{"v1-1hcih9f-8":`Asignaciones`},help:{"v1-y7hrzb-4i":`Reglas de vinculación de nivel superior para el enrutamiento y la asignación persistente de conversaciones ACP. Use type=route para el enrutamiento normal y type=acp para las vinculaciones persistentes del entorno de ejecución ACP.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Ajustes de ACP específicos de la vinculación`},help:{"v1-1t4lisi-44":`Ajustes opcionales de ACP por vinculación para bindings[].type=acp. Esta capa sustituye los valores predeterminados de agents.entries.*.runtime.acp para la conversación coincidente.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`Backend de ACP de la vinculación`},help:{"v1-rsrbkp-2x":`Backend de ACP específico para esta vinculación (si no se especifica, se usa el backend de ACP del entorno de ejecución del agente y, después, el valor global de acp.backend).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Directorio de trabajo de ACP de la vinculación`},help:{"v1-ngpkj0-1y":`Directorio de trabajo alternativo para las sesiones ACP creadas a partir de esta vinculación.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Etiqueta de vinculación ACP`},help:{"v1-azce82-23":`Etiqueta descriptiva para el estado y los diagnósticos de ACP en esta conversación vinculada.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Modo de vinculación ACP`},help:{"v1-cgq8xv-1v":`Modo de sesión ACP alternativo para esta vinculación (persistent u oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`ID del agente de la vinculación`},help:{"v1-17ra0cl-4m":`ID del agente de destino que recibe el tráfico cuando se cumple la regla de coincidencia de la vinculación correspondiente. Usa solo ID de agentes configurados válidos para que el enrutamiento no falle durante la ejecución.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Regla de coincidencia de la vinculación`},help:{"v1-sc1w2e-51":`Objeto de regla de coincidencia que determina cuándo se aplica una vinculación, incluido el canal y las restricciones opcionales de cuenta o interlocutor. Define reglas específicas para evitar que un agente asuma el control accidentalmente en otros contextos.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`ID de cuenta de la vinculación`},help:{"v1-1d209g7-56":`Selector de cuenta opcional para configuraciones de canal con varias cuentas, de modo que la vinculación se aplique solo a una identidad. Úsalo cuando la ruta deba limitarse a una cuenta; de lo contrario, déjalo sin configurar.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Canal de la vinculación`},help:{"v1-d22m5-54":"Identificador del canal o proveedor al que se aplica esta vinculación, como `telegram`, `discord` o el ID de canal de un complemento. Usa exactamente la clave del canal configurada para que la evaluación de la vinculación funcione de forma fiable."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`ID del servidor de la vinculación`},help:{"v1-jzzfj1-4x":`Restricción opcional por ID de comunidad/servidor de tipo Discord para evaluar vinculaciones en implementaciones con varios servidores. Úsala cuando los mismos identificadores de interlocutor puedan aparecer en distintas comunidades.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Coincidencia de interlocutor de la vinculación`},help:{"v1-gcjxff-4i":`Criterio opcional de coincidencia de interlocutor para conversaciones específicas, que incluye el tipo y el ID del interlocutor. Úsalo cuando solo deba asignarse a un agente un destino directo, de grupo o de canal.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`ID de interlocutor de la vinculación`},help:{"v1-86fbh7-4b":`Identificador de conversación usado para la coincidencia de interlocutores, como un ID de chat, canal o grupo del proveedor. Mantén el valor exacto para evitar que se descarten coincidencias sin aviso.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Tipo de interlocutor de la vinculación`},help:{"v1-uufscp-4x":`Tipo de conversación del interlocutor: "direct", "group", "channel" o el valor heredado "dm" (alias obsoleto de direct). Usa preferentemente "direct" en configuraciones nuevas y mantén kind alineado con la semántica del canal.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Roles de la vinculación`},help:{"v1-6s891m-4k":`Lista opcional de filtros basados en roles que usan los proveedores que añaden roles al contexto del chat. Úsala para dirigir el tráfico de roles privilegiados u operativos a agentes especializados.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`ID de equipo de la vinculación`},help:{"v1-hh9ps2-48":`Restricción opcional por ID de equipo/espacio de trabajo que usan los proveedores que agrupan los chats por equipos. Añádela cuando necesites limitar las vinculaciones al contexto de un único espacio de trabajo.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Sesión de la vinculación`},help:{"v1-x325l2-4v":`Ajustes opcionales de sesión de ruta para las conversaciones que coincidan con esta vinculación. Úsalos cuando una ruta específica deba mantener el mismo agente, pero aislar la continuidad de la sesión de forma diferente.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`Ámbito de mensajes directos de la sesión de vinculación`},help:{"v1-10sg3xw-4s":`Ajuste opcional del ámbito de sesión de mensajes directos para esta vinculación de ruta. Por ejemplo, mantén session.dmScope="main" a nivel global y usa "per-account-channel-peer" para determinados interlocutores directos.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Ámbito de grupos de la sesión de vinculación`},help:{"v1-1ys2u7k-6n":`Ajuste opcional del ámbito de sesión de grupos/canales para esta vinculación de ruta. "per-group" mantiene separadas las salas coincidentes y bajo la supervisión en segundo plano de la sesión principal del agente, independientemente de dmScope; "main" integra su contexto en main y no requiere supervisión.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Tipo de vinculación`},help:{"v1-172mhtk-3o":`Tipo de vinculación. Usa "route" (u omítelo para las entradas de ruta heredadas) para el enrutamiento normal y "acp" para las vinculaciones persistentes de conversaciones ACP.`}},broadcast:{label:{"v1-awqjh0-j":`Hilos de grupos de agentes`},help:{"v1-1tz72sr-6b":`Usa hilos de grupos de agentes para ejecutar varios agentes configurados en una misma conversación entrante, cada uno en su propia sesión. Las entradas con canal especificado admiten rondas de seguimiento limitadas; los arrays heredados de interlocutores de WhatsApp mantienen el comportamiento de una sola pasada.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Participantes y opciones del grupo de agentes`},help:{"v1-1b63zmt-7d":`Usa un ID de interlocutor con canal especificado (por ejemplo, "telegram:-100123") para configurar un array de ID de agentes o un objeto estricto con agents, mentionGating, maxRounds y maxTurns. Las entradas con canal especificado tienen prioridad sobre las claves heredadas de interlocutores de WhatsApp y permiten un máximo de 16 agentes.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Participantes del grupo de agentes`},help:{"v1-g5o0ky-43":`ID de los agentes participantes de agents.entries (máximo: 16). Cada participante usa su propia sesión para este canal, cuenta, conversación e hilo.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Máximo de rondas del grupo de agentes`},help:{"v1-i6v4jc-5a":`Máximo de rondas por mensaje entrante, incluida la ronda inicial (entero: 1–4, valor predeterminado: 1). En las rondas posteriores se comparten respuestas acotadas de los demás participantes, con atribución de autoría, y las rondas se detienen cuando todos los participantes pasan.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Máximo de turnos del grupo de agentes`},help:{"v1-1kiv8dy-72":`Máximo de turnos de los participantes por mensaje entrante entre todas las rondas (entero: 1–32, valor predeterminado: agents.length). Los cupos se reservan antes del despacho en paralelo; esto limita los turnos de los agentes, no los fragmentos físicos de mensajes ni los envíos de herramientas. Los presupuestos no se reanudan tras un reinicio.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Selección por mención del grupo de agentes`},help:{"v1-uay9zu-5u":`Selecciona solo a los participantes mencionados explícitamente con @ cuando hay alguna coincidencia; de lo contrario, ejecuta a todos los participantes (valor predeterminado: true). Los nombres sin @ o los emojis no seleccionan participantes. Las listas de permitidos del canal y las reglas de admisión siguen aplicándose.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Estrategia del grupo de agentes`},help:{"v1-p4k9hu-4q":`Orden de ejecución de los participantes: "parallel" (valor predeterminado) ejecuta los agentes simultáneamente, mientras que "sequential" los ejecuta en el orden configurado. Cada ronda se completa antes de que comience la siguiente.`}},browser:{label:{"v1-13dzmen-7":`Navegador`},help:{"v1-5b74wi-5l":`Controles de ejecución del navegador para la conexión mediante CDP local o remoto, el enrutamiento de perfiles y el comportamiento de las capturas de pantalla e instantáneas. Mantén los valores predeterminados a menos que tu flujo de automatización requiera ajustes de transporte del navegador personalizados.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Permitir la importación de perfiles del sistema`},help:{"v1-1lsvlxw-5w":`Permite que los equipos macOS importen cookies de un perfil local del sistema de un navegador de la familia Chrome a un perfil de navegador administrado por OpenClaw. Desactiva esta opción para impedir la importación de cookies de perfiles del navegador y la correspondiente solicitud de consentimiento del Llavero de macOS.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Modo de solo conexión del navegador`},help:{"v1-xaw7xm-4s":`Restringe el navegador al modo de solo conexión, sin iniciar procesos de navegador locales. Usa esta opción cuando todas las sesiones del navegador se gestionen externamente mediante un proveedor de CDP remoto.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`URL de CDP del navegador`},help:{"v1-2n72jb-65":`URL del punto de conexión CDP/DevTools utilizada para conectarse a una instancia de navegador gestionada externamente. Úsala para servidores de navegador centralizados, túneles o conexiones a sesiones existentes, y restringe el acceso a la URL a rutas de red de confianza.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Perfil predeterminado del navegador`},help:{"v1-a6xo96-52":`Nombre del perfil de navegador predeterminado que se selecciona cuando quien realiza la llamada no elige un perfil explícitamente. Usa un perfil estable con privilegios mínimos como predeterminado para reducir el uso accidental del estado entre contextos.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Navegador habilitado`},help:{"v1-19qr4oj-56":`Habilita la integración de las funciones del navegador en el Gateway para ejecutar herramientas del navegador y flujos de trabajo basados en CDP. Desactívala cuando no necesites automatizar el navegador para reducir la superficie de exposición y el trabajo de inicio.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Evaluación en el navegador habilitada`},help:{"v1-1oa79mq-59":`Habilita funciones auxiliares de evaluación en el navegador para evaluar scripts en tiempo de ejecución cuando sea compatible. Mantén esta opción desactivada salvo que tus flujos de trabajo requieran funciones de evaluación más allá de las capturas de estado y la navegación.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Ruta del ejecutable del navegador`},help:{"v1-1plb4ki-6i":`Ruta explícita del ejecutable del navegador cuando la detección automática no es suficiente en tu entorno anfitrión. Usa una ruta absoluta estable o una ruta que comience por ~ para el directorio personal de tu sistema operativo, de modo que el comportamiento de inicio sea determinista entre reinicios.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Retransmisor de la extensión del navegador`},help:{"v1-6ywlwr-4e":`Ajustes de compatibilidad de autenticación del retransmisor de la extensión de Chrome. Mantén el período de compatibilidad con versiones anteriores solo mientras las extensiones vinculadas antiguas o los clientes CDP externos sigan necesitándolo.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Permitir autenticación heredada del retransmisor del navegador`},help:{"v1-pj2e90-63":`Acepta temporalmente la autenticación heredada del retransmisor mediante Bearer, Basic y subprotocolo de token. Valor predeterminado: true durante un período de migración. Establece false cuando todas las extensiones y todos los clientes CDP externos usen Browser Relay Authentication v2.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Modo sin interfaz gráfica del navegador`},help:{"v1-1rswq8j-5a":`Fuerza el inicio del navegador en modo sin interfaz gráfica cuando el lanzador local inicia instancias del navegador. Mantén este modo habilitado en entornos de servidor y desactívalo solo cuando necesites depurar con una interfaz visible.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Modo del navegador sin aislamiento`},help:{"v1-slntux-4w":`Desactiva las opciones de aislamiento de Chromium en entornos donde el aislamiento falla durante la ejecución. Mantén esta opción desactivada siempre que sea posible, ya que reduce las protecciones de aislamiento de procesos.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Perfiles del navegador`},help:{"v1-1x8lf05-51":`Mapa de conexiones de perfiles del navegador con nombre, utilizado para el enrutamiento explícito a puertos o URL de CDP, con metadatos opcionales. Mantén nombres de perfil coherentes y evita definiciones de puntos de conexión que se superpongan.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Modo de solo conexión del perfil del navegador`},help:{"v1-2b5zs0-5a":`Configuración de solo conexión específica de cada perfil que omite el inicio del navegador local y solo se conecta a un punto de conexión CDP existente. Resulta útil cuando un perfil se gestiona externamente, pero los demás se inician de forma local.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`Puerto CDP del perfil del navegador`},help:{"v1-gx1yiq-49":`Puerto CDP local específico de cada perfil que se utiliza al conectar con instancias del navegador mediante un puerto en lugar de una URL. Usa puertos únicos para cada perfil para evitar conflictos de conexión.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`URL de CDP del perfil del navegador`},help:{"v1-x491r0-64":`URL del punto de conexión CDP/DevTools específica de cada perfil, utilizada para el enrutamiento explícito del navegador por nombre de perfil. Úsala para servidores CDP remotos, túneles o perfiles de sesiones existentes que deban conectarse a través de un punto de conexión de Chrome DevTools en ejecución.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Controlador del perfil del navegador`},help:{"v1-17byyx6-5r":`Modo del controlador del navegador por perfil. Usa "openclaw" (o el valor heredado "clawd") para perfiles basados en CDP, "existing-session" para la conexión mediante Chrome DevTools MCP o "extension" para el relé autenticado de la extensión de Chrome.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Ruta del ejecutable del perfil del navegador`},help:{"v1-29azyv-4w":`Ruta del ejecutable del navegador por perfil para perfiles de navegador administrados que se inician localmente. Tiene prioridad sobre browser.executablePath y acepta rutas que comienzan con ~ para el directorio de inicio del usuario en el sistema operativo.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Modo sin interfaz gráfica del perfil del navegador`},help:{"v1-p4jtgv-4u":`Ajuste del modo sin interfaz gráfica por perfil para instancias del navegador que se inician localmente. Úsalo cuando un perfil deba permanecer sin interfaz gráfica sin imponer browser.headless a todos los demás perfiles.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Argumentos de Chrome MCP del perfil del navegador`},help:{"v1-rc45ke-5g":`Argumentos adicionales de Chrome DevTools MCP por perfil para la conexión mediante existing-session, como --no-usage-statistics. Los argumentos del punto de conexión especificados aquí tienen prioridad sobre la conexión automática integrada o la selección de la URL del navegador.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Comando de Chrome MCP del perfil del navegador`},help:{"v1-1xpty8o-2h":`Comando de Chrome DevTools MCP por perfil para la conexión mediante existing-session. El valor predeterminado es npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Directorio de datos de usuario del perfil del navegador`},help:{"v1-5xvgex-9h":`Directorio de datos de usuario de Chromium por perfil para conectarse a sesiones existentes mediante Chrome DevTools MCP. Úsalo para Brave, Edge, Chromium o perfiles de Chrome no predeterminados cuando la conexión automática integrada seleccione el directorio de datos del navegador incorrecto en el host o nodo de navegador seleccionado. Las rutas que comienzan con ~ se expanden al directorio personal del sistema operativo.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Valores predeterminados de las instantáneas del navegador`},help:{"v1-v19wdy-4y":`Configuración predeterminada de captura de instantáneas que se usa cuando quien realiza la llamada no proporciona opciones explícitas. Ajústala para lograr un comportamiento de captura uniforme en todos los canales y flujos de automatización.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Modo de instantánea del navegador`},help:{"v1-joeyxp-5c":`Modo predeterminado de extracción de instantáneas que controla cómo se transforma el contenido de la página para que el agente lo procese. Elige el modo que equilibre la legibilidad, la fidelidad y el consumo de tokens para tus flujos de trabajo.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`Política SSRF del navegador`},help:{"v1-1qbp9im-5e":`Configuración de protección contra la falsificación de solicitudes del lado del servidor para las vías de obtención de datos del navegador y de la red que podrían acceder a hosts internos. Mantén valores predeterminados restrictivos en producción y permite únicamente destinos aprobados explícitamente.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Nombres de host permitidos del navegador`},help:{"v1-1rng39-2k":`Nombres de host exactos o direcciones IP literales permitidos por las comprobaciones de la política SSRF del navegador. Mantén la lista al mínimo.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Permitir el rango local único de IPv6 en el navegador`},help:{"v1-1glx5cy-2c":`Permite direcciones locales únicas de IPv6 (fc00::/7) en entornos de proxy de confianza con IP ficticias.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Permitir el rango de pruebas RFC 2544 en el navegador`},help:{"v1-10ateu3-2i":`Permite las IP del rango de pruebas RFC 2544 (198.18.0.0/15) en entornos de proxy de confianza con IP ficticias.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Nombres de host bloqueados en el navegador`},help:{"v1-nug0we-6k":`Patrones de nombres de host que se bloquean antes de la resolución DNS y de las reglas de autorización, incluso con el acceso a redes privadas habilitado. Admite hosts exactos y "*.example.com" solo para subdominios; añade "example.com" por separado para bloquear el dominio raíz. Si está vacío o no se configura, no añade bloqueos.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Permitir acceso peligroso a redes privadas en el navegador`},help:{"v1-17103pi-4m":`Permite acceder a rangos de direcciones de redes privadas desde las herramientas del navegador. Está deshabilitado de forma predeterminada si no se configura; habilítalo solo para destinos de redes privadas explícitamente confiables.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Limpieza de pestañas del navegador`},help:{"v1-1ctwaad-4y":`Política de limpieza, sin garantía de éxito, para las pestañas del navegador abiertas por sesiones del agente principal. Mantenla habilitada para evitar que se acumulen pestañas obsoletas del entorno aislado o del navegador administrado en gateways de larga duración.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Limpieza de pestañas del navegador habilitada`},help:{"v1-4sv97p-3u":`Habilita la limpieza de las pestañas del navegador supervisadas que estén inactivas en las sesiones del agente principal. Deshabilítala solo cuando las herramientas externas gestionen por completo el ciclo de vida de las pestañas.`}},channels:{label:{"v1-1ju93md-8":`Canales`},help:{"v1-12yv6ma-5n":`Configuraciones de los proveedores de canales y valores predeterminados compartidos que controlan las políticas de acceso, la visibilidad de las señales de actividad y el comportamiento de cada interfaz. Mantén centralizados los valores predeterminados y personalízalos por proveedor solo cuando sea necesario.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Valores predeterminados de los canales`},help:{"v1-uz6veb-4p":`Comportamiento predeterminado de los canales que se aplica a todos los proveedores cuando no se han definido ajustes específicos para cada uno. Úsalo para establecer una política de base uniforme antes de realizar ajustes por proveedor.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Protección predeterminada contra bucles entre bots`},help:{"v1-1lpznyk-4w":`Ajustes predeterminados de protección contra bucles por pareja para los proveedores de canales que admiten protección contra bucles entre bots. Usa ajustes específicos por proveedor solo cuando un canal necesite un límite diferente.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Segundos de espera predeterminados para bucles entre bots`},help:{"v1-1yl5ird-2z":`Segundos de espera que se aplican a una pareja después de que supere el límite de bucles. El valor predeterminado para los canales compatibles es 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Protección contra bucles entre bots activada de forma predeterminada`},help:{"v1-3ruik-4r":`Activa de forma predeterminada la protección contra bucles por pareja en los canales compatibles cuando los mensajes generados por bots pueden llegar a la fase de distribución. Los proveedores pueden desactivar la protección cuando se ignoran los bots.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Eventos predeterminados por ventana para bucles entre bots`},help:{"v1-1u0mdjc-41":`Número máximo de eventos que una pareja de emisor y receptor puede intercambiar dentro de la ventana configurada antes de que comience el bloqueo. El valor predeterminado para los canales compatibles es 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Duración predeterminada de la ventana para bucles entre bots en segundos`},help:{"v1-12xpmen-2m":`Duración de la ventana deslizante en segundos para los límites de bucles entre pares. El valor predeterminado para los canales compatibles es 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Visibilidad predeterminada del contexto`},help:{"v1-1hze3g1-5o":`Visibilidad predeterminada del contexto complementario para el contenido recuperado de citas, hilos e historial: "all" (conservar todo el contexto), "allowlist" (solo remitentes de la lista de permitidos) o "allowlist_quote" (lista de permitidos y conservación de citas explícitas).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Política de grupos predeterminada`},help:{"v1-ntl9m4-4n":`Política de grupos predeterminada para todos los canales: "open", "disabled" o "allowlist". Mantén "allowlist" para configuraciones de producción más seguras, salvo que se busque una participación amplia en los grupos.`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`Visibilidad predeterminada de los latidos`},help:{"v1-49bw75-4v":`Configuración predeterminada de visibilidad de los latidos para los mensajes de estado emitidos por proveedores o canales. Ajústala globalmente para reducir las actualizaciones innecesarias de estado correcto sin dejar de mostrar las alertas.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`Mostrar alertas de latidos`},help:{"v1-8dk8zx-4g":`Muestra alertas de latidos con estado degradado o de error cuando el valor es true, para que los canales de los operadores indiquen los problemas rápidamente. Mantén esta opción activada en producción para que los fallos de los canales sean visibles.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`Mostrar latidos con estado correcto`},help:{"v1-17tg3mk-4z":`Muestra entradas de estado de latido correcto/OK en las salidas de estado de los canales cuando el valor es true. Mantén el valor false en entornos con mucho ruido y actívalo solo cuando los operadores necesiten confirmaciones explícitas de buen funcionamiento.`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`Usar indicador de latido`},help:{"v1-1w12cs2-4m":`Activa una representación concisa del latido mediante indicadores en lugar de texto de estado detallado, cuando sea compatible. Usa el modo de indicador en paneles densos con muchos canales activos.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Menciones implícitas predeterminadas`},help:{"v1-4gtdyv-48":`Política predeterminada que determina si responder al bot, citarlo o escribir en un hilo en el que haya participado activa los canales de mensajes compatibles sin una mención explícita.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Menciones implícitas predeterminadas al citar al bot`},help:{"v1-va1u5v-2v":`Trata los mensajes citados del bot como menciones implícitas de forma predeterminada. El valor predeterminado es true para mantener la compatibilidad con versiones anteriores.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Menciones implícitas predeterminadas al responder al bot`},help:{"v1-lm44c3-39":`Trata las respuestas a los mensajes del propio bot como menciones implícitas de forma predeterminada. El valor predeterminado es true para mantener la compatibilidad con versiones anteriores.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Menciones implícitas predeterminadas por participación en hilos`},help:{"v1-160205h-3o":`Trata los mensajes posteriores en hilos donde haya participado el bot como menciones implícitas de forma predeterminada. El valor predeterminado es true para mantener la compatibilidad con versiones anteriores.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Modelos alternativos por canal`},help:{"v1-1b01spx-2p":`Asigna proveedor -> id. del canal / id. del interlocutor de mensaje directo -> modelo alternativo (los valores son proveedor/modelo o alias).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Workers en la nube`},help:{"v1-10carc4-5v":`Perfiles de workers en la nube de activación opcional para entornos remotos desechables. Si se omite esta sección o no contiene perfiles, la creación de workers en la nube sigue sin estar disponible y el comportamiento existente del estado del Gateway/nodo no cambia.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Escritorio de worker en la nube (experimental)`},help:{"v1-vllayc-3n":`Habilita la interfaz experimental worker.desktop.observe y el panel de escritorio de Control UI para entornos de workers en la nube compatibles con escritorio.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Grupo de procesos de trabajo en la nube preparados`},help:{"v1-rw51o5-6b":`Límites para los procesos de trabajo en la nube que se mantienen preparados para sesiones posteriores. Las reservas generan cargos por máquinas en ejecución hasta que se completa la limpieza del proveedor; su vencimiento fijo se rige por la demanda real del proyecto y la política de inactividad vigente del proveedor.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Límite de reserva de trabajadores en la nube listos`},help:{"v1-1mpd1dt-7u":`Límite global del Gateway para los trabajadores en la nube preparados y sin asignar entre todos los proyectos y perfiles (predeterminado: 4). Los trabajadores en preparación y aquellos cuya eliminación de la reserva aún no se ha confirmado cuentan para este límite. Establece 0 para vaciar las reservas sin asignar y desactivar su reposición, manteniendo la reutilización de instantáneas y las sesiones activas.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Perfiles de workers en la nube`},help:{"v1-eii67l-3j":`Perfiles con nombre de workers en la nube. Cada perfil selecciona un proveedor de workers registrado por un plugin e incluye ajustes propios del proveedor.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Perfil de worker en la nube`},help:{"v1-1v2w7jl-4u":`Un perfil de worker en la nube que se selecciona por nombre al crear un entorno. Guarda las credenciales del proveedor en referencias compatibles en lugar de incrustar datos secretos en este bloque.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Método de instalación de worker en la nube`},help:{"v1-blrtbf-74":`Método de instalación del worker: "bundle" (predeterminado) transfiere la compilación instalada del Gateway, identificada por el hash de su contenido, y admite versiones publicadas, en desarrollo y sin publicar; "npm" instala la versión exacta del Gateway y solo está disponible cuando esa versión está publicada.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Proveedor de workers en la nube`},help:{"v1-1p4s4c1-44":`ID del proveedor de workers registrado por un plugin. El plugin configurado debe exponer este ID para que el Gateway pueda aprovisionar entornos a partir del perfil.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Objetivo de reserva de trabajadores en la nube listos`},help:{"v1-1nwve9s-7w":`Cantidad objetivo de trabajadores preparados y sin asignar por cada proyecto que cumpla los requisitos y use este perfil (predeterminado: 1), sujeta al límite global del Gateway para el grupo de trabajadores preparados. Establece 0 para desactivar las reservas de este perfil, manteniendo la reutilización de instantáneas. Los trabajadores en preparación y aquellos cuya eliminación de la reserva aún no se ha confirmado cuentan para este objetivo.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Configuración del proveedor de workers en la nube`},help:{"v1-mq7u32-4j":`Configuración propia del proveedor validada por el plugin seleccionado. Usa objetos SecretRef para los valores que contengan secretos; la configuración opaca no obtiene resolución automática de secretos.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Tiempo de inactividad antes de suspender el worker en la nube`},help:{"v1-1keuwgh-4w":`Libera automáticamente los recursos de un worker en la nube inactivo tras este intervalo, como 45m o 2h; el siguiente mensaje aprovisiona un reemplazo. Mínimo: 1m. Deja este valor sin configurar para mantener los workers en ejecución.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Perfiles de workers en la nube por proyecto`},help:{"v1-1kkfrif-46":`Nombres de los perfiles predeterminados de workers en la nube, indexados por la identidad del repositorio normalizada en minúsculas (host/owner/repo). Los ID de perfil de despacho explícitos tienen prioridad.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Perfil de worker en la nube por proyecto`},help:{"v1-1mux5u0-30":`Nombre del perfil de worker en la nube que se usa de forma predeterminada cuando el origen del árbol de trabajo de una sesión coincide con esta identidad de repositorio.`}},commands:{label:{"v1-15x4mpf-8":`Comandos`},help:{"v1-1gi0dr2-5a":`Controla las interfaces de comandos del chat, las restricciones de acceso del propietario y el comportamiento del acceso con privilegios elevados a comandos en todos los proveedores. Mantén los valores predeterminados a menos que necesites controles más estrictos para los operadores o una mayor disponibilidad de comandos.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Reglas de acceso con privilegios elevados a comandos`},help:{"v1-7azkw-5g":`Define reglas de autorización de comandos elevados por canal y remitente para las interfaces de comandos de nivel propietario. Usa identidades específicas y restringidas de cada proveedor para evitar que los comandos privilegiados queden expuestos a un público amplio en los chats.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Permitir comando Bash en el chat`},help:{"v1-83ah7w-36":"Permite que el comando bash del chat (`!`; alias `/bash`) ejecute comandos de shell en el host (valor predeterminado: false; requiere tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Tiempo de Bash en primer plano (ms)`},help:{"v1-1o0o4dw-2c":`Tiempo que bash espera antes de pasar a segundo plano (valor predeterminado: 2000; 0 lo pasa a segundo plano inmediatamente).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`Permitir /config`},help:{"v1-151bb7c-21":`Permite que el comando /config del chat lea y escriba la configuración en disco (valor predeterminado: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`Permitir /debug`},help:{"v1-y1lc3j-1y":`Permite usar el comando /debug del chat para aplicar ajustes que solo tienen efecto durante la ejecución (valor predeterminado: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`Permitir /mcp`},help:{"v1-1rtwcgd-2o":`Permite que el comando /mcp del chat gestione la configuración de servidores MCP de OpenClaw en mcp.servers (valor predeterminado: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Comandos nativos`},help:{"v1-dighr2-5n":`Registra comandos nativos de barra o menú en los canales que admiten el registro de comandos (Discord, Slack, Telegram). Mantén esta opción activada para facilitar su descubrimiento, salvo que uses intencionadamente flujos de trabajo con comandos solo de texto.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Comandos nativos de habilidades`},help:{"v1-19gtqci-5h":`Registra comandos nativos de habilidades para que los usuarios puedan invocarlas directamente desde los menús de comandos del proveedor, cuando se admita. Mantén esta opción alineada con tu política de habilidades para que los comandos disponibles coincidan con lo que esperan los operadores.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Propietarios de comandos`},help:{"v1-1di38gv-3y":`Lista explícita de propietarios autorizados para comandos restringidos a propietarios. Usa los ID nativos del canal (opcionalmente con un prefijo como "whatsapp:+15551234567"). Se ignora '*'.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`Permitir /plugins`},help:{"v1-akwy9y-33":`Permite el comando de chat /plugins para enumerar los plugins detectados y activarlos o desactivarlos en la configuración (valor predeterminado: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Permitir reinicio`},help:{"v1-m32fv2-27":`Permitir /restart, /update y solicitudes externas de reinicio mediante SIGUSR2 (valor predeterminado: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Comandos de texto`},help:{"v1-1utu76s-5j":`Habilita el análisis de comandos de texto en la entrada del chat, además de las interfaces de comandos nativos cuando estén disponibles. Mantén esta opción activada para garantizar la compatibilidad con los canales que no admiten el registro de comandos nativos.`}},cron:{label:{"v1-1qlte4b-b":`Automatizaciones`},help:{"v1-4md8ic-5u":`Configuración global del programador para las automatizaciones guardadas, la concurrencia de ejecuciones, la entrega alternativa y la retención de sesiones de ejecución. Mantén los valores predeterminados salvo que vayas a aumentar el volumen de automatizaciones o integrar receptores externos de webhooks.`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Automatizaciones habilitadas`},help:{"v1-y8otx6-5i":`Habilita la ejecución de automatizaciones para las programaciones guardadas que gestiona el Gateway. Mantén esta opción activada para los flujos habituales de recordatorios y automatizaciones, y desactívala solo para pausar todas las ejecuciones de automatizaciones sin eliminar las tareas.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Retención de sesiones de automatizaciones`},help:{"v1-4wagu6-7e":"Controla cuánto tiempo se conservan las sesiones de ejecuciones de automatización completadas antes de eliminarlas (`24h`, `7d`, `1h30m` o `false` para desactivar la eliminación; una duración de cero, como `0h`, también la desactiva; valor predeterminado: `24h`). Usa una retención más corta para reducir el crecimiento del almacenamiento en programaciones de alta frecuencia."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Omitir automatizaciones recurrentes no ejecutadas`},help:{"v1-w9wfmo-66":`Omite las ejecuciones recurrentes de cron/every que no se realizaron al iniciar Gateway y programa su próxima ejecución futura en lugar de recuperar las pendientes. Valor predeterminado: false. Activa esta opción para evitar recordatorios obsoletos tras un periodo de inactividad; las tareas de ejecución única de tipo at se siguen recuperando.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`Política SSRF de webhooks de automatizaciones`},help:{"v1-1xlfqnu-5h":`Política SSRF aplicada a cada webhook saliente de automatización. Los destinos privados, de bucle local, de enlace local e internos permanecen bloqueados a menos que esta política los permita explícitamente. Déjala sin configurar para aplicar restricciones estrictas a los envíos.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Nombres de host permitidos para webhooks de automatizaciones`},help:{"v1-1i94hyz-3n":`Nombres de host exactos o direcciones IP literales permitidos para el envío de webhooks de automatizaciones, incluidos los destinos que de otro modo estarían bloqueados. Mantén la lista al mínimo.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Permitir el rango local único de IPv6 para webhooks de automatizaciones`},help:{"v1-rke0oj-3b":`Permite enviar webhooks de automatizaciones a direcciones locales únicas de IPv6 (fc00::/7). Úsalo solo con entornos de proxy de IP ficticias de confianza.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Permitir el rango de pruebas de rendimiento de RFC 2544 para webhooks de automatizaciones`},help:{"v1-x1usg4-3h":`Permite webhooks de automatización dirigidos a IP del rango de pruebas de rendimiento RFC 2544 (198.18.0.0/15). Úsalo solo con entornos de proxy de IP ficticias de confianza.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Nombres de host bloqueados para webhooks de automatización`},help:{"v1-16cv1ic-6a":`Patrones de nombres de host que se bloquean antes de la resolución DNS y de aplicar las reglas de autorización para la entrega de webhooks de automatización. Admite hosts exactos y "*.example.com" solo para subdominios; añade "example.com" por separado para bloquear el dominio raíz. Si está vacío o sin definir, no se añaden bloqueos.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Permitir redes privadas para webhooks de automatización (peligroso)`},help:{"v1-1n9710c-3t":`Permite webhooks de automatización dirigidos a destinos de redes privadas e internas. Mantén esta opción desactivada a menos que todos los destinos de webhook configurados sean de confianza.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Token Bearer para webhooks de automatización`},help:{"v1-1l90hxg-5l":`Token Bearer que se adjunta a los envíos POST de webhooks de automatización cuando se usa el modo webhook. Es preferible usar la sustitución mediante secretos o variables de entorno y renovar este token periódicamente si los endpoints de webhook compartidos son accesibles desde Internet.`}},desktop:{label:{"v1-rs698z-7":`Escritorio`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Escritorio local`},help:{"v1-99weio-30":`Observación del escritorio para nodos vinculados o para la fuente experimental del host de Gateway, mediante un servidor VNC local.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Uso compartido del escritorio`},help:{"v1-m9lbcj-83":`Habilita la fuente de escritorio de este equipo. Los nodos vinculados de macOS, Windows y Linux la tienen habilitada de forma predeterminada; una preferencia explícita de uso compartido en la aplicación de escritorio tiene prioridad. La fuente de Labs del host de Gateway está deshabilitada de forma predeterminada y aplica los cambios en tiempo real. Reinicia un nodo vinculado después de cambiar su configuración de escritorio.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Escritorio gestionado del host Linux`},help:{"v1-1r7n22m-49":`Ejecuta y supervisa un escritorio TigerVNC/XFCE sin pantalla en Linux, accesible solo mediante la interfaz de bucle local. Un puerto explícito o un servidor VNC existente en el puerto predeterminado siguen teniendo prioridad.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Archivo de contraseña de VNC local`},help:{"v1-1m5lsox-37":`Ruta absoluta al archivo de contraseña de VNC. Omítela en macOS para introducir las credenciales de la cuenta al abrir el visor de escritorio.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Puerto VNC local`},help:{"v1-1ku4w9b-2b":`Puerto RFB de bucle local de un servidor VNC que ya esté en ejecución en este equipo (predeterminado: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Diagnóstico`},help:{"v1-1d5rnym-5p":`Controles de diagnóstico para el seguimiento selectivo, la exportación de telemetría y la inspección de la caché durante la depuración. Mantén los diagnósticos básicos al mínimo en producción y habilita señales más detalladas solo al investigar problemas.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Seguimiento de caché`},help:{"v1-10523zm-5b":`Ajustes del registro de seguimiento de caché para observar las decisiones de caché y el contexto de la carga útil en ejecuciones integradas. Habilítalo temporalmente para depurar y deshabilítalo después para reducir la cantidad de datos sensibles en los registros.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Seguimiento de caché habilitado`},help:{"v1-2c1umi-1v":`Registra instantáneas del seguimiento de caché para las ejecuciones del agente integrado (predeterminado: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Diagnósticos habilitados`},help:{"v1-a46pxt-4h":`Interruptor principal para la salida de instrumentación de diagnóstico en los registros y las rutas de conexión de telemetría. Está habilitado de forma predeterminada; establécelo en false solo en entornos con restricciones estrictas.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Indicadores de diagnóstico`},help:{"v1-x4w5ok-33":`Activa registros de diagnóstico específicos mediante indicadores (p. ej., ["telegram.http"]). Admite comodines como "telegram.*" o "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Configuración de exportación de OpenTelemetry para trazas, métricas y registros emitidos por los componentes del Gateway. Úsala al integrar con sistemas centralizados de observabilidad y flujos de procesamiento de trazas distribuidas.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`Captura de contenido de OpenTelemetry`},help:{"v1-19tid4t-2t":`Captura opcional de contenido de spans de OTEL. Desactivada de forma predeterminada; true captura el contenido de mensajes que no sean del sistema y de herramientas.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry activado`},help:{"v1-193bm0-5b":`Activa el flujo de exportación de OpenTelemetry para trazas, métricas y registros según la configuración del punto de conexión y del protocolo. Mantenlo desactivado hasta que el punto de conexión del colector y la autenticación estén completamente configurados.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`Punto de conexión de OpenTelemetry`},help:{"v1-4rrd1x-4y":`URL del punto de conexión del colector que se utiliza para el transporte de exportación de OpenTelemetry, incluidos el esquema y el puerto. Usa un punto de conexión de colector accesible y de confianza, y supervisa los errores de ingesta tras el despliegue.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`Intervalo de vaciado de OpenTelemetry (ms)`},help:{"v1-1moqogc-53":`Intervalo en milisegundos para el vaciado periódico de telemetría desde los búferes al colector. Auméntalo para reducir la frecuencia de los envíos de exportación o redúcelo para obtener visibilidad más rápidamente durante la respuesta activa a incidentes.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`Cabeceras de OpenTelemetry`},help:{"v1-s26t2a-52":`Encabezados HTTP adicionales enviados con las solicitudes de exportación de OpenTelemetry, que suelen usarse para la autenticación de inquilinos o el enrutamiento. Mantén los secretos en valores respaldados por variables de entorno y evita la proliferación innecesaria de encabezados.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`Registros de OpenTelemetry habilitados`},help:{"v1-12wo6rv-4k":`Habilita la exportación de señales de registro mediante OpenTelemetry, además de los destinos de registro locales. Usa esta opción cuando se requiera una correlación centralizada de registros entre servicios y agentes.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`Endpoint de registros de OpenTelemetry`},help:{"v1-1vgzldu-40":`Endpoint de registros OTLP/HTTP específico de la señal. Si se establece, sustituye a diagnostics.otel.endpoint y OTEL_EXPORTER_OTLP_ENDPOINT únicamente para la exportación de registros.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`Exportador de registros de OpenTelemetry`},help:{"v1-9bzywd-5q":`Destino de exportación de registros para diagnostics.otel.logs. Usa "otlp" para el endpoint de registros OTLP configurado, "stdout" para un registro JSON por línea de stdout en canalizaciones de registros de contenedores y "both" cuando se requieran ambos destinos.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`Prefijo de nombres de métricas de OpenTelemetry`},help:{"v1-1epdpi9-b2":`Reemplaza el prefijo predeterminado "openclaw." en los nombres de métricas propias de OpenClaw. Usa una cadena vacía para eliminar el prefijo, o hasta 128 caracteres ASCII entre letras, dígitos, guiones bajos, puntos, guiones y barras, comenzando por una letra. Incluye cualquier separador que necesites, por ejemplo "acme."; los nombres de métricas estándar gen_ai.* no se modifican. Cambiar este valor requiere actualizar los paneles y las alertas que consultan los nombres anteriores.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`Métricas de OpenTelemetry habilitadas`},help:{"v1-13r4cf4-4x":`Habilita la exportación de señales de métricas al endpoint del recopilador de OpenTelemetry configurado. Mantén esta opción habilitada para los paneles de estado en tiempo de ejecución y deshabilítala solo si es necesario minimizar el volumen de métricas.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`Endpoint de métricas de OpenTelemetry`},help:{"v1-qlfh7x-47":`Endpoint de métricas OTLP/HTTP específico de la señal. Si se configura, sustituye a diagnostics.otel.endpoint y OTEL_EXPORTER_OTLP_ENDPOINT únicamente para la exportación de métricas.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`Protocolo de OpenTelemetry`},help:{"v1-17ine8s-5e":`Protocolo de transporte de OTel para la exportación de telemetría. Solo se acepta "http/protobuf"; ejecuta "openclaw doctor --fix" para corregir un valor heredado "grpc" guardado o recibir instrucciones de edición manual específicas de la fuente.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`Tasa de muestreo de trazas de OpenTelemetry`},help:{"v1-brcwep-50":`Tasa de muestreo de trazas (0-1) que controla cuánto tráfico de trazas se exporta a los backends de observabilidad. Las tasas más bajas reducen la sobrecarga y el coste, mientras que las más altas mejoran la precisión de la depuración.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`Nombre del servicio de OpenTelemetry`},help:{"v1-1hpiqon-5d":`Nombre del servicio indicado en los atributos de recursos de telemetría para identificar esta instancia de Gateway en los backends de observabilidad. Usa nombres estables para que los paneles y las alertas mantengan la coherencia entre despliegues.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`Trazas de OpenTelemetry habilitadas`},help:{"v1-j7zrrp-4s":`Habilita la exportación de señales de trazas al endpoint del recopilador de OpenTelemetry configurado. Mantén esta opción habilitada cuando necesites trazas de latencia o depuración y deshabilítala si solo quieres métricas o registros.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`Endpoint de trazas de OpenTelemetry`},help:{"v1-8yw5p1-43":`Endpoint de trazas OTLP/HTTP específico para esta señal. Si se configura, tiene prioridad sobre diagnostics.otel.endpoint y OTEL_EXPORTER_OTLP_ENDPOINT solo para la exportación de trazas.`}},discovery:{label:{"v1-l2sr05-9":`Descubrimiento`},help:{"v1-1sqleij-4w":`Ajustes de descubrimiento de servicios para el anuncio local mediante mDNS y la señalización opcional de presencia en redes de área amplia. Limita el descubrimiento a las redes previstas para evitar la filtración de metadatos del servicio.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`Descubrimiento mediante mDNS`},help:{"v1-vtbyyq-4w":`Grupo de configuración del descubrimiento mediante mDNS para ajustar el anuncio en la red local y el comportamiento del descubrimiento. Mantén el modo mínimo para el descubrimiento habitual en la LAN, salvo que se requieran metadatos adicionales.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`Modo de descubrimiento mediante mDNS`},help:{"v1-1p28pd5-2m":`Modo de difusión de mDNS ("minimal" de forma predeterminada, "full" incluye cliPath/sshPort, "off" desactiva mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Descubrimiento de área amplia`},help:{"v1-1akkqjm-53":`Grupo de configuración del descubrimiento de área amplia para exponer señales de descubrimiento más allá del ámbito del enlace local. Actívalo solo en implementaciones que agreguen intencionadamente la presencia de gateways en distintas ubicaciones.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Dominio de descubrimiento de área amplia`},help:{"v1-rxrygo-4m":`Dominio DNS-SD unicast opcional para el descubrimiento de área amplia, como openclaw.internal. Úsalo cuando publiques intencionadamente el descubrimiento del gateway más allá del ámbito local de mDNS.`}},env:{label:{"v1-1zc80q-b":`Entorno`},help:{"v1-1ao5po6-55":`Ajustes de importación y sobrescritura del entorno para proporcionar variables de ejecución al proceso del gateway. Usa esta sección para controlar la carga del entorno del shell y el comportamiento de la inyección explícita de variables.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Importación del entorno del shell`},help:{"v1-1gw487t-4y":`Controles de importación del entorno del shell para cargar variables desde tu shell de inicio de sesión durante el arranque. Mantén esta opción activada si dependes de secretos definidos en el perfil o de personalizaciones de PATH.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Importación del entorno del shell activada`},help:{"v1-5tiuup-5u":`Permite cargar variables de entorno desde el perfil del shell del usuario durante la inicialización. Mantén esta opción activada en equipos de desarrollo o desactívala en entornos de servicio restringidos con gestión explícita de las variables de entorno.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Tiempo de espera de importación del entorno del shell (ms)`},help:{"v1-nsk2yf-5c":`Tiempo máximo en milisegundos permitido para resolver el entorno del shell antes de aplicar el comportamiento alternativo. Usa tiempos de espera más cortos para acelerar el arranque o auméntalos si la inicialización del shell es lenta.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Sobrescrituras de variables de entorno`},help:{"v1-yxc3z7-5n":`Sobrescrituras explícitas de variables de entorno mediante pares clave/valor que se integran en el entorno del proceso de OpenClaw durante la ejecución. Usa esta opción para configurar el entorno de forma determinista en lugar de depender únicamente de los efectos secundarios del perfil del shell.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`Opciones de ejecución de Gateway para el modo de enlace, la autenticación, Control UI, el transporte remoto y los controles de seguridad operativa. Mantén valores predeterminados conservadores, salvo que quieras exponer Gateway más allá de las interfaces locales de confianza.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Permitir x-real-ip como alternativa en Gateway`},help:{"v1-1wr3qmw-4c":`Permite usar x-real-ip como alternativa cuando falta x-forwarded-for en escenarios con proxy. Mantén esta opción desactivada, salvo que tu infraestructura de entrada requiera este comportamiento de compatibilidad.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Autenticación de Gateway`},help:{"v1-70b6ni-50":`Política de autenticación para el acceso HTTP/WebSocket al Gateway, incluidos el modo, las credenciales, el comportamiento del proxy de confianza y la limitación de frecuencia. Mantén la autenticación habilitada en todos los despliegues que no estén limitados a la interfaz de bucle local.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Permitir la identidad de Tailscale en la autenticación del Gateway`},help:{"v1-vqtmgw-53":`Permite que las vías de identidad de confianza de Tailscale satisfagan las comprobaciones de autenticación del Gateway cuando estén configuradas. Usa esta opción solo si la seguridad de las identidades de tu tailnet es sólida y los flujos de trabajo de los operadores dependen de ella.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Concesiones de ámbitos por identidad del Gateway`},help:{"v1-1h0zxy7-5n":`Asocia identidades verificadas de un proxy de confianza o de Tailscale con concesiones de ámbitos de operador válidas solo para la conexión. Las claves de correo electrónico se comparan sin distinguir mayúsculas y minúsculas; las concesiones amplían los ámbitos del dispositivo antes de que se aplique el límite de ámbitos de la conexión.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Modo de autenticación del Gateway`},help:{"v1-j8rodq-9t":`Modo de autenticación del Gateway: "none", "token", "password" o "trusted-proxy", según tu arquitectura perimetral. El modo token/password selecciona el secreto configurado (gateway.auth.token o gateway.auth.password); los clientes pueden enviarlo en cualquiera de los campos de autenticación de conexión. Usa token/password para la exposición directa y trusted-proxy solo detrás de proxies reforzados con reconocimiento de identidad.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Contraseña del Gateway`},help:{"v1-1ndt0u2-4g":`Secreto compartido seleccionado mediante gateway.auth.mode=password. Los clientes pueden enviarlo tanto en auth.token como en auth.password. El modo de contraseña es obligatorio para Tailscale Funnel.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Límite de frecuencia de autenticación del Gateway`},help:{"v1-1kstr42-54":`Controles de limitación de intentos de inicio de sesión y autenticación para reducir el riesgo de ataques de fuerza bruta contra las credenciales en el perímetro del Gateway. Manténgalos habilitados en entornos expuestos y ajuste los umbrales según su tráfico habitual.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Token del Gateway`},help:{"v1-16i7cxs-5q":`Secreto compartido seleccionado mediante gateway.auth.mode=token, el valor predeterminado para las nuevas configuraciones locales iniciales. Los clientes pueden enviarlo en auth.token o en auth.password. La escucha en direcciones que no sean de bucle local requiere un modo de autenticación habilitado.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Autenticación del Gateway mediante proxy de confianza`},help:{"v1-12fsi5d-58":`Asignación de encabezados de autenticación mediante proxy de confianza para proveedores de identidad previos en la cadena que inyectan atributos de usuario. Úsela solo con rangos CIDR de proxies conocidos y listas estrictas de encabezados permitidos para evitar la suplantación de encabezados de identidad.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Identidad de GitHub mediante OIDC de Cloudflare Access`},help:{"v1-1puth4k-6t":`Identidad verificada de GitHub opcional procedente de un proveedor OIDC de Cloudflare Access seleccionado. Requiere las cabeceras estándar de correo electrónico y de aserción de Access. Si faltan las declaraciones, los perfiles siguen usando solo el correo electrónico; se conservan los roles de perfil y las preferencias de coautoría existentes.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Declaración del ID de cuenta de GitHub`},help:{"v1-pcaaw7-57":`Declaración OIDC reenviada exacta cuyo valor es un ID de cuenta de GitHub verificado, expresado como una cadena de dígitos decimales que representa un número positivo. Configura Access para reenviarla en oidc_fields; nunca uses una declaración no verificada que el usuario pueda editar.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Emisor de Cloudflare Access`},help:{"v1-gykv03-56":`Origen HTTPS exacto del equipo de Cloudflare Access de confianza, como https://example.cloudflareaccess.com, sin barra al final. Las declaraciones de otros emisores no proporcionan una identidad de GitHub.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`ID del proveedor OIDC de Cloudflare Access`},help:{"v1-kbyo5w-44":`ID exacto del proveedor de identidad de Access para la integración OIDC de confianza. Ni el nombre para mostrar de un proveedor ni un nombre de declaración coincidente bastan por sí solos para establecer la confianza.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Aprobación automática de dispositivos mediante proxy de confianza`},help:{"v1-uh32ha-6z":`Política opcional para aprobar automáticamente nuevos dispositivos de operadores que usan el navegador o la interfaz nativa, así como ampliaciones de permisos con la misma clave, tras la autenticación mediante proxy de confianza. Los permisos concedidos están limitados por deviceAutoApprove.scopes y por el encabezado x-openclaw-scopes del proxy, cuando está presente.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Aprobación automática de dispositivos mediante proxy de confianza habilitada`},help:{"v1-1nntwls-78":`Aprueba automáticamente nuevos dispositivos de operadores que usan el navegador o la interfaz nativa, así como ampliaciones de permisos con la misma clave, después de que el proxy inverso autentique a un usuario autorizado. Valor predeterminado: false. Habilite esta opción solo cuando el perímetro de confianza de identidad del proxy sea lo suficientemente sólido como para sustituir la vinculación manual de dispositivos.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Permisos de aprobación automática de dispositivos mediante proxy de confianza`},help:{"v1-raeila-g3":`Permisos máximos concedidos a los dispositivos de operador aprobados automáticamente. Los valores predeterminados son operator.read, operator.write, operator.approvals y operator.questions. Los permisos solicitados se limitan a esta lista; las solicitudes sin permisos especificados reciben los de esta lista. Si no se configura, la aprobación automática también añade operator.questions para los clientes de interfaz de usuario antiguos; una lista explícita nunca se amplía. Incluir operator.admin explícitamente permite que cualquier usuario autenticado mediante proxy obtenga automáticamente permisos completos de administración y hace que las solicitudes sin permisos especificados también los reciban automáticamente; además, genera un hallazgo crítico en la auditoría de seguridad y una advertencia al iniciar Gateway.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Modo de enlace de Gateway`},help:{"v1-1unqude-4y":`Perfil de enlace de red: "auto", "lan", "loopback", "custom" o "tailnet" para controlar la exposición de las interfaces. Mantén "loopback" para un funcionamiento exclusivamente local; "auto" puede exponer todas las interfaces.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`Agentes de CLI`},help:{"v1-1qqo8m2-5a":`Descubrimiento en Control UI de motores externos de sesiones CLI expuestos por el catálogo de sesiones de Gateway. Está activado de forma predeterminada; desactívalo para impedir que se inicien esos motores desde el selector de modelos de una nueva sesión.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`Agentes de CLI habilitados`},help:{"v1-ufu7fx-8p":`Muestra los agentes de CLI disponibles en el catálogo en el selector de modelos para nuevas sesiones de Control UI cuando su valor es true (predeterminado: true). Establécelo en false para deshabilitar los agentes de CLI y la creación de sesiones nativas de CLI. Solo se muestran los catálogos que anuncian la posibilidad de crear sesiones, y el selector permanece oculto cuando Gateway no anuncia compatibilidad con el catálogo de sesiones.`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`Configuración de alojamiento de Control UI, incluida la habilitación, las rutas y las medidas de seguridad para los orígenes del navegador y la autenticación. Mantén al mínimo la exposición de la interfaz y combínala con controles de autenticación sólidos antes de realizar despliegues accesibles desde Internet.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Orígenes permitidos de Control UI`},help:{"v1-1stgitk-9i":`Orígenes del navegador permitidos para las conexiones WebSocket de Control UI/WebChat (solo orígenes completos, p. ej., https://control.example.com). Obligatorio para los despliegues de Control UI fuera de la interfaz de bucle local, salvo que se habilite explícitamente la alternativa peligrosa basada en el encabezado Host. Establecer ["*"] permite cualquier origen del navegador y debe evitarse fuera de las pruebas locales estrictamente controladas.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Permitir URL externas para contenido incrustado en Control UI`},help:{"v1-obwpfg-6s":`Opción PELIGROSA que permite que el contenido incrustado alojado cargue URL externas absolutas de http(s). Mantenla desactivada a menos que tu Control UI incruste intencionadamente páginas de terceros de confianza; los documentos alojados en /__openclaw__/canvas y /__openclaw__/a2ui no la necesitan.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Obtener automáticamente los favicons de los enlaces`},help:{"v1-bn9u34-ag":`Obtener los favicons de los enlaces y las vistas previas sociales de las pestañas del navegador a través del Gateway (activado de forma predeterminada). Las tarjetas de las pestañas del navegador cargan los metadatos públicos de las páginas y las imágenes declaradas sin cookies del navegador ni credenciales del sitio. Todas las solicitudes utilizan comprobaciones estrictas de SSRF y un procesamiento limitado de HTML e imágenes. Establece el valor en false para desactivar la obtención automática tanto de favicons como de vistas previas de páginas; las capturas de pantalla en directo del navegador no se ven afectadas.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Ruta base de Control UI`},help:{"v1-1dx68ar-1w":`Prefijo de URL opcional desde el que se sirve Control UI (p. ej., /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Invitación a la comunidad en Control UI`},help:{"v1-1rz3zsx-73":`Muestra la invitación a la comunidad de Discord en la Control UI que sirve este Gateway (activado de forma predeterminada). Establece false para ocultarla en todos los navegadores que usen este despliegue de la interfaz. Los cambios se aplican tras actualizar el navegador o volver a conectarse; al reactivarla, se conservan los descartes guardados localmente en cada navegador.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Permitir de forma peligrosa el origen alternativo basado en la cabecera Host`},help:{"v1-1t1qi4c-7v":`Opción PELIGROSA que habilita el uso de un origen alternativo basado en la cabecera Host para las comprobaciones de WebSocket de Control UI/WebChat. Este modo es compatible con despliegues que dependen intencionadamente de una política de origen basada en la cabecera Host; la configuración explícita de gateway.controlUi.allowedOrigins sigue siendo la opción predeterminada recomendada para reforzar la seguridad.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Modo de aislamiento del contenido incrustado de Control UI`},help:{"v1-d54l3a-7c":'Política de aislamiento de iframe para el contenido incrustado alojado en Control UI. "strict" desactiva los scripts, "scripts" permite contenido incrustado interactivo manteniendo el aislamiento de origen (opción predeterminada), y "trusted" añade `allow-same-origin` para documentos del mismo sitio que necesitan intencionadamente mayores privilegios.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Control UI habilitada`},help:{"v1-1hhyymc-4w":`Permite servir la Control UI del Gateway desde el proceso HTTP del Gateway cuando se establece en true. Mantén esta opción habilitada para la administración local y desactívala cuando una interfaz de control externa la sustituya.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Entorno de Control UI`},help:{"v1-paarso-4n":`Identidad pública opcional del entorno que se muestra en la franja de Control UI, el avatar del agente, las etiquetas, el título del navegador y el favicon. Omítala para conservar la apariencia predeterminada.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Color del entorno de Control UI`},help:{"v1-mp6cta-2i":`Gama de colores del entorno identificada por nombre: teal, amber, purple, coral, pink, blue, green, red o gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Etiqueta del entorno de Control UI`},help:{"v1-1njve3z-3z":`Etiqueta del entorno que se muestra en Control UI y en la pestaña del navegador; se eliminan los espacios en blanco al principio y al final, y la etiqueta debe contener entre 1 y 24 caracteres.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`Funciones experimentales de Control UI`},help:{"v1-1qobi2m-3g":`Experimentos de Control UI de activación opcional. Estas funciones pueden cambiar entre versiones y permanecen desactivadas a menos que se activen explícitamente.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Interfaz de plugins personalizados`},help:{"v1-108u6ts-9e":`Permite que los plugins instalados por el usuario ejecuten JavaScript nativo en la Control UI (valor predeterminado: false). Las vistas de los plugins incluidos siguen estando disponibles. La interfaz personalizada comparte los permisos de Gateway del operador que ha iniciado sesión; actívala solo para plugins de confianza. Los cambios se aplican sin reiniciar el Gateway. Recarga las páginas abiertas de la Control UI para eliminar el código de plugins cargado anteriormente.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`Credencial de servicio de GitHub para Control UI`},help:{"v1-1p31phh-d6":`Credencial de servicio respaldada por SecretRef para la detección de proyectos de Control UI y las vistas previas de GitHub al pasar el cursor, sin una identidad administrada. Las vistas previas al pasar el cursor dan preferencia a la identidad de GitHub configurada para el agente seleccionado y heredan la identidad del sistema si no se ha definido una alternativa. Es preferible una configuración explícita para dejar clara la titularidad del servicio. Omítala para conservar el uso de GH_TOKEN/GITHUB_TOKEN como alternativa desde el entorno compartido del proceso de Gateway. Si una credencial configurada explícitamente no está disponible, se deniega el acceso.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Directorio raíz de los recursos de Control UI`},help:{"v1-elck04-25":`Directorio raíz opcional del sistema de archivos para los recursos de Control UI (predeterminado: dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Observador de sesiones de Control UI`},help:{"v1-1ahs80-8a":`Genera resúmenes en tiempo real del estado de las sesiones para los clientes suscritos de Control UI con el modelo auxiliar de cada agente (activado de forma predeterminada). Establezca el valor en false para desactivar las llamadas al modelo observador en todo Gateway; establecer agents.defaults.utilityModel en una cadena vacía desactiva la observación mediante el modelo auxiliar para los agentes que no lo sobrescriban.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Host de escucha personalizado de Gateway`},help:{"v1-lwjcyo-4d":`Dirección IPv4 utilizada para una escucha personalizada. Las direcciones IPv4 específicas también requieren el mismo puerto de Gateway en 127.0.0.1; evite 0.0.0.0 salvo que sea necesario exponer el servicio en todas las interfaces.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`API HTTP de Gateway`},help:{"v1-ebtex7-4j":`Configuración de la API HTTP de Gateway que agrupa los controles de activación de endpoints y los controles de exposición de la API en la capa de transporte. Mantenga activados solo los endpoints necesarios para reducir la superficie de ataque.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Endpoints HTTP de Gateway`},help:{"v1-1a0r104-55":`Controles de activación de endpoints HTTP en la API del Gateway para rutas de compatibilidad e integraciones opcionales. Habilite los endpoints de forma deliberada y supervise los patrones de acceso tras el despliegue.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`Endpoint de OpenAI Chat Completions`},help:{"v1-1271mpb-2b":"Habilita el endpoint `POST /v1/chat/completions` compatible con OpenAI (valor predeterminado: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Límites de imágenes de OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Controles de descarga y validación de imágenes para las partes `image_url` compatibles con OpenAI."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`Lista de tipos MIME permitidos para imágenes de OpenAI Chat Completions`},help:{"v1-1guijf3-1t":"Tipos MIME permitidos para las partes `image_url` (lista que no distingue entre mayúsculas y minúsculas)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`Permitir URL de imágenes en OpenAI Chat Completions`},help:{"v1-55cb3n-47":"Permite descargar desde URL en el servidor para las partes `image_url` (valor predeterminado: false; se mantiene la compatibilidad con los URI de datos). Establezca este valor en `false` para deshabilitar por completo las descargas desde URL."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`Máximo de bytes por imagen de OpenAI Chat Completions`},help:{"v1-d920yx-1s":"Máximo de bytes por imagen `image_url` descargada o decodificada (valor predeterminado: 10 MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`Máximo de redirecciones de imágenes de OpenAI Chat Completions`},help:{"v1-1enujsk-1z":"Número máximo de redirecciones HTTP permitidas al obtener las URL de `image_url` (predeterminado: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`Tiempo de espera de imágenes de OpenAI Chat Completions (ms)`},help:{"v1-89w2b9-1x":"Tiempo de espera en milisegundos para obtener las URL de `image_url` (predeterminado: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`Lista de URL permitidas para imágenes de OpenAI Chat Completions`},help:{"v1-n4hlt1-4r":"Lista opcional de nombres de host permitidos para obtener las URL de `image_url`; admite nombres de host exactos y comodines como `*.example.com`. Si la lista está vacía o se omite, no se aplican restricciones por nombre de host."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Cabeceras de seguridad HTTP de Gateway`},help:{"v1-n8z1hb-44":`Cabeceras de seguridad de respuesta HTTP opcionales aplicadas por el propio proceso de Gateway. Es preferible configurarlas en el proxy inverso si TLS termina allí.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Cabecera de seguridad de transporte estricta`},help:{"v1-1buwhc3-3v":`Valor de la cabecera de respuesta Strict-Transport-Security. Configúrelo solo en orígenes HTTPS que controle por completo; use false para desactivarlo explícitamente.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Modo de Gateway`},help:{"v1-nfjirv-5m":`Modo de funcionamiento de Gateway: "local" ejecuta los canales y el entorno de ejecución del agente en este host, mientras que "remote" se conecta mediante transporte remoto. Mantén "local" a menos que quieras ejecutar una topología dividida con un Gateway remoto.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Skills de nodos de Gateway habilitadas`},help:{"v1-1xwu6at-3g":`Acepta las Skills publicadas por los nodos vinculados mientras estén conectados (valor predeterminado: true). Establece false para ignorar las Skills publicadas por los nodos.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Modo de navegador de nodos de Gateway`},help:{"v1-oeu1nc-69":`Enrutamiento del navegador mediante nodos ("auto" = dar preferencia al navegador del host y usar un único nodo de navegador conectado cuando la funcionalidad local no esté disponible; "manual" = requerir una selección explícita de nodo o una asignación fija configurada; "off" = desactivar el enrutamiento mediante nodos).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Nodo fijo para el navegador de Gateway`},help:{"v1-1cykty2-1p":`Fija el enrutamiento del navegador a un ID o nombre de nodo específico (opcional).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Lista de permitidos de nodos de Gateway (comandos adicionales)`},help:{"v1-6l4otb-5m":"Comandos node.invoke adicionales que se permiten además de los predeterminados de Gateway (matriz de cadenas de comandos). Habilitar comandos peligrosos aquí supone una excepción con implicaciones de seguridad que `openclaw security audit` señala."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Lista de bloqueados de nodos de Gateway`},help:{"v1-u7c8wx-53":"Nombres de comandos de nodos que se bloquearán aunque figuren en las declaraciones del nodo o en la lista predeterminada de permitidos (solo coincidencias exactas del nombre del comando, p. ej., `system.run`; no inspecciona el texto de shell dentro de ese comando)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Vinculación de nodos de Gateway`},help:{"v1-gldsi2-4s":`Ajustes de la política de vinculación de nodos. La aprobación automática verificada por SSH está activada de forma predeterminada; la aprobación automática por CIDR permanece desactivada salvo que se configuren listas explícitas de CIDR/IP de confianza permitidos.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`CIDR para la aprobación automática de vinculación de nodos del Gateway`},help:{"v1-1m6jsxj-6x":`Lista opcional de CIDR/IP permitidos para aprobar automáticamente la primera vinculación de dispositivos con rol de nodo sin ámbitos solicitados. Se desactiva si no se configura. Las vinculaciones de operadores, navegadores y Control UI, así como cualquier vinculación que amplíe roles, ámbitos o metadatos, o que actualice la clave pública, siguen requiriendo aprobación manual.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Aprobación automática local de vinculación de nodos del Gateway`},help:{"v1-glzm36-41":`Aprueba sin avisar las vinculaciones locales de confianza y las ampliaciones de acceso (valor predeterminado: true); establece false para priorizar la aprobación explícita de cada dispositivo sobre la comodidad.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Verificación SSH de vinculación de nodos del Gateway`},help:{"v1-1e4da92-ct":"Aprobación automática verificada por SSH para la primera vinculación de dispositivos con rol de nodo (activada de forma predeterminada). El Gateway se conecta por SSH al host que solicita la vinculación (BatchMode, verificación estricta de las claves del host) y solo la aprueba cuando la salida remota de `openclaw node identity` coincide con la clave del dispositivo pendiente. Establece false para desactivar la verificación SSH (independientemente de autoApproveCidrs, que permanece activo); para permitir únicamente la vinculación manual, elimina también la configuración de autoApproveCidrs. Proporciona un objeto para sobrescribir user/identity/timeoutMs/cidrs."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Herramientas de plugins de nodos del Gateway`},help:{"v1-1c24iq3-28":`Controla si los nodos vinculados pueden publicar descriptores de herramientas de plugins visibles para el agente.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Herramientas de plugins de nodos del Gateway habilitadas`},help:{"v1-14lgfu6-47":`Acepta descriptores de herramientas de plugins visibles para el agente publicados por nodos emparejados (valor predeterminado: true). Establece false para ignorar y eliminar todas las herramientas de plugins publicadas por nodos.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Puerto del Gateway`},help:{"v1-for8t5-54":`Puerto TCP que utiliza el servicio de escucha del Gateway para la API, la Control UI y las rutas de entrada de los canales. Usa un puerto dedicado y evita conflictos con proxies inversos o servicios de desarrollo locales.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Portales de Gateway`},help:{"v1-1v2lkw9-1c":`Configuración de publicación de portales y de entrada privada.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Entrada privada a los portales`},help:{"v1-20w4gq-69":`Proxy inverso HTTPS privado opcional con dominio comodín, administrado por el operador. Reenvía el encabezado Host original, las rutas y las solicitudes de actualización a WebSocket al servicio de escucha dedicado de bucle local. La autenticación del portal mediante token de portador sigue siendo obligatoria. Requiere reiniciar Gateway.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Dominio comodín del portal`},help:{"v1-1ipbfad-53":`Dominio DNS sin prefijos para subdominios aleatorios del portal (por ejemplo, previews.example.net). Configura DNS comodín y HTTPS de forma privada; no compartas el espacio de nombres de host de Gateway ni de Control UI.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Puerto de bucle local de entrada al portal`},help:{"v1-1mb98cv-4g":`Puerto HTTP de loopback dedicado que recibe el tráfico del proxy HTTPS privado con comodín. Debe ser distinto del puerto de Gateway. Este es el puerto del backend, no el puerto HTTPS público.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Origen público del Gateway`},help:{"v1-17vekvx-87":`Origen HTTPS del Gateway accesible desde el exterior. HTTP solo se permite para localhost, 127.0.0.1 o [::1]. OAuth de MCP por solicitante lo utiliza para crear la URL de retorno en /oauth/mcp/callback; los enlaces de sesión de los canales y los enlaces de visualización generados por plugins lo utilizan para acceder a la Control UI y a las rutas del Gateway.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Envío de notificaciones push del Gateway`},help:{"v1-h23oz7-5s":`Configuración de envío de notificaciones push que utiliza el Gateway cuando necesita activar dispositivos emparejados o enviarles notificaciones. Configura aquí APNs mediante un servicio de retransmisión para las compilaciones oficiales de iOS; la autenticación directa de APNs sigue basándose en variables de entorno para las compilaciones locales o manuales.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Envío por APNs del Gateway`},help:{"v1-4bbafr-4e":`Configuración de envío por APNs para dispositivos iOS emparejados con este Gateway. Usa la configuración de retransmisión para las compilaciones oficiales de App Store que se registran a través del servicio externo de retransmisión de notificaciones push.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Servicio de retransmisión de APNs del Gateway`},help:{"v1-7glbel-6x":`Configuración del servicio de retransmisión externo para envíos APNs mediante retransmisión. El Gateway usa de forma predeterminada el servicio de retransmisión alojado de OpenClaw, o este servicio personalizado para push.test, avisos de activación y activaciones de reconexión después de que una compilación oficial de iOS emparejada publique un registro mediante retransmisión.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`URL base del servicio de retransmisión APNs del Gateway`},help:{"v1-1o8mgnq-69":`URL base HTTPS personalizada opcional para el servicio de retransmisión APNs externo que usan las compilaciones oficiales de iOS de App Store. Manténgala alineada con la URL de retransmisión integrada en la compilación de iOS para que el tráfico de registro y envío llegue al mismo despliegue.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Tiempo de espera del servicio de retransmisión APNs del Gateway (ms)`},help:{"v1-a0jkb1-4z":`Tiempo de espera en milisegundos para las solicitudes de envío del Gateway al servicio de retransmisión APNs (predeterminado: 10000). Auméntelo para servicios de retransmisión o redes más lentos, o redúzcalo para que los intentos de activación fallen antes.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Recarga de configuración`},help:{"v1-d02mvq-4w":`Política de recarga de configuración en vivo que determina cómo se aplican los cambios y cuándo se activan los reinicios completos. Mantenga el comportamiento híbrido para realizar actualizaciones operativas más seguras, salvo que esté depurando el funcionamiento interno de la recarga.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Modo de recarga de configuración`},help:{"v1-1q1etcf-3m":`Controla cómo se aplican los cambios de configuración: "off" ignora los cambios en vivo y "hybrid" aplica los cambios seguros en caliente y luego reinicia cuando es necesario.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Gateway remoto`},help:{"v1-6xv7gd-5a":`Configuración de conexión al Gateway remoto mediante transporte directo o SSH cuando esta instancia actúa como proxy hacia otro host de ejecución. Use el modo remoto solo cuando se haya configurado intencionalmente el funcionamiento en hosts separados.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`Cabeceras de autenticación perimetral del Gateway remoto`},help:{"v1-jg9p7d-5o":`Cabeceras HTTP respaldadas por secretos que se presentan a un proxy con reconocimiento de identidad situado delante del Gateway remoto configurado. Las cabeceras se envían únicamente al origen exacto de gateway.remote.url mediante WSS y nunca siguen redirecciones.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Contraseña del Gateway remoto`},help:{"v1-16jc0yx-7y":`Secreto compartido enviado en el campo de contraseña para autenticar este cliente ante un Gateway remoto. El parámetro gateway.auth.mode del servidor selecciona el secreto configurado; se acepta tanto el campo de token como el de contraseña del cliente. Mantén este secreto bajo gestión externa y evita valores en texto sin formato en la configuración guardada en el repositorio.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Política de claves de host SSH del Gateway remoto`},help:{"v1-7qoxtb-49":`Política de verificación de claves de host SSH en macOS. "strict" requiere una clave de host que ya sea de confianza; "openssh" delega explícitamente en la configuración efectiva de OpenSSH.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`Identidad SSH del Gateway remoto`},help:{"v1-hz2hsm-1f":`Ruta opcional del archivo de identidad SSH (se pasa a ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`Destino SSH del Gateway remoto`},help:{"v1-85w39w-2t":`Gateway remoto mediante SSH (redirige el puerto del Gateway a localhost a través de un túnel). Formato: user@host o user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`Huella TLS del Gateway remoto`},help:{"v1-1ri16lk-23":`Huella TLS sha256 esperada para el Gateway remoto (fíjala para evitar ataques MITM).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Token del Gateway remoto`},help:{"v1-1pb9q8w-7v":`Secreto compartido enviado en el campo token para autenticar este cliente ante un Gateway remoto. El valor de gateway.auth.mode del servidor selecciona el secreto configurado; se acepta tanto el campo token como el campo password del cliente. Almacénelo mediante sustitución de secretos o variables de entorno y rótelo cuando cambie la autenticación del Gateway remoto.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Transporte del Gateway remoto`},help:{"v1-1acfs7m-54":`Transporte de conexión remota: "direct" utiliza la conectividad de la URL configurada, mientras que "ssh" establece un túnel mediante SSH. Use SSH cuando necesite un túnel cifrado sin exponer puertos remotos.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`URL del Gateway remoto`},help:{"v1-va7exe-1b":`URL de WebSocket del Gateway remoto (ws:// o wss://).`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Roles de operador del Gateway`},help:{"v1-b59sc5-6w":`Roles de operador opcionales vinculados a perfiles para los Gateway de equipo. Cada rol con nombre controla el acceso a las sesiones de otras personas, el aislamiento del entorno aislado, los agentes de sesión y de ejecución, y los ámbitos de operador concedidos; omitir esta sección conserva el comportamiento actual del operador.`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`Rol de operador predeterminado`},help:{"v1-1v8add8-4u":`Rol obligatorio asignado a los perfiles autenticados sin una asignación explícita válida cuando se configuran roles de operador. Su nombre debe coincidir con una definición de rol configurada.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Definiciones de roles de operador`},help:{"v1-uv91an-53":`Definiciones de roles no vacías, con nombres asignados por el administrador, que agrupan el conjunto cerrado de políticas de uso compartido de sesiones, aislamiento del entorno aislado, acceso a agentes y ámbitos de operador aplicadas a los perfiles de usuario autenticados.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Definición del rol de operador`},help:{"v1-p8tfws-6q":`Un rol de operador con nombre. Cada definición debe especificar explícitamente su política de uso compartido de sesiones, los agentes permitidos para sesiones y ejecuciones, y el límite de permisos del operador. También puede exigir aislamiento en un entorno aislado para las sesiones recién creadas y una política de acceso mediante un plugin.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Plugin de política de acceso del rol de operador`},help:{"v1-1gq4q08-9n":`ID exacto y opcional del plugin cuya política de acceso a Gateway debe autorizar este rol. Se deniega el acceso cuando el plugin no está presente, está deshabilitado, no se carga correctamente o no proporciona una autorización vigente. Los ID de plugins no disponibles siguen siendo válidos en la configuración para que los roles independientes del personal y el propietario de Gateway puedan restablecer el acceso. Omitir este campo no añade ninguna dependencia de un plugin.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Agentes permitidos para el rol de operador`},help:{"v1-fvun18-4v":`Agentes disponibles cuando este rol crea sesiones o inicia ejecuciones: establece "*" para permitir todos los agentes, enumera los ID de los agentes para permitir solo esos agentes o usa una lista vacía para deshabilitar ambas acciones.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Aislamiento del rol de operador en un entorno aislado`},help:{"v1-sknx21-66":`Aislamiento de ejecución para las sesiones recién creadas: "inherit" (predeterminado) usa la política del agente; "required" exige permanentemente un entorno aislado, incluso cuando el modo de aislamiento del agente está desactivado, y bloquea la ejecución si el backend no está disponible.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Límite de permisos del rol de operador`},help:{"v1-1selr2i-4s":`Lista cerrada de permisos de operador concedidos como autoridad máxima de conexión de este rol. Los permisos solicitados, asociados mediante emparejamiento, concedidos por identidad y ampliados se limitan a su intersección con esta lista.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Acceso a sesiones del rol de operador`},help:{"v1-hsoiop-45":`Permisos de uso compartido de sesiones concedidos a este rol para las sesiones creadas por otras personas autenticadas; cada persona conserva el acceso a sus propias sesiones.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Acceso del rol de operador a otras sesiones`},help:{"v1-vf8umx-5r":`Acceso a las sesiones de otras personas: "none" las oculta, "view" permite leerlas, "suggest" permite el flujo de sugerencias y "write" permite participar. La pertenencia explícita a una sesión puede conceder acceso adicional.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Tailscale de Gateway`},help:{"v1-6ar9o-4x":`Ajustes de integración con Tailscale para la exposición mediante Serve/Funnel y la gestión del ciclo de vida al iniciar o cerrar el gateway. Mantén esta opción desactivada a menos que tu despliegue dependa intencionadamente del acceso entrante mediante Tailscale.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Modo de Tailscale de Gateway`},help:{"v1-6l2099-5a":`Modo de publicación de Tailscale: "off", "serve" o "funnel" para vías de exposición privadas o públicas. Usa "serve" para permitir el acceso solo desde la tailnet y "funnel" únicamente cuando se requiera acceso desde la Internet pública.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Protección de migración de Funnel externo de Tailscale de Gateway`},help:{"v1-1mntkor-7q":`Protección de migración obsoleta para mode='serve'. Si un Funnel externo sigue apuntando al listener habitual de Gateway, OpenClaw mantiene la exposición sin cambios y advierte de que solo se podrán usar los webhooks autenticados mediante plugins hasta que se configure la autenticación por contraseña y se migre el modo a 'funnel'.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Terminal del operador`},help:{"v1-18f5rgm-8b":`Terminal del operador disponible para Control UI y clientes móviles: un shell basado en PTY en el host del gateway, restringido a sesiones de operador con permisos de administración. Se inicia en el espacio de trabajo del agente de destino y se deniega para agentes totalmente aislados (sandbox.mode 'all'), en lugar de proporcionar un shell del host sin restricciones.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Tiempo de espera de las sesiones desconectadas del terminal del operador`},help:{"v1-k6qbgr-9e":`Segundos que una sesión de terminal permanece activa tras perder la conexión (suspensión del portátil, recarga de la página), durante los cuales es posible volver a conectarse mediante terminal.attach y recuperar su salida reciente. Establece 0 para finalizar las sesiones en cuanto se pierda la conexión. Valor predeterminado: 300 (5 minutos). Las sesiones desconectadas siguen ejecutando sus comandos, por lo que conviene reducir este tiempo en hosts compartidos o expuestos.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Terminal del operador habilitado`},help:{"v1-1nez06v-7p":`Habilita la terminal del operador para clientes con permisos de administración (valor predeterminado: true). Esto expone un shell en el navegador o en dispositivos móviles con el entorno del proceso de Gateway; establece el valor en false para deshabilitarlo en implementaciones donde los operadores administradores no deban tener acceso a un shell del host. Los cambios se aplican sin reiniciar Gateway.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Intérprete de comandos del terminal del operador`},help:{"v1-19mfe6t-5i":`Ejecutable del intérprete de comandos que inicia el terminal del operador. Déjalo sin configurar para usar el intérprete de inicio de sesión del host ($SHELL en Unix, %ComSpec% en Windows), o especifica un intérprete concreto para mantener un entorno de operador uniforme.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`TLS del Gateway`},help:{"v1-1dx77dq-4z":`Configuración del certificado y la clave TLS para terminar las conexiones HTTPS directamente en el proceso del Gateway. Usa certificados explícitos en producción y evita exponer datos en texto sin cifrar en redes no confiables.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Generación automática del certificado TLS del Gateway`},help:{"v1-1ld6uiu-4w":`Genera automáticamente un par local de certificado y clave TLS cuando no se han configurado archivos explícitos. Úsalo solo en entornos locales o de desarrollo y sustitúyelo por certificados reales para el tráfico de producción.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Ruta de CA TLS de Gateway`},help:{"v1-andqlu-52":`Ruta opcional al paquete de CA para la verificación de clientes o los requisitos de cadenas de confianza personalizadas en el perímetro de Gateway. Úsala cuando el despliegue incluya una PKI privada o cadenas de certificados personalizadas.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Ruta del certificado TLS de Gateway`},help:{"v1-1wznaof-4q":`Ruta en el sistema de archivos al archivo del certificado TLS que usa Gateway cuando TLS está habilitado. Usa rutas de certificados gestionadas y mantén la automatización de la renovación sincronizada con esta ubicación.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`TLS de Gateway habilitado`},help:{"v1-ykhwp0-4o":`Habilita la terminación TLS en el punto de escucha de Gateway para que los clientes se conecten directamente mediante HTTPS/WSS. Mantén esta opción habilitada si Gateway está expuesto directamente a Internet o en cualquier límite con una red no confiable.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Ruta de la clave TLS de Gateway`},help:{"v1-15knri0-4i":`Ruta en el sistema de archivos al archivo de la clave privada TLS que usa Gateway cuando TLS está habilitado. Mantén restringidos los permisos de este archivo de clave y rótala según tu política de seguridad.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Política de exposición de herramientas de Gateway`},help:{"v1-1ffol26-5a":`Política de permisos y denegaciones de exposición de herramientas a nivel de Gateway que puede restringir la disponibilidad de herramientas durante la ejecución, independientemente de los perfiles de agentes o herramientas. Úsala para controles generales de emergencia y para reforzar la seguridad en producción.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Lista de herramientas permitidas de Gateway`},help:{"v1-163khb1-4y":`Lista explícita de herramientas permitidas a nivel de Gateway para cuando quieras disponer de un conjunto reducido de herramientas durante la ejecución. Úsala en entornos restringidos donde el alcance de las herramientas deba controlarse estrictamente.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Lista de herramientas denegadas de Gateway`},help:{"v1-1lhssnf-4o":`Lista explícita de herramientas denegadas a nivel de Gateway para bloquear herramientas de riesgo incluso si las políticas de niveles inferiores las permiten. Usa reglas de denegación para responder a emergencias y reforzar la defensa en profundidad.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`CIDR de proxies de confianza de Gateway`},help:{"v1-n5zcvf-4f":`Lista de CIDR/IP permitidos de proxies intermediarios autorizados a proporcionar cabeceras reenviadas de identidad del cliente. Mantén esta lista restringida para que los saltos no confiables no puedan suplantar a los usuarios.`}},hooks:{label:{"v1-j9ywl7-5":`Ganchos`},help:{"v1-1mzh0ry-5v":`Interfaz de automatización mediante webhooks entrantes para asignar eventos externos a acciones de activación o de agente en OpenClaw. Mantén su acceso restringido mediante controles explícitos de tokens, sesiones y agentes antes de exponerla fuera de redes de confianza.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`ID de agentes permitidos para hooks`},help:{"v1-hree88-7c":`Lista de ID de agentes efectivos a los que pueden dirigirse las solicitudes y asignaciones de hooks, incluido el enrutamiento al agente predeterminado cuando se omite agentId. Úsala para limitar los eventos de automatización a agentes de servicio dedicados y reducir el alcance del impacto si se expone un token de hook.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Prefijos de claves de sesión permitidos para hooks`},help:{"v1-b346oh-4r":`Lista de prefijos de claves de sesión aceptados para las solicitudes de hooks entrantes cuando están habilitadas las claves proporcionadas por el solicitante. Usa prefijos específicos para evitar la inyección de claves de sesión arbitrarias.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Permitir claves de sesión en solicitudes de hooks`},help:{"v1-11n9ps-52":`Permite a los solicitantes proporcionar una clave de sesión en las solicitudes de hooks cuando el valor es true, lo que habilita el enrutamiento controlado por el solicitante. Mantén el valor en false a menos que los integradores de confianza necesiten explícitamente una agrupación personalizada de conversaciones por sesión.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Clave de sesión predeterminada para hooks`},help:{"v1-bzdgkn-57":`Clave de sesión de respaldo que se usa para las entregas de hooks cuando una solicitud no proporciona una a través de los canales permitidos. Usa una clave estable, pero de alcance limitado, para evitar mezclar conversaciones de automatización no relacionadas.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Hooks habilitados`},help:{"v1-1mixmjf-4n":`Habilita el endpoint de hooks y el flujo de ejecución de asignaciones para las solicitudes de webhooks entrantes. Mantenlo deshabilitado a menos que estés enrutando activamente eventos externos al Gateway.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Hook de Gmail`},help:{"v1-4cibmt-4r":`Configuración de la integración push de Gmail para las notificaciones de Pub/Sub y la recepción local opcional de llamadas de retorno. Siempre que sea posible, limita su uso a cuentas de Gmail dedicadas a la automatización.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Cuenta del hook de Gmail`},help:{"v1-12l1h96-4v":`Identificador de la cuenta de Google que se usa para las operaciones de vigilancia y suscripción de Gmail en esta integración de hooks. Usa una cuenta de correo dedicada a la automatización para aislar los permisos operativos.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Permitir contenido externo no seguro en el hook de Gmail`},help:{"v1-1w3gdvs-55":`Cuando está habilitado, permite que el contenido externo de Gmail pase al procesamiento con menos depuración de seguridad. Mantenlo deshabilitado para conservar una configuración predeterminada más segura y habilítalo solo para flujos de correo de confianza con transformaciones controladas.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`URL de llamada de retorno del hook de Gmail`},help:{"v1-19fhn6q-4z":`URL pública de llamada de retorno que Gmail o los intermediarios invocan para entregar notificaciones a este flujo de hooks. Mantén esta URL protegida mediante la validación de tokens y un acceso de red restringido.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Incluir el cuerpo en el hook de Gmail`},help:{"v1-14cf1c3-52":`Cuando es true, obtiene e incluye el contenido del cuerpo del correo para su posterior asignación o procesamiento por el agente. Mantén false salvo que se necesite el texto del cuerpo, ya que esto aumenta el tamaño y la sensibilidad de los datos enviados.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Etiqueta del hook de Gmail`},help:{"v1-9zpdg8-4g":`Filtro opcional de etiquetas de Gmail que limita qué mensajes etiquetados activan eventos del hook. Mantén los filtros acotados para evitar saturar las automatizaciones con mensajes no relacionados de la bandeja de entrada.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Máximo de bytes del cuerpo del hook de Gmail`},help:{"v1-2aaxx1-4b":`Cantidad máxima de bytes de datos de Gmail que se procesan por evento cuando includeBody está habilitado. Mantén límites conservadores para reducir el costo y el riesgo de procesar mensajes demasiado grandes.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Modelo alternativo del hook de Gmail`},help:{"v1-1var65t-59":`Modelo alternativo opcional para las ejecuciones activadas por Gmail cuando las automatizaciones del buzón deban usar un comportamiento de modelo específico. Déjalo sin configurar para heredar los valores predeterminados del agente, salvo que las tareas del buzón requieran especialización.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Token de notificaciones push del hook de Gmail`},help:{"v1-h1vx01-4o":`Token secreto compartido requerido en las llamadas de retorno del hook de notificaciones push de Gmail antes de procesar las notificaciones. Usa la sustitución mediante variables de entorno y rota el token si los puntos de conexión de las llamadas de retorno están expuestos al exterior.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Intervalo de renovación del hook de Gmail (min)`},help:{"v1-pr1z9-49":`Frecuencia de renovación en minutos de las suscripciones de seguimiento de Gmail para evitar que caduquen. Establece un intervalo inferior a los plazos de caducidad del proveedor y supervisa los fallos de renovación en los registros.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Servidor local del hook de Gmail`},help:{"v1-hom4wq-54":`Bloque de configuración del servidor local de callbacks para recibir notificaciones de Gmail directamente, sin una capa de entrada independiente. Habilítelo solo cuando este proceso deba gestionar por sí mismo el tráfico de webhooks.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Dirección de escucha del servidor de hooks de Gmail`},help:{"v1-55bieu-4d":`Dirección de escucha del servidor HTTP local de callbacks de Gmail que se utiliza al atender hooks directamente. Limítela a la interfaz de bucle local, a menos que se requiera expresamente la entrada de tráfico externo.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Ruta del servidor de hooks de Gmail`},help:{"v1-1jqhcw4-4h":`Ruta HTTP del servidor local de callbacks de Gmail en la que se aceptan notificaciones push. Manténgala alineada con la configuración de la suscripción para evitar la pérdida de eventos.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Puerto del servidor de hooks de Gmail`},help:{"v1-1yku7dz-43":`Puerto del servidor HTTP local de callbacks de Gmail cuando el modo de servidor está habilitado. Use un puerto dedicado para evitar conflictos con las interfaces del Gateway o de control.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Suscripción del hook de Gmail`},help:{"v1-127h8vg-5b":`Suscripción de Pub/Sub que utiliza el Gateway para recibir notificaciones de cambios de Gmail desde el tema configurado. Defina claramente quién gestiona la suscripción para evitar que varios consumidores compitan de forma inesperada.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale del hook de Gmail`},help:{"v1-7jzidp-4l":`Bloque de configuración de exposición de Tailscale para publicar callbacks de Gmail a través de rutas de Serve/Funnel. Use modos privados de tailnet antes de habilitar cualquier ruta de entrada pública.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Modo de Tailscale del hook de Gmail`},help:{"v1-vhm395-4u":`Modo de exposición de Tailscale para las llamadas de retorno de Gmail: "off", "serve" o "funnel". Usa "serve" para la entrega privada a través de la tailnet y "funnel" solo cuando se requiera acceso desde la internet pública.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Ruta de Tailscale para el hook de Gmail`},help:{"v1-fr8qi-4m":`Ruta publicada por Tailscale Serve/Funnel para reenviar las llamadas de retorno de Gmail cuando está habilitado. Mantenla alineada con la configuración del webhook de Gmail para que las solicitudes lleguen al controlador esperado.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Destino de Tailscale para el hook de Gmail`},help:{"v1-1twwxge-47":`Destino del servicio local al que Tailscale Serve/Funnel reenvía el tráfico (por ejemplo, http://127.0.0.1:8787). Usa destinos de bucle local explícitos para evitar ambigüedades de enrutamiento.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Ajuste del razonamiento para el hook de Gmail`},help:{"v1-17owk9q-4z":`Ajuste del esfuerzo de razonamiento para las ejecuciones del agente activadas por Gmail: "off", "minimal", "low", "medium" o "high". Mantén valores predeterminados moderados para las automatizaciones rutinarias de la bandeja de entrada a fin de controlar el coste y la latencia.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Tema de Pub/Sub para el hook de Gmail`},help:{"v1-iled0e-4p":`Nombre del tema de Google Pub/Sub que la supervisión de Gmail utiliza para publicar notificaciones de cambios de esta cuenta. Asegúrate de que IAM del tema conceda a Gmail permisos de publicación antes de habilitar la supervisión.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Hooks internos`},help:{"v1-piq9k-4v":`Configuración de ejecución de los hooks internos para los controladores de eventos incluidos o personalizados que se cargan desde rutas de módulos. Úsala para automatizaciones de confianza dentro del proceso y limita estrictamente el alcance de la carga de controladores.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Hooks internos habilitados`},help:{"v1-1wv0289-4c":`Habilita el procesamiento de hooks internos y entradas configuradas en el entorno de ejecución de hooks internos. Manténgalo deshabilitado salvo que los hooks internos se hayan configurado intencionadamente.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Entradas de hooks internos`},help:{"v1-1ovi38l-4o":`Registros de entradas de hooks internos configurados que se usan para registrar manejadores concretos del entorno de ejecución y metadatos. Mantenga las entradas explícitas y versionadas para que el comportamiento en producción sea auditable.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Cargador de hooks internos`},help:{"v1-11re5ph-4p":`Configuración del cargador de hooks internos que controla dónde se buscan los módulos de manejadores al iniciar. Use directorios raíz de carga restringidos para reducir los conflictos accidentales entre módulos o la ocultación de unos por otros.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Directorios adicionales de hooks internos`},help:{"v1-1xfdqxg-4c":`Directorios adicionales donde se buscan módulos de hooks internos, además de las rutas de carga predeterminadas. Mantenga esta lista al mínimo y bajo control para reducir la ocultación accidental de unos módulos por otros.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Asignaciones de hooks`},help:{"v1-frhp3v-5i":`Reglas de asignación ordenadas que identifican las solicitudes de hooks entrantes y eligen acciones de activación o de agente, con enrutamiento de entrega opcional. Coloque primero las asignaciones específicas para evitar que las reglas con patrones amplios capturen todo.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Acción de asignación de hooks`},help:{"v1-1r5zt5f-5f":`Tipo de acción de asignación: "wake" inicia el flujo de activación del agente, mientras que "agent" envía directamente al procesamiento del agente. Use "agent" para la ejecución inmediata y "wake" cuando se prefiera el procesamiento basado en latidos.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`ID del agente de la asignación de hooks`},help:{"v1-l0uioz-4y":`ID del agente de destino para ejecutar la asignación cuando el enrutamiento de acciones no deba usar los valores predeterminados. Usa agentes de automatización dedicados para aislar el comportamiento del webhook de las sesiones interactivas del operador.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Permitir contenido externo no seguro en la asignación del hook`},help:{"v1-1np9426-57":`Cuando se establece en true, el contenido de la asignación puede incluir datos de cargas útiles externas con menor saneamiento en los mensajes generados. Mantén false de forma predeterminada y actívalo solo para fuentes de confianza cuya lógica de transformación se haya revisado.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Canal de entrega de la asignación del hook`},help:{"v1-oz7pu5-5s":`Canal de entrega que sustituye al predeterminado para las salidas de la asignación (por ejemplo, "last", "telegram", "discord", "slack", "signal", "imessage" o "msteams"). Define explícitamente las sustituciones de canal para evitar envíos accidentales a otros canales.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Entregar la respuesta de la asignación del hook`},help:{"v1-12tbbam-5o":`Controla si los resultados de la ejecución de la asignación se entregan a un destino de canal o se procesan silenciosamente. Desactiva la entrega para las automatizaciones en segundo plano que no deban publicar salidas visibles para el usuario.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Clave de distribución de la asignación del hook`},help:{"v1-1d593op-7e":`Clave de un array de nivel superior en la carga útil sobre el que se distribuye la asignación: cada elemento desencadena su propia acción, y las plantillas o transformaciones reciben una carga útil cuyo array contiene solo el elemento actual. La configuración predefinida de Gmail usa forEach: messages para que las notificaciones por lotes desencadenen una ejecución por correo electrónico.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`ID de la asignación del hook`},help:{"v1-q1t4zw-57":`Identificador estable opcional de una entrada de asignación de hook, utilizado para auditorías, resolución de problemas y actualizaciones específicas. Usa identificadores únicos para que los registros y las diferencias de configuración puedan hacer referencia a las asignaciones sin ambigüedad.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Coincidencia de la asignación de hook`},help:{"v1-6u73k2-5a":`Objeto que agrupa los criterios de coincidencia de la asignación, como la ruta y el origen, antes de aplicar el enrutamiento de acciones. Define criterios de coincidencia específicos para que el tráfico de webhooks no relacionado no active automatizaciones.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Ruta de coincidencia de la asignación de hook`},help:{"v1-1d7dc5j-4k":`Condición de coincidencia de ruta para una asignación de hook, que normalmente se compara con la ruta de la solicitud entrante. Úsala para diferenciar el comportamiento de la automatización según las familias de rutas de los endpoints de webhooks.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Origen de coincidencia de la asignación de hook`},help:{"v1-177zgy7-52":`Condición de coincidencia de origen para una asignación de hook, normalmente establecida mediante metadatos de confianza de sistemas previos o la lógica del adaptador. Usa identificadores de origen estables para que el enrutamiento siga siendo determinista en los reintentos.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Plantilla de mensaje de la asignación de hook`},help:{"v1-ggqszl-5c":`Plantilla para convertir los datos de entrada estructurados de la asignación en el contenido final del mensaje enviado a la ruta de acción de destino. Mantén las plantillas deterministas para que el análisis y el comportamiento posteriores permanezcan estables.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Anulación del modelo de la asignación de hook`},help:{"v1-10qyo4j-5e":`Anulación opcional del modelo para las ejecuciones activadas por la asignación cuando la automatización deba usar un modelo distinto del predeterminado del agente. Úsala con moderación para que el comportamiento siga siendo predecible entre las ejecuciones de la asignación.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Nombre de la asignación del hook`},help:{"v1-zrd9tn-4v":`Nombre legible de la asignación que se muestra en los diagnósticos y las interfaces de configuración para operadores. Usa nombres concisos y descriptivos para que el propósito del enrutamiento resulte evidente durante la revisión de incidentes.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Clave de sesión de la asignación del hook`},help:{"v1-lfnt1n-58":`Anulación explícita de la clave de sesión para los mensajes entregados mediante la asignación, a fin de controlar la continuidad del hilo. Usa claves estables con un ámbito definido para que los eventos repetidos se correlacionen sin mezclarse con conversaciones no relacionadas.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Modo de sesión de la asignación del hook`},help:{"v1-1ggtdze-5k":`Controla la continuidad de la sesión de la asignación: "isolated" inicia una nueva sesión de ejecución, mientras que "persistent" reutiliza la sessionKey resuelta. Mantén isolated a menos que la integración necesite expresamente un contexto duradero.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Plantilla de texto de la asignación del hook`},help:{"v1-1rg732b-4y":`Plantilla alternativa de solo texto que se usa cuando no se desea o no se admite la representación enriquecida de la carga útil. Úsala para proporcionar un resumen conciso y uniforme en las interfaces de entrega de mensajes de chat.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Anulación del razonamiento de la asignación del hook`},help:{"v1-17hq8me-57":`Ajuste opcional del esfuerzo de razonamiento para las ejecuciones activadas por la asignación, que permite equilibrar la latencia y la profundidad del razonamiento. Mantén un nivel bajo o mínimo para hooks de alto volumen, salvo que se requiera claramente un razonamiento más profundo.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Tiempo de espera de la asignación del hook (s)`},help:{"v1-1r44ox2-4i":`Tiempo máximo permitido para ejecutar la acción de la asignación antes de aplicar la gestión del tiempo de espera agotado. Usa límites más estrictos para fuentes de webhooks de alto volumen a fin de evitar acumulaciones en la cola.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Destino de entrega de la asignación del hook`},help:{"v1-1p7928e-55":`Identificador de destino dentro del canal seleccionado cuando las respuestas de la asignación deban dirigirse a un destino fijo. Verifica los formatos de destino específicos del proveedor antes de habilitar asignaciones en producción.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Transformación de la asignación del hook`},help:{"v1-14igxpm-5m":`Bloque de configuración de la transformación que define el módulo y la exportación para el preprocesamiento antes de gestionar la acción de la asignación. Usa únicamente transformaciones cuyo código se haya revisado y mantén un comportamiento determinista para que la automatización sea reproducible.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Exportación de la transformación del hook`},help:{"v1-atn8v-4b":`Exportación con nombre que se invocará desde el módulo de transformación; si se omite, se usa la exportación predeterminada del módulo. Configura este valor cuando un archivo contenga varios controladores de transformación.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Módulo de transformación del hook`},help:{"v1-56futq-4v":`Ruta relativa del módulo de transformación que se carga desde hooks.transformsDir para reescribir las cargas útiles entrantes antes de su entrega. Mantén los módulos locales, revisados y libres de patrones de recorrido de directorios.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Modo de activación de la asignación de hooks`},help:{"v1-1dzqfnw-59":`Modo de programación de la activación: "now" activa inmediatamente, mientras que "next-heartbeat" pospone la activación hasta el siguiente ciclo de latido. Usa el modo diferido para automatizaciones de menor prioridad que puedan tolerar un ligero retraso.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Ruta del endpoint de hooks`},help:{"v1-1l9ijzv-4u":"Ruta HTTP que utiliza el endpoint de hooks (por ejemplo, `/hooks`) en el servidor de control del gateway. Usa una ruta difícil de adivinar y combínala con la validación de tokens para una defensa en profundidad."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Ajustes preestablecidos de hooks`},help:{"v1-dp8m0l-4v":`Conjuntos con nombre de ajustes preestablecidos de hooks que se aplican durante la carga para establecer asignaciones estándar y comportamientos predeterminados. Mantén explícito el uso de estos ajustes para que los operadores puedan auditar qué automatizaciones están activas.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Token de autenticación de hooks`},help:{"v1-1ihf6mv-82":`Token de portador compartido que el punto de entrada de hooks comprueba para autenticar las solicitudes antes de ejecutar las asignaciones. Considera a sus titulares como solicitantes de plena confianza para la interfaz de entrada de hooks, no como un rol independiente sin privilegios de propietario. Usa la sustitución mediante variables de entorno y renueva el token periódicamente cuando los endpoints de webhooks sean accesibles desde Internet.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Directorio de transformaciones de hooks`},help:{"v1-1ayj9p0-4t":`Directorio base de los módulos de transformación de hooks a los que hacen referencia las rutas transform.module de las asignaciones. Usa un directorio de repositorio controlado para que las importaciones dinámicas sigan siendo revisables y predecibles.`}},logging:{label:{"v1-rq08xq-7":`Registro`},help:{"v1-11an9pb-5e":`Controles del comportamiento del registro: gravedad, destinos de salida, formato y ocultación de datos sensibles. Mantén los niveles y la ocultación lo suficientemente estrictos para producción, sin perder información de diagnóstico útil.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Registro de auditoría`},help:{"v1-1lauvy2-6w":`Historial de auditoría limitado que solo contiene metadatos para la revisión por parte del operador. Los registros de ejecuciones y herramientas están habilitados de forma predeterminada; los metadatos del ciclo de vida de los mensajes requieren una activación independiente por sus implicaciones para la privacidad. La escritura en segundo plano se realiza en la medida de lo posible y no constituye un archivo de cumplimiento normativo sin pérdida de datos.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Registro de auditoría habilitado`},help:{"v1-snknxb-4v":`Registra nuevos eventos de auditoría de ejecuciones, herramientas y mensajes habilitados. Valor predeterminado: true. Los cambios se aplican de inmediato; las escrituras aceptadas se completan y las filas retenidas siguen disponibles para consulta hasta que caducan.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Auditoría de identidad de ejecución`},help:{"v1-1ucirwv-5b":`Conserva una atribución acotada de la identidad de ejecución para inspeccionar ejecuciones específicas. Valor predeterminado: false. Requiere logging.audit.enabled y se aplica a las ejecuciones recién admitidas; los contextos existentes no cambian.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Alcance de la auditoría de mensajes`},help:{"v1-1yg4lc3-76":`Controla los registros del ciclo de vida de los mensajes sin incluir su contenido: "off" (valor predeterminado), "direct" solo para conversaciones directas conocidas o "all" para conversaciones directas, de grupo, de canal y de tipo desconocido. Requiere logging.audit.enabled. Los cambios se aplican a los eventos posteriores del ciclo de vida.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Nivel de registro de la consola`},help:{"v1-16badbd-5u":`Umbral de registro específico de la consola: "silent", "fatal", "error", "warn", "info", "debug" o "trace" para controlar la salida del terminal. Úsalo para reducir los mensajes en la consola local y mantener un registro más detallado en archivos si es necesario.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Estilo de registro de la consola`},help:{"v1-d7u0iq-3q":`Estilo de formato de salida de la consola: "pretty" o "json". Usa json para flujos de procesamiento automatizado y pretty para flujos de trabajo en el terminal orientados a la lectura humana.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Ruta del archivo de registro`},help:{"v1-16gaitv-4w":`Ruta de archivo opcional para guardar la salida del registro, además del registro en consola o en su lugar. Usa una ruta administrada con permisos de escritura y ajusta la retención y la rotación a tu política operativa.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Nivel de registro`},help:{"v1-1r5yku0-5o":`Umbral principal del nivel de registro para la salida durante la ejecución: "silent", "fatal", "error", "warn", "info", "debug" o "trace". Mantén "info" o "warn" en producción y usa debug/trace solo durante la investigación de problemas.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Patrones de ocultación personalizados`},help:{"v1-1esa6eg-7k":`Las cadenas de expresiones regulares personalizadas sustituyen la lista de cadenas predeterminada para la salida de registros y transcripciones y se añaden a las reglas de los límites de seguridad para la interfaz de usuario, las herramientas y los diagnósticos. Las protecciones integradas para cuerpos de formularios, autenticación estructurada y claves de AWS sin formato siempre se aplican. Utilice esta opción para ocultar tokens e identificadores específicos de la implementación.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Definiciones globales de servidores MCP administradas por OpenClaw. OpenClaw integrado y otros adaptadores de entornos de ejecución pueden utilizar estos servidores sin almacenarlos en la configuración del proyecto propia del entorno de ejecución.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`Aplicaciones MCP`},help:{"v1-amyd91-38":`Compatibilidad con la interfaz de MCP Apps. Cuando está habilitada, los servidores MCP configurados pueden proporcionar vistas HTML interactivas para los resultados de sus herramientas.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps habilitado`},help:{"v1-ghqy98-3w":`Renderizado de MCP Apps y puente entre aplicaciones y servidores de activación opcional. Mantén esta opción deshabilitada a menos que confíes en los servidores MCP configurados que proporcionan recursos de interfaz para las aplicaciones.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Origen del entorno aislado de MCP Apps`},help:{"v1-1sxv3mf-6v":`Origen HTTP(S) público dedicado opcional para MCP Apps. Úsalo detrás de un proxy inverso o un terminador TLS y redirige su tráfico únicamente al puerto configurado del entorno aislado de MCP Apps. Debe ser distinto del origen de Control UI y no debe servir contenido autenticado.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Puerto del entorno aislado de MCP Apps`},help:{"v1-1b8n71l-4p":`Puerto de escucha dedicado del entorno aislado de MCP Apps. De forma predeterminada, es el puerto de Gateway más uno. Establece un puerto libre si otro servicio local o perfil de Gateway ya ocupa ese puerto.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`Servidores MCP`},help:{"v1-157ozoz-42":`Definiciones de servidores MCP con nombre. OpenClaw las almacena en su propia configuración y los adaptadores del entorno de ejecución deciden qué transportes se admiten durante la ejecución.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`Autenticación del servidor MCP`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`Certificado de cliente MCP`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`Clave de cliente MCP`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`Certificado de cliente MCP`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`Clave de cliente MCP`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Proyección MCP de Codex`},help:{"v1-slcmq1-6x":`Metadatos de proyección de OpenClaw solo para hilos de Codex app-server. No afecta a las sesiones ACP ni a la configuración genérica del entorno de ejecución de Codex. Omite este bloque para mantener el servidor disponible para todos los agentes de Codex app-server con el comportamiento predeterminado de aprobación MCP de Codex.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Agentes MCP de Codex`},help:{"v1-8q98n8-67":`Identificadores opcionales y no vacíos de agentes de OpenClaw que deben recibir este servidor MCP en la configuración de hilos de Codex app-server. Las listas vacías, en blanco o no válidas bloquean el acceso por seguridad; si se omiten, el servidor se proyecta para todos los agentes de Codex app-server.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Aprobación de herramientas MCP de Codex`},help:{"v1-1xql0qr-3d":`Nombre nativo de Codex para el mismo modo de aprobación de herramientas MCP por servidor. Usa preferentemente defaultToolsApprovalMode en la configuración de OpenClaw.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Aprobación de herramientas MCP de Codex`},help:{"v1-y5vsqq-3s":`Modo opcional de aprobación de herramientas MCP de Codex para este servidor: "auto", "prompt" o "approve". Úsalo solo para servidores MCP en los que confíes de forma explícita.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`Tiempo de espera de conexión MCP (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`Servidor MCP habilitado`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`OAuth de MCP`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`Perfil de autenticación OAuth de MCP`},help:{"v1-fcrb4u-5z":`ID del perfil de autenticación con capacidad de renovación que se usa para inyectar el token de portador actual en este servidor MCP remoto. Cuando se configura, OpenClaw resuelve y renueva el perfil en tiempo de ejecución y no transmite los datos de renovación a los componentes posteriores.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`URL de metadatos del cliente OAuth de MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`Identidad OAuth de MCP`},help:{"v1-1ie6ys7-59":`Titularidad de las credenciales OAuth de este servidor. Omite este campo o usa "shared" para las credenciales gestionadas por el operador; usa "per-requester" para que cada remitente autenticado pueda conectar su propia cuenta.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`URL de redirección OAuth de MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`Ámbito OAuth de MCP`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Tiempo de espera de las solicitudes MCP (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`Verificación TLS de MCP`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`Verificación TLS de MCP`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Llamadas en paralelo a herramientas MCP`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Llamadas en paralelo a herramientas MCP`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`Selección de herramientas MCP`},help:{"v1-10poyzb-4v":`Selección de herramientas MCP por servidor. Usa include para exponer solo los nombres de herramientas MCP seleccionados, o exclude para ocultarlos. Las entradas admiten nombres exactos y patrones simples con el comodín '*'.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Herramientas MCP excluidas`},help:{"v1-ijrc5y-1u":`Nombres exactos de herramientas MCP o patrones simples con '*' para ocultar herramientas de este servidor.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Herramientas MCP incluidas`},help:{"v1-89fdfq-3o":`Nombres exactos de herramientas MCP o patrones simples con '*' para exponer herramientas de este servidor. Si se omite, todas las herramientas del servidor siguen siendo aptas, salvo las excluidas.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL de inactividad de la sesión MCP (ms)`},help:{"v1-j9si74-87":`Eliminación opcional por inactividad de los entornos de ejecución MCP de las sesiones de OpenClaw, en milisegundos. Si no se establece o es 0, los entornos se mantienen activos hasta la limpieza de la sesión o el apagado de Gateway. Los valores positivos se redondean hacia abajo; las reservas activas y las adquisiciones pendientes impiden la eliminación. Los entornos asociados a una ejecución se siguen retirando cuando finaliza su ejecución única.`}},memory:{label:{"v1-oopaku-6":`Memoria`},help:{"v1-1wlx40m-13":`Configuración de la memoria integrada (global).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Modo de citas de la memoria`},help:{"v1-1q6dxr5-4u":`Controla la visibilidad de las citas en las respuestas: "auto" muestra las citas cuando son útiles, "on" las muestra siempre y "off" las oculta. Mantenga "auto" como valor predeterminado para equilibrar la información útil y el ruido.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Búsqueda en la memoria`},help:{"v1-1ukbud1-25":`Búsqueda vectorial en MEMORY.md y memory/*.md (admite ajustes específicos por agente).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Caché de embeddings de búsqueda en la memoria`},help:{"v1-d8h2e4-5b":`Almacena en caché en SQLite los embeddings calculados de los fragmentos para acelerar la reindexación y las actualizaciones incrementales (valor predeterminado: true). Mantenga esta opción activada, salvo que esté investigando la integridad de la caché o minimizando el uso del disco.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Tipo de entrada de documentos para la búsqueda en la memoria`},help:{"v1-1ui33sv-5f":"Valor opcional de `input_type` específico del proveedor para las representaciones vectoriales de memoria de documentos e indexación. Úsalo con endpoints de representaciones vectoriales asimétricas compatibles con OpenAI que requieran una etiqueta de pasaje o documento."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Activar la búsqueda en memoria`},help:{"v1-14f11b9-4t":`Interruptor principal que controla la indexación y la recuperación de la búsqueda en memoria en este perfil de agente. Mantenlo activado para la recuperación semántica y desactívalo cuando quieras respuestas completamente sin estado.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Índice de sesiones para la búsqueda en memoria (experimental)`},help:{"v1-qvhv8z-3i":`Indexa las transcripciones de sesiones para la búsqueda en memoria. Mantén esta configuración avanzada cuando la herencia de la recuperación difiera entre el nivel raíz y el de cada agente.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Rutas de memoria adicionales`},help:{"v1-ojqokq-7i":`Añade directorios o archivos .md adicionales al índice de memoria, además de los archivos de memoria predeterminados. Las entradas pueden ser cadenas de ruta u objetos con un patrón glob relativo a la raíz. Cuando la memoria multimodal está activada, los archivos de imagen o audio coincidentes en estas rutas también pueden indexarse.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Ruta de memoria adicional`},help:{"v1-b9mbq8-3m":`Establece el directorio o archivo de memoria adicional. Las rutas relativas se resuelven desde el espacio de trabajo del agente; las entradas que apuntan directamente a archivos se indexan tal cual.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Patrón de ruta de memoria adicional`},help:{"v1-j8br1v-4e":`Limita una entrada de directorio a los archivos compatibles que coincidan con este patrón glob relativo a la raíz, por ejemplo "runbooks/**/*.md". Omítelo para examinar todos los archivos compatibles de forma recursiva.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Proveedor de respaldo para la búsqueda en memoria`},help:{"v1-1r6368w-6p":`Proveedor de respaldo que se utiliza cuando falla la generación principal de representaciones vectoriales: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" o "none". Configura un proveedor de respaldo real para garantizar la fiabilidad en producción; usa "none" solo si prefieres que los fallos sean explícitos.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Tipo de entrada de la búsqueda en memoria`},help:{"v1-26vbwe-5u":"Usa este valor opcional de `input_type`, específico del proveedor, solo cuando la misma etiqueta deba aplicarse a las solicitudes de representaciones vectoriales tanto de consultas como de documentos. Para los proveedores asimétricos, es preferible usar queryInputType y documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Ruta del modelo local de representaciones vectoriales`},help:{"v1-13ymbnt-5q":"Especifica el origen del modelo local de representaciones vectoriales para la búsqueda local en memoria, como una ruta de archivo GGUF o un URI `hf:`. Úsalo solo cuando el proveedor sea `local` y verifica la compatibilidad del modelo antes de reconstruir índices grandes."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Modelo de búsqueda en memoria`},help:{"v1-11pohrl-59":`Modelo de representaciones vectoriales alternativo que utiliza el proveedor de memoria seleccionado cuando se requiere un modelo distinto del predeterminado. Configúralo solo cuando necesites ajustar explícitamente la calidad de recuperación o el coste más allá de los valores predeterminados del proveedor.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Búsqueda multimodal en memoria`},help:{"v1-1jn02s-9e":'Ajustes opcionales de memoria multimodal para indexar archivos de imagen y audio de las rutas adicionales configuradas. Mantén esta opción desactivada a menos que tu modelo de representaciones vectoriales admita explícitamente representaciones entre modalidades, y establece `memory.search.fallback` en "none" mientras esté activada. Los archivos coincidentes se suben al proveedor remoto de representaciones vectoriales configurado durante la indexación.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Activar la búsqueda multimodal en memoria`},help:{"v1-1dk5d7o-7e":`Activa la indexación de imágenes y audio en memoria desde extraPaths. Actualmente requiere Gemini embedding-2, mantiene las rutas raíz de memoria predeterminadas limitadas a Markdown, desactiva los proveedores alternativos de búsqueda en memoria y carga el contenido binario correspondiente en el proveedor remoto de embeddings configurado.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Máximo de bytes por archivo para la búsqueda multimodal en memoria`},help:{"v1-1mmdrvk-5d":`Establece el máximo de bytes permitidos por archivo multimodal; los archivos que lo superen se omiten durante la indexación de memoria. Úsalo para limitar el costo de carga y la latencia de indexación, o auméntalo para clips de audio cortos de alta calidad.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Modalidades de la búsqueda multimodal en memoria`},help:{"v1-alp4vh-4l":`Selecciona qué tipos de archivos multimodales se indexan desde extraPaths: "image", "audio" o "all". Limita esta selección para evitar indexar involuntariamente grandes colecciones de archivos binarios.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Dimensionalidad de salida de la búsqueda en memoria`},help:{"v1-1f7zu53-93":`Permite personalizar el tamaño del vector de salida para los embeddings de memoria según el proveedor. Los modelos Gemini admiten entre 128 y 3072 dimensiones y recomiendan 768, 1536 o 3072; las familias de Bedrock, como Titan V2, Cohere V4 y Nova, ofrecen sus propios tamaños permitidos. Al cambiarlo, será necesaria una reindexación completa, ya que las dimensiones de los vectores almacenados deben mantenerse coherentes.`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Proveedor de búsqueda en memoria`},help:{"v1-5evseb-71":`Selecciona el backend de embeddings utilizado para crear y consultar vectores de memoria. El valor predeterminado es "openai"; establece "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" o "local" si quieres usar otro backend.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Máximo de resultados de búsqueda en memoria`},help:{"v1-13ekath-4x":`Número máximo de coincidencias de memoria devueltas por la búsqueda antes de la reclasificación posterior y su inserción en el prompt. Auméntalo para recuperar más información o redúcelo para obtener prompts más concisos y respuestas más rápidas.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Puntuación mínima de búsqueda en memoria`},help:{"v1-1ww231l-4v":`Umbral mínimo de relevancia para incluir resultados de memoria en la salida final de recuperación. Auméntalo para reducir las coincidencias débiles o irrelevantes, o redúcelo si necesitas una recuperación más permisiva.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Tipo de entrada de consulta de búsqueda en memoria`},help:{"v1-831yrv-4q":"Valor opcional de `input_type`, específico del proveedor, para los embeddings de memoria al realizar consultas. Úsalo con endpoints de embeddings asimétricos compatibles con OpenAI que requieran una etiqueta de consulta."}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Recordar entre conversaciones`},help:{"v1-k1itm8-7y":`Usa contexto relevante de otras conversaciones privadas de este agente mediante la recuperación protegida de transcripciones. Solo se activa de forma predeterminada cuando session.dmScope global no está definido o es "main" y ninguna vinculación anula el ámbito de los mensajes directos; cualquier aislamiento de mensajes directos configurado lo desactiva de forma predeterminada. Un valor explícito true o false siempre tiene prioridad.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`Clave de API de embeddings remotos`},help:{"v1-nfuuu-62":`Proporciona una clave de API dedicada para las llamadas remotas de generación de representaciones vectoriales utilizadas en la indexación de memoria y en las consultas. Usa esta opción cuando las representaciones vectoriales de memoria deban usar credenciales distintas de las predeterminadas globales o de las variables de entorno.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`URL base de representaciones vectoriales remotas`},help:{"v1-1ugvqgt-5p":`Sustituye el punto de conexión de la API de representaciones vectoriales, por ejemplo, por un proxy compatible con OpenAI o una URL base personalizada de Gemini. Usa esta opción solo al enrutar las solicitudes a través de tu propia pasarela o de un punto de conexión del proveedor; de lo contrario, conserva los valores predeterminados del proveedor.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Generación remota de representaciones vectoriales por lotes habilitada`},help:{"v1-1fehqi-5x":`Habilita las API por lotes del proveedor para los trabajos de generación de representaciones vectoriales cuando sean compatibles (OpenAI/Gemini), lo que mejora el rendimiento en las ejecuciones de indexación más grandes. Mantén esta opción habilitada, salvo que estés depurando fallos en el procesamiento por lotes del proveedor o ejecutando cargas de trabajo muy pequeñas.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`Encabezados de representaciones vectoriales remotas`},help:{"v1-1uic0kd-5i":`Añade encabezados HTTP personalizados a las solicitudes remotas de representaciones vectoriales, combinándolos con los predeterminados del proveedor. Usa esta opción para los encabezados de autenticación del proxy y de enrutamiento por inquilino, y limita los valores al mínimo para evitar la filtración de metadatos confidenciales.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Fuentes de búsqueda en memoria`},help:{"v1-btxtzg-57":`Selecciona qué fuentes se indexan: "memory" lee MEMORY.md y los archivos de memoria, y "sessions" incluye el historial de transcripciones. Mantén ["memory"] a menos que necesites recuperar información de transcripciones de chats anteriores.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Índice vectorial de búsqueda en memoria`},help:{"v1-fbybkj-37":`Controla el índice semántico de sqlite-vec. Mantén esta configuración avanzada cuando las políticas vectoriales de la raíz y de cada agente difieran.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Ruta de la extensión vectorial de búsqueda en memoria`},help:{"v1-1hysv5q-58":"Sustituye la ruta detectada automáticamente de la biblioteca de extensión sqlite-vec (`.dylib`, `.so` o `.dll`). Úsala cuando tu entorno de ejecución no pueda encontrar sqlite-vec automáticamente o cuando fijes una compilación de funcionamiento comprobado."}},messages:{label:{"v1-1wwzqad-8":`Mensajes`},help:{"v1-i5k0iw-5k":`Infraestructura de mensajes y valores predeterminados compartidos entre agentes. Las secciones del nivel raíz definen la infraestructura y los valores predeterminados compartidos entre agentes; agents.defaults define el comportamiento del bucle del agente; las entradas de cada agente pueden sobrescribir cualquiera de ellos cuando se admita.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Emoji de reacción de confirmación`},help:{"v1-1iip0zs-1x":`Reacción con emoji utilizada para confirmar la recepción de mensajes entrantes (si se deja vacío, se desactiva).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Ámbito de las reacciones de confirmación`},help:{"v1-1jvdg5n-7s":`Cuándo enviar reacciones de confirmación ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" confirma los mensajes de grupo que mencionan al agente, independientemente de si el grupo requiere menciones; "group-all" confirma todos los mensajes de grupo. "off"/"none" desactiva por completo las reacciones de confirmación.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Reglas del chat de grupo`},help:{"v1-chqsvh-4l":`Controles de gestión de mensajes de grupo, incluidos los activadores por mención y el tamaño de la ventana del historial. Mantén los patrones de mención específicos para que los canales de grupo no activen al agente con cada mensaje.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Límite del historial de grupo`},help:{"v1-1mkbpw-9k":`Número máximo de mensajes anteriores del grupo que se cargan como contexto por turno en las sesiones de grupo. Usa valores más altos para una mayor continuidad, o más bajos para obtener respuestas más rápidas y económicas. El historial automático del prompt está limitado a 200 mensajes. El valor entero máximo de JSON selecciona la ventana predeterminada del canal (50 para el historial de grupo compartido), no una ventana ilimitada.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Patrones de menciones en grupos`},help:{"v1-i7h7qc-6f":`Patrones seguros de expresiones regulares que no distinguen entre mayúsculas y minúsculas y que se usan para detectar menciones explícitas o frases de activación en chats de grupo. Usa patrones precisos para reducir los falsos positivos en canales con mucho tráfico; se ignoran los patrones no válidos o inseguros con repeticiones anidadas.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Mensajes entrantes sin mención en grupos`},help:{"v1-17wef8h-5f":`Controla cómo se envían para su procesamiento los mensajes sin mención de grupos con escucha permanente. "user_request" los trata como solicitudes del usuario; "room_event" los envía como contexto silencioso en el que la salida visible requiere la herramienta de mensajes.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Respuestas visibles en grupos`},help:{"v1-qa4z1s-aa":`Anula el comportamiento de las respuestas redactadas por el modelo en la conversación de origen para grupos y canales. El valor predeterminado es "automatic" cuando no se ha establecido una política global de respuestas visibles. "message_tool" requiere message(action=send) para la salida normal del asistente y el contenido multimedia genérico de las herramientas; la salida en tiempo de ejecución controlada explícitamente por el host sigue pudiendo entregarse, salvo en el caso de eventos ambientales de la sala. "automatic" publica las respuestas normales como antes.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Agrupación temporal de mensajes entrantes`},help:{"v1-ebyu5x-4a":`Ajustes directos de agrupación temporal de mensajes entrantes que se aplican antes de iniciar el procesamiento de la cola o del turno. Configura esta opción para ráfagas rápidas de mensajes del mismo remitente específicas de cada proveedor.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Agrupación temporal de mensajes entrantes por canal (ms)`},help:{"v1-wbz54j-4g":`Ajustes por canal del tiempo de espera para agrupar mensajes entrantes, en milisegundos, indexados por id de proveedor. Úsalos cuando algunos proveedores envíen fragmentos de mensajes con mayor frecuencia que otros.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Tiempo de espera para agrupar mensajes entrantes (ms)`},help:{"v1-1616yo2-7w":`Intervalo de inactividad (ms) para agrupar mensajes entrantes enviados rápidamente por el mismo remitente. Telegram usa 300 ms de forma predeterminada cuando no se ha establecido un valor personalizado global ni por canal; los demás canales usan 0. El valor cero desactiva la agrupación habitual de mensajes consecutivos, pero Telegram sigue uniendo los fragmentos de mensajes largos cercanos al límite.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Cola de mensajes entrantes`},help:{"v1-hm2o31-48":`Estrategia de cola para los mensajes entrantes que llegan mientras hay una ejecución de sesión activa. Úsala para ajustar la redirección, los seguimientos diferidos, la agrupación o la interrupción.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Modo de cola por canal`},help:{"v1-4rf8z8-54":`Ajustes del modo de cola por canal, indexados por id de proveedor (por ejemplo, telegram, discord, slack). Úsalos cuando el patrón de tráfico de un canal requiera un comportamiento distinto al predeterminado global.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Capacidad de la cola`},help:{"v1-16ql8c7-4j":`Número máximo de elementos entrantes que se conservan en la cola antes de aplicar la política de descarte. El valor predeterminado es 20; mantén límites acotados en los canales con mucho tráfico para que el uso de memoria siga siendo predecible.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Tiempo de espera alternativo para agrupar mensajes en cola por canal (ms)`},help:{"v1-4tpyt7-4e":`Ajustes por canal del tiempo de espera para agrupar mensajes en cola, indexados por id de proveedor. Úsalos para ajustar de forma independiente la gestión de ráfagas en interfaces de chat con distintos ritmos.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Estrategia de descarte de la cola`},help:{"v1-ydb2rw-6m":`Estrategia de descarte cuando se supera el límite de la cola. "summarize" descarta las entradas más antiguas, pero conserva resúmenes compactos; "old" descarta las más antiguas sin resúmenes; "new" rechaza el elemento más reciente. Usa "summarize" para chats prolongados donde el contexto sea importante.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Modo de cola`},help:{"v1-19k7gy1-67":`Modo de cola para ejecuciones activas. Usa "steer" para introducir instrucciones en la ejecución activa, "followup" para ejecutarlas más tarde, "collect" para agrupar mensajes compatibles y procesarlos más tarde, o "interrupt" para cancelar la ejecución activa antes de iniciar la instrucción más reciente.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Prefijo de respuesta saliente`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Modo predeterminado del pie de uso`},help:{"v1-l3shsx-dv":`Modo predeterminado del pie de uso por respuesta ("off"|"tokens"|"full") que se aplica inicialmente a las sesiones que no hayan elegido uno mediante /usage. También acepta "on" como alias heredado de "tokens". Acepta un modo simple o un mapa por canal con "default" como valor de respaldo. Precedencia: valor de la sesión -> entrada del canal -> default -> off; una elección explícita mediante /usage (incluido off) se guarda y prevalece sobre el valor predeterminado. Usa /usage reset (alias: inherit, clear, default) para eliminar la configuración específica de una sesión y volver a heredar este valor predeterminado configurado.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Reacciones de estado`},help:{"v1-193764l-3s":`Reacciones de estado del ciclo de vida que actualizan el emoji del mensaje que inició la ejecución a medida que el agente avanza (en cola → pensando → herramienta → completado/error).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Activar reacciones de estado`},help:{"v1-1qnmmnc-7x":`Activa las reacciones de estado del ciclo de vida en los canales compatibles. Discord considera que esta opción está activada si no se establece ningún valor y las reacciones de confirmación están activas; Slack, Signal, Telegram y WhatsApp requieren que sea true para usar las reacciones del ciclo de vida. Slack usa de forma predeterminada el estado nativo del hilo del asistente para indicar el progreso.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Plantilla del pie de uso`},help:{"v1-1xibc23-47":`Plantilla personalizada del pie de /usage full, como objeto en línea o ruta a un archivo JSON. Si la plantilla no es válida o no está disponible, se usa la línea de uso integrada.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Respuestas visibles`},help:{"v1-7yfwc2-8t":`Controla las respuestas de origen redactadas por el modelo en conversaciones directas, grupales y de canales. "message_tool" requiere message(action=send) para la salida normal del asistente y los archivos multimedia genéricos de las herramientas; la salida en tiempo de ejecución que sea explícitamente responsabilidad del anfitrión se puede seguir entregando, salvo los eventos ambientales de la sala. "automatic" publica las respuestas normales como antes.`}},meta:{label:{"v1-1xpfxac-m":`Metadatos de compatibilidad`},help:{"v1-1owqhgn-2w":`Metadatos de compatibilidad legibles por versiones anteriores, conservados para que los binarios antiguos puedan rechazar conversiones no seguras de la configuración a versiones anteriores.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Versión de la última modificación de la configuración`},help:{"v1-qykpv1-1i":`Versión de OpenClaw que escribió esta configuración por última vez.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Marcadores de migración de la configuración`},help:{"v1-burt8q-1q":`Marcadores de compatibilidad acotados para las migraciones de configuración completadas.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Migración de la lista de permitidos de la política de modelos`},help:{"v1-5psop1-1z":`Registra que las restricciones heredadas del mapa de modelos se conservaron o evaluaron.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Migración de separación del modelo auxiliar`},help:{"v1-vzdfqx-2t":`Registra que los modelos principales implícitos heredados se conservaron antes de separar la selección del modelo auxiliar.`}},models:{label:{"v1-hzmwb-6":`Modelos`},help:{"v1-1h1niol-5q":`Raíz del catálogo de modelos para las definiciones de proveedores, el comportamiento de combinación o sustitución y la integración opcional de detección de Bedrock. Mantén las definiciones de proveedores explícitas y validadas antes de depender de las rutas de conmutación por error en producción.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Actualización del catálogo de modelos`},help:{"v1-1hess4t-40":`Controla las actualizaciones en segundo plano del catálogo de modelos incluido. Las entradas remotas pueden actualizar los metadatos de los modelos, pero no pueden cambiar los endpoints ni los encabezados de los proveedores.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Actualización del catálogo de modelos habilitada`},help:{"v1-1fogpjj-3j":`Obtiene actualizaciones del catálogo de modelos alojado en segundo plano (valor predeterminado: true). Establece el valor en false para desactivar todo el tráfico remoto del catálogo de modelos.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`URL de actualización del catálogo de modelos`},help:{"v1-e02ai2-44":`Sustituye la URL del catálogo de modelos alojado por la de un servidor espejo HTTPS autoalojado (se permite HTTP en localhost para pruebas). Los cambios se aplican después de reiniciar Gateway.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Modo del catálogo de modelos`},help:{"v1-1ofrnsp-es":`Controla el comportamiento del catálogo de proveedores: "merge" conserva los proveedores integrados y superpone tus proveedores personalizados, mientras que "replace" utiliza solo los proveedores que hayas configurado. En "merge", los ID de proveedor coincidentes conservan los valores baseUrl no vacíos del archivo models.json del agente, mientras que los valores apiKey se conservan solo cuando el proveedor no está gestionado mediante SecretRef en el contexto actual de configuración/perfil de autenticación; los proveedores gestionados mediante SecretRef actualizan apiKey a partir de los marcadores de origen actuales, y los valores contextWindow/maxTokens de los modelos coincidentes utilizan el valor más alto entre las entradas explícitas e implícitas.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Proveedores de modelos`},help:{"v1-1y5jg0v-8p":`Mapa de proveedores indexado por ID de proveedor que contiene ajustes de conexión y autenticación y definiciones concretas de modelos. Los proveedores integrados se pueden ajustar mediante sobreescrituras a nivel de proveedor; los proveedores personalizados deben incluir baseUrl y models. Usa claves de proveedor estables para que las referencias de los agentes y las herramientas sigan siendo portables entre entornos.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Entorno de ejecución del proveedor de modelos`},help:{"v1-1luy4fb-5o":`Política opcional de bajo nivel del entorno de ejecución de agentes para este proveedor. Usa una política de entorno de ejecución por proveedor o modelo en lugar de fijar un entorno de ejecución para todo el agente; si se omite o se usa el valor predeterminado, OpenClaw elige el entorno de ejecución para el proveedor seleccionado.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`ID del entorno de ejecución del proveedor de modelos`},help:{"v1-1gusd9s-69":`ID del entorno de ejecución de agentes del proveedor: "openclaw", "auto", un ID de arnés de plugin registrado, como "codex", o un alias de backend de CLI compatible, como "claude-cli". OpenAI en el endpoint oficial usa el arnés de Codex de forma predeterminada si se omite.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`Adaptador de API del proveedor de modelos`},help:{"v1-16c28rb-57":`Selección del adaptador de API del proveedor que controla la gestión de compatibilidad de solicitudes y respuestas en las llamadas a modelos. Usa el adaptador que coincida con el protocolo de tu proveedor de origen para evitar incompatibilidades de funciones.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`Clave de API del proveedor de modelos`},help:{"v1-1p84k96-54":`Credencial del proveedor utilizada para la autenticación mediante clave de API cuando el proveedor requiere autenticación directa con clave. Usa la sustitución mediante secretos o variables de entorno y evita guardar claves reales en archivos de configuración incluidos en el control de versiones.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Modo de autenticación del proveedor de modelos`},help:{"v1-1l1lwxr-5p":`Selecciona el tipo de autenticación del proveedor: "api-key" para autenticación con clave de API, "token" para autenticación con token de portador, "oauth" para credenciales de OAuth y "aws-sdk" para la resolución de credenciales de AWS. Ajusta esta opción a los requisitos de tu proveedor.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Encabezado Authorization del proveedor de modelos`},help:{"v1-1gn3lt3-59":`Cuando es true, las credenciales se envían mediante el encabezado HTTP Authorization, incluso si es posible usar otro método de autenticación. Usa esta opción solo cuando tu proveedor o proxy requiera explícitamente el reenvío de Authorization.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`URL base del proveedor de modelos`},help:{"v1-1ku88v8-53":`URL base del punto de conexión del proveedor que atiende las solicitudes de modelos de esa entrada de proveedor. Usa puntos de conexión HTTPS y mantén las URL específicas de cada entorno mediante plantillas de configuración cuando sea necesario.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Encabezados del proveedor de modelos`},help:{"v1-chg59u-4x":`Encabezados HTTP estáticos que se incorporan a las solicitudes al proveedor para el enrutamiento por inquilino, la autenticación del proxy o los requisitos de una pasarela personalizada. Usa esta opción con moderación y guarda los valores confidenciales de los encabezados como secretos.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Inyección de num_ctx del proveedor de modelos (compatibilidad con OpenAI)`},help:{"v1-53rmcr-6n":"Controla si OpenClaw inyecta `options.num_ctx` para los proveedores de Ollama configurados con el adaptador compatible con OpenAI (`openai-completions`). El valor predeterminado es true. Establece false solo si tu proxy o servidor de destino rechaza campos desconocidos de `options` en el cuerpo de la solicitud."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Servicio local del proveedor de modelos`},help:{"v1-19zkcow-4y":`Proceso opcional de servidor de modelos local bajo demanda para este proveedor. OpenClaw comprueba healthUrl, ejecuta el comando cuando es necesario, espera a que el servidor esté listo y luego envía la solicitud al modelo.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Argumentos del servicio local del proveedor de modelos`},help:{"v1-t12wib-27":`Lista de argumentos que se pasan al comando del servidor de modelos local sin expansión del intérprete de comandos.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Comando del servicio local del proveedor de modelos`},help:{"v1-1x6hz64-4j":`Ruta absoluta del ejecutable del proceso del servidor de modelos local. Mantenga esta ruta explícita para que el inicio del proveedor sea determinista y no dependa de la búsqueda en PATH del intérprete de comandos.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Directorio de trabajo del servicio local del proveedor de modelos`},help:{"v1-fi3xlx-1h":`Directorio de trabajo del proceso del servidor de modelos local.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Entorno del servicio local del proveedor de modelos`},help:{"v1-1lwb9k1-3k":`Variables de entorno adicionales para el proceso del servidor de modelos local. Los valores que parecen secretos se ocultan en las instantáneas de configuración.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL de comprobación de estado del servicio local del proveedor de modelos`},help:{"v1-jv7aw-35":`URL que se consulta antes de las solicitudes al modelo para comprobar si el servidor está listo. Si se omite, OpenClaw usa baseUrl del proveedor con /models añadido al final.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Parada por inactividad del servicio local del proveedor de modelos`},help:{"v1-1efg054-3z":`Milisegundos durante los que se mantiene activo un servidor de modelos local iniciado por OpenClaw tras finalizar la última solicitud. Establece 0 para mantenerlo activo hasta que OpenClaw se cierre.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Tiempo de espera para que el servicio local del proveedor de modelos esté listo`},help:{"v1-4gp0f0-2r":`Tiempo máximo en milisegundos que se espera a que la comprobación de disponibilidad del servidor de modelos local confirme que está listo después de iniciar el proceso.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Máximo de tokens del proveedor de modelos`},help:{"v1-fnj50y-38":`Límite máximo predeterminado de tokens de salida que se aplica a los modelos de este proveedor cuando la entrada de un modelo no establece maxTokens.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Lista de modelos del proveedor de modelos`},help:{"v1-1vbm0gt-63":`Lista de modelos declarados para un proveedor, incluidos identificadores, metadatos, parámetros específicos del proveedor e indicaciones opcionales de compatibilidad y coste. Mantén los ID exactamente como aparecen en el catálogo del proveedor para que la selección y el uso de alternativas funcionen correctamente.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Entorno de ejecución del modelo`},help:{"v1-1k70g2n-3g":`Política opcional de bajo nivel del entorno de ejecución del agente para este modelo específico. La política del entorno de ejecución del modelo prevalece sobre la del proveedor.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`ID del entorno de ejecución del modelo`},help:{"v1-1llzv33-42":`ID del entorno de ejecución del agente del modelo: "openclaw", "auto", un ID registrado de infraestructura de ejecución de un complemento, como "codex", o un alias de backend de CLI compatible, como "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Entrada multimedia del modelo`},help:{"v1-wxtj8e-2x":`Metadatos opcionales sobre las capacidades multimedia del modelo que las herramientas usan para elegir valores predeterminados conservadores de compresión de imágenes.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Entrada de imágenes del modelo`},help:{"v1-1nviirq-3c":`Límites opcionales de entrada de imágenes para este modelo, como la longitud máxima del lado, el número máximo de píxeles y la longitud de lado preferida para la compresión.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Máximo de bytes por imagen del modelo`},help:{"v1-c2469j-23":`Tamaño máximo de los datos de imagen codificados que el proveedor acepta para este modelo.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Máximo de píxeles por imagen del modelo`},help:{"v1-9d6yqp-1u":`Número máximo de píxeles por imagen que el proveedor acepta para este modelo.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Longitud máxima del lado de imagen del modelo`},help:{"v1-1gbci08-1y":`Anchura o altura máxima de imagen que el proveedor acepta para este modelo.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Longitud de lado preferida de imagen del modelo`},help:{"v1-1u1mpcg-2x":`Longitud de lado preferida al redimensionar imágenes para una compresión equilibrada. Deja este campo sin configurar para usar el valor predeterminado conservador de OpenClaw.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Modo de tokens de imagen del modelo`},help:{"v1-1oy6z7v-1z":`Método de contabilización de tokens de imagen del proveedor: "tile", "detail" o "provider".`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Parámetros de ejecución del proveedor de modelos`},help:{"v1-464sgu-4t":`Parámetros de ejecución específicos del proveedor que interpretan sus complementos. Utilice las claves documentadas por el proveedor y dé prioridad a su documentación explícita frente a suposiciones compartidas improvisadas.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Región del proveedor de modelos`},help:{"v1-yq7rxk-5h":`Región opcional de despliegue/API del proveedor, interpretada por los proveedores que ofrecen endpoints regionales. Consulte los valores admitidos en la documentación del proveedor; las anulaciones de baseUrl suelen tener prioridad cuando se configuran ambos.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Anulaciones de solicitudes al proveedor de modelos`},help:{"v1-1lkxryk-87":`Anulaciones opcionales para las solicitudes al proveedor de modelos, incluidos encabezados adicionales, anulaciones de autenticación, enrutamiento por proxy, ajustes del cliente TLS y la opción allowPrivateNetwork para endpoints autoalojados de confianza. Utilícelas solo cuando el servicio de destino o la ruta de red empresarial requieran personalizar el transporte.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Permitir redes privadas en las solicitudes al proveedor de modelos`},help:{"v1-1nbtcjk-fo":`Cuando es true, permite que las solicitudes HTTP al proveedor de modelos accedan a rangos privados, CGNAT o similares a través de la protección de solicitudes HTTP del proveedor (fetchWithSsrFGuard). Las URL base de proveedores personalizados o locales ya confían en el origen exacto configurado, excepto en los orígenes de metadatos, de enlace local y NAT64 de uso local (64:ff9b:1::/48); establece este valor en false para desactivar esa confianza. OpenAI Responses WebSocket reutiliza request para los encabezados y TLS, pero no utiliza esa ruta de solicitudes con protección SSRF. Usa true solo para endpoints autoalojados bajo el control del operador que deban acceder a orígenes privados fuera del origen configurado en baseUrl.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Anulación de la autenticación de solicitudes al proveedor de modelos`},help:{"v1-ucdgnf-1w":`Anula el comportamiento de autenticación de las solicitudes para este proveedor.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Nombre del encabezado de autenticación de solicitudes al proveedor de modelos`},help:{"v1-1881nqr-1i":`Nombre del encabezado de autenticación personalizado que se usa cuando el modo de autenticación es header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Modo de autenticación de solicitudes al proveedor de modelos`},help:{"v1-1lhv8hs-24":`Modo de anulación de la autenticación: "provider-default", "authorization-bearer" o "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Prefijo del encabezado de autenticación de solicitudes al proveedor de modelos`},help:{"v1-1rbm9lz-21":`Prefijo opcional que se antepone a request.auth.value cuando el modo de autenticación es header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Token Bearer de solicitudes al proveedor de modelos`},help:{"v1-6rcasw-1l":`Token Bearer utilizado cuando el modo de autenticación es authorization-bearer.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Valor del encabezado de autenticación de las solicitudes al proveedor de modelos`},help:{"v1-1v69ej-1j":`Valor del encabezado de autenticación personalizado utilizado cuando el modo de autenticación es header.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Encabezados de las solicitudes al proveedor de modelos`},help:{"v1-zj3orj-2i":`Encabezados adicionales que se incorporan a las solicitudes al proveedor tras aplicar la atribución predeterminada y resolver la autenticación.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Proxy de las solicitudes al proveedor de modelos`},help:{"v1-md5uj8-4j":`Configuración alternativa opcional del proxy para las solicitudes al proveedor de modelos. Usa "env-proxy" para respetar la configuración del proxy del entorno o "explicit-proxy" para enrutar las solicitudes a través de una URL de proxy específica.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Modo de proxy de las solicitudes al proveedor de modelos`},help:{"v1-1dx0ozg-29":`Modo de configuración alternativa del proxy para las solicitudes al proveedor de modelos: "env-proxy" o "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`TLS del proxy de las solicitudes al proveedor de modelos`},help:{"v1-rdx62w-1v":`Configuración TLS opcional utilizada al conectarse al proxy configurado.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`CA de TLS del proxy de las solicitudes al proveedor de modelos`},help:{"v1-11pg2fd-1s":`Conjunto de certificados de CA personalizado utilizado para verificar la cadena de certificados TLS del proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`Certificado TLS del proxy de las solicitudes al proveedor de modelos`},help:{"v1-x8nk2q-22":`Certificado TLS del cliente que se presenta al proxy cuando se requiere TLS mutuo.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Omitir la verificación TLS del proxy de solicitudes del proveedor de modelos`},help:{"v1-12vjdm9-2j":`Omite la verificación del certificado TLS del proxy. Usar solo en entornos de desarrollo controlados.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`Clave TLS del proxy de solicitudes del proveedor de modelos`},help:{"v1-1skyr56-1w":`Clave privada asociada a request.proxy.tls.cert para TLS mutuo con el proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`Frase de contraseña TLS del proxy de solicitudes del proveedor de modelos`},help:{"v1-wjvoxd-1m":`Frase de contraseña opcional utilizada para descifrar request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`Nombre de servidor TLS del proxy de solicitudes del proveedor de modelos`},help:{"v1-b4oabu-22":`Valor opcional que sustituye el SNI/nombre del servidor al establecer una conexión TLS con el proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`URL del proxy de solicitudes del proveedor de modelos`},help:{"v1-kvbgou-48":`URL de proxy explícita utilizada cuando request.proxy.mode es explicit-proxy. Las credenciales incluidas en la URL se consideran confidenciales y se ocultan en las instantáneas.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS de solicitudes del proveedor de modelos`},help:{"v1-16u7v7h-2b":`Configuración TLS opcional que se usa al conectarse directamente al endpoint del modelo del proveedor.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`CA TLS de las solicitudes al proveedor de modelos`},help:{"v1-ny8y3e-1v":`Conjunto de certificados de CA personalizado que se usa para verificar la cadena de certificados TLS del proveedor.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`Certificado TLS de las solicitudes al proveedor de modelos`},help:{"v1-1lltmhw-2e":`Certificado TLS de cliente que se presenta al endpoint del proveedor cuando se requiere TLS mutuo.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Omitir la verificación TLS de las solicitudes al proveedor de modelos`},help:{"v1-1006cuy-2m":`Omite la verificación del certificado TLS del proveedor. Usar solo en entornos de desarrollo controlados.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`Clave TLS de las solicitudes al proveedor de modelos`},help:{"v1-w2agir-1t":`Clave privada asociada a request.tls.cert para TLS mutuo con el proveedor.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`Frase de contraseña TLS de las solicitudes al proveedor de modelos`},help:{"v1-10ds42f-1g":`Frase de contraseña opcional que se usa para descifrar request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`Nombre del servidor TLS de las solicitudes al proveedor de modelos`},help:{"v1-18yt7x9-1y":`Valor opcional que sustituye el SNI/nombre del servidor al establecer la conexión TLS con el proveedor.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Tiempo de espera de las solicitudes al proveedor de modelos`},help:{"v1-t3yn8l-ih":`Tiempo de espera opcional en segundos para las solicitudes de modelos de cada proveedor. Los ajustes de solicitud a nivel de proveedor afectan a las filas de modelos explícitos de ese proveedor; no crean modelos implícitos. Para los proveedores personalizados, configúralo junto con baseUrl y models del proveedor. Se aplica a las solicitudes HTTP del proveedor, incluida la gestión de la conexión, los encabezados, el cuerpo y la cancelación de la solicitud completa, y también eleva el límite del supervisor de inactividad/transmisión del LLM para este proveedor por encima del valor predeterminado implícito de ~120 s. Úsalo para servidores de modelos locales o autoalojados lentos, o para proveedores en la nube que almacenan en búfer los tokens de razonamiento sin transmitirlos (Gemini preview, Claude/Opus con grandes cargas de datos de herramientas), en lugar de cambiar los tiempos de espera globales del agente.`}},nodeHost:{label:{"v1-nb8lk1-9":`Host del nodo`},help:{"v1-8recuz-4z":`Controles del host del nodo para las funciones que este nodo de gateway expone a otros nodos o clientes. Mantén los valores predeterminados a menos que quieras ofrecer capacidades locales mediante un proxy en tu red de nodos.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Ejecuciones de agentes del nodo`},help:{"v1-4uz5ur-2k":`Habilita los turnos de agentes nativos sujetos a aprobación en este host de nodo sin interfaz gráfica. Deshabilitado de forma predeterminada.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Ejecuciones del agente Claude del nodo`},help:{"v1-g8az5y-2l":`Controla si este host de nodo sin interfaz gráfica puede anunciar al gateway los turnos del agente Claude CLI.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Ejecuciones del agente Claude del nodo habilitadas`},help:{"v1-1ke804l-44":`Anuncia la continuación de sesiones de Claude en nodos emparejados cuando el binario local claude esté disponible (valor predeterminado: false). Las ejecuciones siguen requiriendo la aprobación de ejecución del nodo.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Actualizaciones automáticas de nodos`},help:{"v1-16xjk4e-5n":`Controla las actualizaciones automáticas del entorno de ejecución independiente para hosts de nodos empaquetados sin interfaz gráfica. Busca actualizaciones cada hora y espera a que finalicen todas las tareas del nodo antes de reiniciar; los reinicios automáticos se realizan con al menos 12 horas de diferencia.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Actualizaciones automáticas de nodos habilitadas`},help:{"v1-1sa0yeg-7w":`Habilita las actualizaciones automáticas de versiones estables o beta para nodos empaquetados sin interfaz gráfica que se ejecutan de forma continua (valor predeterminado: true). Establece el valor en false para desactivarlas. También se deshabilitan con update.checkOnStart=false u OPENCLAW_NO_AUTO_UPDATE=1; no se aplican automáticamente en copias de trabajo del código fuente, aplicaciones nativas, procesos de trabajo privados, dev ni extended-stable.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Proxy del navegador del nodo`},help:{"v1-2xrew7-4f":`Agrupa los ajustes del proxy del navegador para exponer el control del navegador local mediante el enrutamiento de nodos. Actívalo solo cuando los flujos de trabajo de nodos remotos necesiten tus perfiles de navegador locales.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Perfiles permitidos en el proxy del navegador del nodo`},help:{"v1-1ew5dkm-8b":`Lista opcional de nombres de perfiles de navegador permitidos que se exponen mediante el enrutamiento del proxy del nodo. Déjala vacía para mantener el acceso completo predeterminado a los perfiles, incluidas las rutas de creación y eliminación de perfiles. Si se configura, OpenClaw aplica el principio de mínimo privilegio al acceso a los perfiles y bloquea la creación y eliminación de perfiles persistentes a través del proxy.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Proxy del navegador del nodo activado`},help:{"v1-pa04pd-5b":`Expone el servidor de control del navegador local mediante el enrutamiento del proxy del nodo para que los clientes remotos puedan usar las funciones del navegador de este host. Mantenlo desactivado a menos que la automatización remota dependa explícitamente de él.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`MCP del host del nodo`},help:{"v1-1mdhrwl-48":`Usa como herramientas del agente los servidores MCP que el host del nodo sin interfaz gráfica inicia y publica en su Gateway vinculado. Reinicia el host del nodo después de cambiar esta sección.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Servidores MCP del host del nodo`},help:{"v1-19m002f-3x":`Definiciones con nombre de servidores MCP locales de este nodo. Usa la misma estructura de servidor que mcp.servers; el host del nodo no admite servidores OAuth.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Skills del host del nodo`},help:{"v1-v8txza-41":`Usa esta sección para publicar las habilidades instaladas en ~/.openclaw/skills desde el host del nodo sin interfaz gráfica. Reinicia el host del nodo después de cambiar los archivos de habilidades.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Skills del host del nodo activadas`},help:{"v1-1ggpkqb-36":`Buscar y publicar habilidades alojadas en el nodo tras conectarse (valor predeterminado: true). Establece false para desactivar la publicación de habilidades del nodo.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Ejecuciones de procesos de trabajo del nodo`},help:{"v1-1w83rox-2p":`Activa el alojamiento completo de sesiones de procesos de trabajo de OpenClaw a partir de paquetes gestionados por Gateway. Desactivado de forma predeterminada.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Capacidad de ejecución de procesos de trabajo del nodo`},help:{"v1-10nvk8f-3w":`Número máximo de sesiones simultáneas de procesos de trabajo alojadas en este nodo (valor predeterminado: el número de núcleos de CPU disponibles). Debe ser un número entero entre 1 y 1024.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Imagen de contenedor para la ejecución de procesos de trabajo del nodo`},help:{"v1-1oqx50o-5t":`Imagen opcional de Node 24.16+ o 26.1+ para procesos de trabajo aislados en contenedores (valor predeterminado: "node:24.19.0-slim"). Usa una imagen fijada por digest, de un registro privado o precargada cuando sea necesario; las imágenes que falten se descargan en el primer uso.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Ejecuciones de procesos de trabajo del nodo habilitadas`},help:{"v1-b3t0xp-2t":`Permitir que este nodo vinculado aloje sesiones a partir de los paquetes exactos instalados por su Gateway (valor predeterminado: false).`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Aislamiento de ejecución de procesos de trabajo del nodo`},help:{"v1-19i6swo-58":`Selecciona el límite de aislamiento del proceso para las sesiones de trabajo: "none" ejecuta directamente en el host del nodo (opción predeterminada); "container" requiere un motor compatible con Docker operativo y nunca recurre a la ejecución en el host como alternativa.`}},plugins:{label:{"v1-10renyj-7":`Complementos`},help:{"v1-1qbev2k-5c":`Controles del sistema de complementos para habilitar extensiones, limitar el alcance de carga, configurar entradas y supervisar instalaciones. Mantén una política de complementos explícita y basada en el principio de mínimo privilegio en los entornos de producción.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Lista de plugins permitidos`},help:{"v1-pupwbe-7z":`Lista opcional de IDs de plugins permitidos; si se define, solo podrán cargarse los plugins incluidos. Los canales de chat integrados que estén configurados podrán seguir activando su plugin integrado cuando el canal esté habilitado explícitamente en la configuración. Utilice esta opción para limitar las extensiones a las aprobadas en entornos controlados.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Lista de plugins bloqueados`},help:{"v1-4gyt4z-4i":`Lista opcional de IDs de plugins que se bloquean aunque estén incluidos en listas de permitidos o rutas. Utilice reglas de bloqueo para reversiones de emergencia y bloqueos estrictos de plugins de riesgo.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Habilitar plugins`},help:{"v1-pnygd7-50":`Habilita o deshabilita globalmente la carga de plugins y extensiones durante el inicio y la recarga de la configuración (valor predeterminado: true). Mantenga esta opción habilitada solo cuando su implementación requiera las capacidades de las extensiones.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Entradas de plugins`},help:{"v1-cn74rf-54":`Ajustes por plugin organizados por ID de plugin, que incluyen su habilitación y los datos de configuración específicos para su ejecución. Utilice esta opción para ajustar plugins individuales sin cambiar la política global de carga.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`Clave de API del plugin`},help:{"v1-ctytg2-53":`Campo opcional de clave de API utilizado por los plugins que admiten configurar la clave directamente en los ajustes de su entrada. Utilice la sustitución mediante secretos o variables de entorno y evite guardar credenciales reales en archivos de configuración.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Configuración del plugin`},help:{"v1-1he672p-51":`Datos de configuración definidos por el plugin e interpretados según su propio esquema y sus reglas de validación. Utilice únicamente los campos documentados del plugin para evitar ajustes no válidos o que se ignoren.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Plugin habilitado`},help:{"v1-12soc0h-9a":`Anulación de la habilitación de un plugin para una entrada específica, aplicada sobre la política global de plugins. Con el modo de recarga híbrida predeterminado, los cambios recargan en caliente el entorno de ejecución del plugin para los nuevos turnos del agente sin reiniciar el Gateway, a menos que el plugin requiera un reinicio para esta ruta. Use esta opción para desplegar el plugin gradualmente en distintos entornos.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Variables de entorno del plugin`},help:{"v1-p39pu4-52":`Mapa de variables de entorno por plugin que se inyecta únicamente en el contexto de ejecución de ese plugin. Use esta opción para limitar las credenciales del proveedor a un solo plugin en lugar de compartir el entorno global del proceso.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Política de hooks del plugin`},help:{"v1-1oslnrf-4c":`Controles de política de hooks tipados por plugin para las medidas de seguridad impuestas por el núcleo. Use esta opción para restringir las categorías de hooks de alto impacto sin deshabilitar todo el plugin.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Permitir hooks de acceso a conversaciones`},help:{"v1-xqz31z-7e":"Controla si este plugin puede leer el contenido sin procesar de las conversaciones mediante hooks tipados como `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` y `agent_end`. Los plugins no incluidos de serie deben habilitar esta opción explícitamente."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`Permitir hooks de inyección de prompts`},help:{"v1-7y6cny-32":"Controla si este plugin puede modificar prompts mediante hooks tipados. Establezca el valor en false para bloquear `before_prompt_build`."}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Tiempo de espera de los hooks del plugin (ms)`},help:{"v1-4ra6b7-74":`Tiempo de espera predeterminado en milisegundos para los hooks tipados de este plugin, con un límite de 600000. Si no se configura, cada hook usa el tiempo de espera declarado por el plugin o la política por hook del Gateway; no hay un único valor predeterminado fijo. Los valores por hook en hooks.timeouts tienen prioridad.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Tiempos de espera personalizados de los hooks del plugin`},help:{"v1-yphl9b-5s":`Tiempos de espera personalizados por hook en milisegundos, indexados por el nombre del hook tipado, con un máximo de 600000. Usa ajustes específicos para hooks que se sabe que son lentos, como before_prompt_build o agent_end, en lugar de aumentar el tiempo de espera de todos los hooks.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`Política de LLM del plugin`},help:{"v1-dlca6c-4j":`Controles de api.runtime.llm.complete por plugin para autorizar la selección de modelos y agentes alternativos. Deja esta opción sin configurar, salvo que un plugin deba dirigir explícitamente las llamadas de generación de texto gestionadas por el anfitrión.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Permitir que el plugin seleccione un agente alternativo para el LLM`},help:{"v1-k8c08b-4n":`Permite explícitamente que este plugin solicite api.runtime.llm.complete con un ID de agente distinto del predeterminado. Mantén el valor false, salvo que se confíe en el plugin para acceder a modelos de otros agentes.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Permitir que el plugin seleccione un perfil de autenticación alternativo para el LLM`},help:{"v1-9ityw9-4x":`Permite que este plugin seleccione un perfil de autenticación distinto del predeterminado para generar texto en un entorno de ejecución de agente aislado. Mantén el valor false, salvo que se confíe en el plugin para el enrutamiento explícito y aislado de credenciales.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Modelos de LLM permitidos para la generación de texto del plugin`},help:{"v1-1ul08he-54":`Destinos permitidos para cada generación de texto del LLM del plugin como referencias canónicas "provider/model", incluidos los valores predeterminados resueltos por el host y las sustituciones. Use "*" solo si desea permitir expresamente cualquier modelo.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Modelos permitidos para el LLM del plugin`},help:{"v1-154sk45-47":`Destinos de sustitución permitidos para las llamadas de confianza al LLM del plugin como referencias canónicas "provider/model". Use "*" solo si desea permitir expresamente cualquier sustitución de modelo.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Permitir la sustitución del modelo del LLM del plugin`},help:{"v1-uw4jmc-47":`Permite explícitamente que este plugin solicite sustituciones de modelo en api.runtime.llm.complete. Mantenga el valor false a menos que confíe en el plugin para determinar la selección del modelo.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Política de subagentes del plugin`},help:{"v1-wbf4m1-4d":`Controles de ejecución de subagentes por plugin para la confianza en las sustituciones de modelo y las listas de modelos permitidos. Deje esta opción sin configurar a menos que un plugin deba determinar explícitamente la selección del modelo del subagente.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Modelos permitidos para los subagentes del plugin`},help:{"v1-2pvkow-42":`Destinos de sustitución permitidos para las ejecuciones de confianza de subagentes del plugin como referencias canónicas "provider/model". Use "*" solo si desea permitir expresamente cualquier modelo.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Permitir la sustitución del modelo del subagente del plugin`},help:{"v1-1r5tzm1-4g":`Permite explícitamente que este complemento solicite cambios de proveedor o modelo en las ejecuciones de subagentes en segundo plano. Mantén el valor false a menos que confíes en el complemento para dirigir la selección del modelo.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Cargador de complementos`},help:{"v1-1myjwbi-52":`Grupo de configuración del cargador de complementos para especificar las rutas del sistema de archivos donde se buscan complementos. Define y revisa explícitamente las rutas de carga para evitar cargar accidentalmente extensiones no confiables.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Rutas de carga de complementos`},help:{"v1-o689p1-4z":`Archivos o directorios de complementos adicionales que el cargador examina además de los predeterminados integrados. Usa directorios dedicados a extensiones y evita rutas amplias con contenido ejecutable no relacionado.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Espacios de complementos`},help:{"v1-zx6crl-5f":`Selecciona qué complementos ocupan espacios exclusivos en tiempo de ejecución, como el de memoria, para que solo un complemento proporcione esa capacidad. Asigna explícitamente cada espacio para evitar la superposición de proveedores con comportamientos en conflicto.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`Complemento del motor de contexto`},help:{"v1-4v13iw-2t":`Selecciona por su identificador el complemento del motor de contexto activo para que un único complemento proporcione la orquestación del contexto.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Complemento de memoria`},help:{"v1-80ngcl-23":`Selecciona el complemento de memoria activo por su identificador, o "none" para desactivar los complementos de memoria.`}},presence:{label:{"v1-10fdwo4-8":`Presencia`}},proxy:{label:{"v1-ji57pa-d":`Proxy administrado`},help:{"v1-vui6bx-58":`Enrutamiento mediante un proxy de reenvío administrado por el operador para el tráfico HTTP, HTTPS y WebSocket de OpenClaw en tiempo de ejecución, así como para las rutas de salida directa compatibles. Úsalo cuando el control centralizado del tráfico de salida forme parte del perímetro del despliegue.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Proxy administrado habilitado`},help:{"v1-1456xdw-49":`Anulación explícita del proxy administrado. La presencia de una URL habilita el enrutamiento de forma predeterminada; establece false para ignorar las URL de proxy configuradas o definidas en el entorno sin eliminarlas.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Modo de bucle local del proxy administrado`},help:{"v1-1kaiuh0-3c":`Controla el enrutamiento del plano de control de Gateway a través del bucle local mientras el modo de proxy administrado está activo: "gateway-only", "proxy" o "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`URL del proxy administrado`},help:{"v1-p36b5l-3v":`URL del proxy de reenvío administrado. Usa http:// para un proxy CONNECT sin cifrado o https:// cuando la conexión al propio punto de conexión del proxy deba usar TLS.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS del proxy administrado`},help:{"v1-6i0vu-3q":`Configuración de TLS utilizada al conectarse al punto de conexión del proxy administrado. Esta configuración se aplica al TLS del proxy, no al TLS del destino después de CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`Archivo de CA para TLS del proxy administrado`},help:{"v1-1ntzjia-2p":`Ruta del sistema de archivos a un paquete de CA personalizado utilizado para verificar el certificado de un punto de conexión de proxy administrado HTTPS.`}},secrets:{label:{"v1-1sihgpy-7":`Secretos`},help:{"v1-jgn0o9-2l":`Proveedores de referencias a secretos, comportamiento del almacén compartido y protección opcional del tráfico saliente de subprocesos.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Proxy de salida de secretos`},help:{"v1-1qfgid-4n":`Proxy de bucle local gestionado por Gateway que sustituye los marcadores de secretos del almacén compartido solo al realizar solicitudes salientes. Reinicia Gateway después de modificar esta sección, que se aplica al inicio.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Hosts permitidos del proxy de salida de secretos`},help:{"v1-9ypodl-6t":`Lista opcional de destinos permitidos para solicitudes y túneles CONNECT. Si se define, los destinos deben figurar en esta lista, en una vinculación de host por secreto o en bypassHosts. Una lista vacía permite únicamente los hosts vinculados o excluidos. Reinicia el Gateway después de modificarla.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Hosts excluidos del proxy de salida de secretos`},help:{"v1-1oiiomv-57":`Nombres de host exactos que usan túneles CONNECT ciegos autenticados para clientes con certificados fijados. Los valores centinela permanecen cifrados y provocarán un fallo de autenticación con el proveedor en lugar de exponer texto sin cifrar.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Proxy de salida de secretos habilitado`},help:{"v1-u99b1i-2h":`Habilita la sustitución de secretos en el tráfico de salida de los subprocesos de agentes alojados en el Gateway. Valor predeterminado: false.`}},session:{label:{"v1-8yh9jr-7":`Sesión`},help:{"v1-j86s32-5d":`Controles globales de enrutamiento, restablecimiento, política de entrega y mantenimiento de sesiones para el comportamiento del historial de conversaciones. Mantén los valores predeterminados salvo que necesites restricciones más estrictas de aislamiento, retención o entrega.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Ámbito de sesión de mensajes directos`},help:{"v1-ql362c-5l":`Ámbito de las sesiones de mensajes directos: "main" mantiene la continuidad, mientras que "per-peer", "per-channel-peer" y "per-account-channel-peer" aumentan el aislamiento. Usa modos aislados para bandejas de entrada compartidas o implementaciones con varias cuentas.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Ámbito de sesión de grupo`},help:{"v1-1fdezx2-6i":`Ámbito de las sesiones de grupos y canales: "per-group" mantiene las salas separadas mientras la sesión principal del agente las observa en segundo plano, independientemente de dmScope; "main" integra el contexto de las salas en la sesión principal y no requiere observación. Usa "main" solo para salas de confianza.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Vínculos de identidad de sesión`},help:{"v1-1y5jnsm-5n":`Asocia identidades canónicas con IDs de interlocutores que llevan el prefijo del proveedor para que los usuarios equivalentes se vinculen a un único hilo de mensajes directos (ejemplo: telegram:123456). Úsalo cuando la misma persona aparezca en varios canales o cuentas.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Clave principal de sesión`},help:{"v1-18p638h-3q":`Se acepta, pero se ignora: el sufijo de la sesión principal de cada agente siempre es "main". Omite este campo; el ámbito de sesión global usa "global" en su lugar.`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Mantenimiento de sesiones`},help:{"v1-imr441-66":`Controles de mantenimiento automático del almacén de sesiones para el archivado del panel, la antigüedad para la depuración, los límites de entradas, la retención de archivos de reinicio y la limpieza según el espacio asignado en disco. Empieza en modo warn para observar el impacto y luego cambia a enforce una vez ajustados los umbrales.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Archivar sesiones inactivas del panel después de`},help:{"v1-1frdtub-5n":"Archiva las sesiones inactivas del panel después de este período (por ejemplo, `7d`) para que sigan disponibles sin saturar la lista de sesiones activas. Establece `false` o `0` para desactivar el archivado automático del panel."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`Almacenamiento en frío de transcripciones`},help:{"v1-1kp9s9h-5s":`Mueve las transcripciones inactivas a archivos JSONL comprimidos y conserva los metadatos de las sesiones. Los archivos pasan a formar parte del historial obligatorio y deben incluirse en las copias de seguridad. Los cambios se aplican sin reiniciar Gateway.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Archivar tras estos días de inactividad`},help:{"v1-zay1q3-5b":`Archiva las transcripciones tras este número de días de inactividad (entero positivo, 30 de forma predeterminada). El trabajo activo está protegido; los cambios en el umbral se aplican en el siguiente ciclo del proceso de trabajo sin reiniciar Gateway.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`Archivar automáticamente las transcripciones antiguas`},help:{"v1-6p6vmb-5a":`Habilita el archivado de transcripciones en segundo plano (false de forma predeterminada). Un proceso comprueba cada minuto si hay transcripciones que cumplen los requisitos. Esta política de archivado explícita es independiente de la eliminación y de la limpieza por límite de espacio en disco.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Objetivo de ocupación máxima del disco para sesiones`},help:{"v1-143vh09-7z":`Tamaño objetivo tras la limpieza según el espacio asignado en disco (umbral máximo). El valor predeterminado es el 80% de maxDiskBytes; establécelo explícitamente para controlar mejor la recuperación de espacio en discos con capacidad limitada. Un valor que se evalúe como cero se sustituye por el predeterminado; los valores negativos no son válidos. Para desactivar el límite de espacio, usa maxDiskBytes.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Espacio máximo en disco asignado a sesiones`},help:{"v1-147lxk3-cj":'Presupuesto de espacio físico en disco por agente que abarca el archivo principal y el WAL de SQLite, así como los artefactos contabilizados del directorio de sesiones (por ejemplo, `500mb`). El valor predeterminado es `10gb`; los datos protegidos pueden mantener el uso por encima del objetivo. Cuando se supera, el modo warn informa de la presión sobre el espacio y el modo enforce elimina primero los artefactos antiguos de restablecimiento o eliminación, luego el historial sin referencias y, por último, los archivos creados al alcanzar el límite. Los archivos manuales, de retención por antigüedad, del panel, de recuperación y heredados permanecen protegidos. Establece `false`, `0` o `"0"` para desactivarlo.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Máximo de entradas de sesión`},help:{"v1-1w2egrh-7u":`Limita las entradas de sesión sin archivar (5000 de forma predeterminada). Las conversaciones persistentes que cumplen los requisitos y exceden el límite se archivan con su historial; las entradas de automatización desechables se eliminan. Los archivos existentes no cuentan para el límite. Las entradas activas protegidas siguen contando y pueden mantener el almacén por encima del límite.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Modo de mantenimiento de sesiones`},help:{"v1-bq39hk-6v":`Determina si las políticas de depuración y de límite de espacio en disco solo se notifican ("warn") o se aplican activamente ("enforce"). Mantén "warn" durante el despliegue y cambia a "enforce" tras validar que los umbrales sean seguros. El almacenamiento en frío tiene su propia opción explícita de habilitación.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Conservar sesiones recientes`},help:{"v1-138q5wx-89":"Protege las sesiones interactivas activas durante este período (por ejemplo, `7d`) frente a la eliminación automática del historial por antigüedad, cantidad o presupuesto de disco. Si no se establece o se configura como `false`, se mantiene la política habitual de eliminar primero las más antiguas. Las filas sintéticas de ejecución de modelos, cron, hook, heartbeat, ACP y subagentes siguen siendo aptas para la limpieza con límites."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Depurar sesiones después de`},help:{"v1-1xn50w7-76":"Archiva las conversaciones persistentes que cumplen los requisitos y elimina las entradas de automatización desechables cuya antigüedad supera esta duración (valor predeterminado: `30d`; por ejemplo, `12h`). Las conversaciones archivadas conservan su historial y pueden restaurarse; las conversaciones protegidas o enrutables permanecen activas."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Retención de archivos de restablecimiento de sesiones`},help:{"v1-16amrs1-7r":"Retención basada en la antigüedad para las transcripciones archivadas (`*.reset.<timestamp>` y `*.deleted.<timestamp>`). De forma predeterminada, los archivos se conservan hasta que el límite de espacio en disco obliga a eliminarlos, empezando por los más antiguos; establece una duración (por ejemplo, `30d`) para activar la eliminación según el tiempo transcurrido, o `false` para desactivarla explícitamente."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Notificar a Inicio al crear una sesión`},help:{"v1-c4prn5-8b":`Añade a la cola un aviso del sistema en la sesión de Inicio del agente propietario cuando se crea una sesión (valor predeterminado: true). Los avisos incluyen el título y los metadatos del creador disponibles y se leen en el siguiente turno de Inicio o pulso periódico. Establece false para desactivar esta opción; se excluyen los borradores, las sesiones de incógnito, las sesiones internas y las ejecuciones cron programadas.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Política de restablecimiento de sesiones`},help:{"v1-1hmt7n3-6r":`Define el objeto de política de restablecimiento predeterminada que se utiliza cuando no se aplica ninguna configuración específica del tipo o del canal. De forma predeterminada, las sesiones no se restablecen automáticamente; utiliza programaciones diarias o por inactividad para activar esta función. /new y /reset siguen disponibles en cualquier momento.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Hora de restablecimiento diario de sesiones`},help:{"v1-wry8cv-59":`Establece la hora local (0-23) que marca el límite para el modo de restablecimiento diario, de modo que las sesiones se renueven a horas predecibles. Úsala con mode=daily y ajústala a la zona horaria esperada por el operador para que el comportamiento sea fácil de interpretar.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Minutos de inactividad para restablecer sesiones`},help:{"v1-1kzj0id-5e":`Establece el período de inactividad previo al restablecimiento en el modo por inactividad y también puede actuar como protección adicional en el modo diario. Utiliza valores mayores para preservar la continuidad o menores para mantener conversaciones más recientes y de corta duración.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Modo de restablecimiento de sesiones`},help:{"v1-e5ie4w-5b":`Selecciona la estrategia de restablecimiento: "none" desactiva el restablecimiento automático (opción predeterminada), "daily" restablece a una hora configurada e "idle" restablece tras un período de inactividad. /new y /reset siguen disponibles en todos los modos.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Restablecimiento de sesión por canal`},help:{"v1-1uxsulx-5h":`Permite definir excepciones de restablecimiento específicas por canal, usando el identificador del proveedor/canal como clave, para un control detallado del comportamiento. Úsalo solo cuando un canal necesite un comportamiento de restablecimiento especial que no cubran las políticas por tipo.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Restablecimiento de sesión por tipo de chat`},help:{"v1-ypdr7u-52":`Permite modificar el comportamiento de restablecimiento por tipo de chat (directo, grupo, hilo) cuando los valores predeterminados no son suficientes. Úsalo cuando la actividad de grupos o hilos requiera una frecuencia de restablecimiento distinta a la de los mensajes directos.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Restablecimiento de sesión (directo)`},help:{"v1-fjnlp5-56":`Define la política de restablecimiento para los chats directos y tiene prioridad sobre la configuración base session.reset para ese tipo. Usa esta opción como la excepción principal para mensajes directos en lugar del alias heredado dm.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Restablecimiento de sesión (grupo)`},help:{"v1-hl1200-4u":`Define la política de restablecimiento para las sesiones de chat grupal, donde los patrones de continuidad y ruido difieren de los de los mensajes directos. Usa períodos de inactividad más cortos para los grupos activos si la desviación del contexto se convierte en un problema.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Restablecimiento de sesión (hilo)`},help:{"v1-1hgpeke-4w":`Define la política de restablecimiento para las sesiones limitadas a un hilo, incluidos los flujos de trabajo centrados en hilos de canales. Úsalo cuando las sesiones de hilos deban caducar antes o después que las de otros tipos de chat.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Desencadenantes de reinicio de sesión`},help:{"v1-rcabsw-5a":`Enumera los desencadenantes de mensajes que fuerzan un reinicio de sesión cuando coinciden con el contenido entrante. Úsalos con moderación para frases explícitas de reinicio, de modo que el contexto no se pierda inesperadamente durante una conversación normal.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Ámbito de la sesión`},help:{"v1-axt4ds-5z":`Establece la estrategia base de agrupación de sesiones: "per-sender" las aísla por remitente y "global" comparte una sesión por contexto de canal. Mantén "per-sender" para un comportamiento multiusuario más seguro, salvo que se requiera expresamente un contexto compartido.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Política de envío de sesiones`},help:{"v1-17qpipb-5l":`Controla los permisos de envío entre sesiones mediante reglas de permiso o denegación evaluadas según channel, chatType y los prefijos de clave. Úsala para delimitar dónde pueden entregar mensajes las herramientas de sesión en entornos complejos.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Acción predeterminada de la política de envío de sesiones`},help:{"v1-15plhut-53":`Establece la acción de respaldo cuando no coincide ninguna regla de sendPolicy: "allow" o "deny". Mantén "allow" para configuraciones más sencillas, o elige "deny" cuando necesites reglas de permiso explícitas para cada destino.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Reglas de la política de envío de sesiones`},help:{"v1-o217za-5h":'Reglas ordenadas de permiso o denegación que se evalúan antes de la acción predeterminada, por ejemplo, `{ action: "deny", match: { channel: "discord" } }`. Coloca primero las reglas más específicas para que las reglas generales no oculten las excepciones.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Acción de la regla de envío de sesiones`},help:{"v1-178vm80-54":`Define la decisión de la regla como "allow" o "deny" cuando se cumplen los criterios de coincidencia correspondientes. Evalúe primero las reglas de denegación al aplicar límites estrictos con excepciones explícitas de autorización.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Coincidencia de la regla de envío de sesión`},help:{"v1-18qh5qg-5d":`Define condiciones opcionales de coincidencia de la regla que pueden combinar restricciones de channel, chatType y prefijo de clave. Mantenga las coincidencias acotadas para que la intención de la política sea clara y la depuración siga siendo sencilla.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Canal de la regla de envío de sesión`},help:{"v1-u5erwx-50":`Limita la aplicación de la regla a un identificador específico de canal o proveedor (por ejemplo, discord, telegram, slack). Use esta opción cuando un canal deba permitir o denegar la entrega independientemente de los demás.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Tipo de chat de la regla de envío de sesión`},help:{"v1-7cv4f9-4z":`Limita la aplicación de la regla según el tipo de chat (direct, group, thread) para que el comportamiento varíe según la forma de conversación. Use esta opción cuando los destinos de mensajes directos y de grupo requieran límites de seguridad diferentes.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Prefijo de clave de la regla de envío de sesión`},help:{"v1-ac4dee-5n":`Busca coincidencias con un prefijo normalizado de clave de sesión después de los pasos internos de normalización de claves en los componentes que aplican la política. Use esta opción para controles generales por prefijo y prefiera rawKeyPrefix cuando se requiera una coincidencia exacta con la clave completa.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Prefijo de clave sin procesar de la regla de envío de sesión`},help:{"v1-1g9w044-5e":`Coincide con el prefijo sin normalizar de la clave de sesión para aplicar la política a claves completas exactas. Úsalo cuando el keyPrefix normalizado sea demasiado amplio y necesites precisión con prefijos de agente o específica del transporte.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Modos de uso compartido de sesiones`},help:{"v1-xbh52d-5a":`Controla qué modos de colaboración pueden seleccionar los propietarios de sesiones y los administradores. Los valores booleanos omitidos se consideran habilitados de forma predeterminada; establece un modo en false para eliminarlo del selector y rechazar nuevas selecciones.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Permitir sesiones en borrador`},help:{"v1-1lzap27-2p":`Permite la visibilidad de borrador, que oculta las sesiones a los operadores que no sean propietarios ni administradores. Valor predeterminado: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Permitir sesiones de solo lectura`},help:{"v1-upl3nu-21":`Permite establecer las sesiones como de solo lectura para quienes no participen en ellas. Valor predeterminado: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Permitir sesiones con sugerencias`},help:{"v1-4i8owu-4g":`Permite la visibilidad con sugerencias. En esta fase, aplica la misma política de admisión que el modo de solo lectura; las colas de sugerencias se configuran mediante una función posterior. Valor predeterminado: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Ruta de almacenamiento de sesiones`},help:{"v1-hreznz-56":`Establece la ruta del archivo de almacenamiento de sesiones que se utiliza para conservar los registros de sesión entre reinicios. Usa una ruta explícita solo cuando necesites una distribución personalizada en disco, un destino específico para las copias de seguridad o almacenamiento en un volumen montado.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Vinculaciones de hilos de sesión`},help:{"v1-zbzihu-4s":`Valores predeterminados compartidos para la creación y el enrutamiento de sesiones vinculadas a hilos en los canales compatibles. Configure aquí los valores predeterminados globales y sobrescríbalos por canal solo cuando el comportamiento sea diferente.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Contexto de creación en hilos`},help:{"v1-1set6nw-4c":`Contexto nativo predeterminado del subagente para las creaciones vinculadas a hilos. Use "fork" para comenzar a partir de la transcripción del solicitante o "isolated" para crear un subagente sin contexto previo. Valor predeterminado: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Vinculación a hilos habilitada`},help:{"v1-foomtc-3f":`Interruptor principal global para la creación, el enrutamiento y la entrega de sesiones vinculadas a hilos. Desactívelo para deshabilitar la vinculación a hilos de forma global.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Tiempo de espera por inactividad de la vinculación a hilos (horas)`},help:{"v1-gffnx3-3h":`Periodo de inactividad predeterminado en horas para las sesiones vinculadas a hilos en todos los proveedores y canales (0 desactiva la caducidad por inactividad). Valor predeterminado: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Duración máxima de la vinculación a hilos (horas)`},help:{"v1-1xfcyhw-39":`Límite máximo absoluto opcional de duración en horas para las sesiones vinculadas a hilos en todos los proveedores y canales (0 desactiva el límite absoluto). Valor predeterminado: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Creación de sesiones vinculadas a hilos`},help:{"v1-1lqwbdl-46":`Control global predeterminado para crear sesiones de trabajo vinculadas a hilos desde sessions_spawn y las creaciones de hilos de ACP. Valor predeterminado: true cuando la vinculación a hilos está habilitada.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Destinos permitidos de enlaces simbólicos de habilidades`},help:{"v1-xzybiq-4t":`Directorios raíz de destino reales y de confianza a los que pueden apuntar los enlaces simbólicos de habilidades cuando están fuera de su directorio raíz de origen configurado. Limita este alcance, por ejemplo, al directorio de habilidades de un repositorio hermano.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Directorios adicionales de habilidades`},help:{"v1-11o7opu-53":`Directorios raíz adicionales de habilidades compartidas que se explorarán con la prioridad más baja. Úsalo para repositorios hermanos o paquetes de habilidades compartidas que deban estar disponibles sin copiarlos al espacio de trabajo de OpenClaw.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Supervisar Skills`},help:{"v1-1ckr2l5-5d":`Activa la supervisión del sistema de archivos para detectar cambios en las definiciones de habilidades y aplicar actualizaciones sin reiniciar todo el proceso. Mantén esta opción activada en los flujos de trabajo de desarrollo y desactívala en las imágenes de producción inmutables.`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Modo autónomo de Skill Workshop`},help:{"v1-1s3kgit-6j":`Controla el aprendizaje en segundo plano: "off" mantiene solo el aviso de sugerencia, "propose" crea propuestas pendientes y "auto" aplica las propuestas registradas y realiza una revisión semanal de las habilidades gestionadas por Workshop mediante ediciones normales de archivos. Valor predeterminado: "auto".`}},surfaces:{label:{"v1-exl2ye-g":`Políticas de superficies`},help:{"v1-vgtjbs-50":`Anulaciones de la política de mensajes para cada superficie, identificadas por el id de la superficie de entrega resuelta. Úsalo solo cuando una superficie desplegada necesite un tratamiento de las respuestas silenciosas más estricto que el predeterminado del agente.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Política de respuestas silenciosas de la superficie`},help:{"v1-12zgc3n-60":`Anula la política de respuestas silenciosas para una superficie de entrega resuelta. Los campos sin definir heredan agents.defaults.silentReply; usa ids de superficie de alcance limitado para que el comportamiento interno o específico de un grupo no se extienda a otros destinos.`}},talk:{label:{"v1-15ukbjj-4":`Hablar`},help:{"v1-1gx10xa-5g":`Ajustes de síntesis de voz del modo Talk para la identidad de voz, la selección del modelo, el formato de salida y el comportamiento de interrupción. Usa esta sección para ajustar la experiencia de voz del usuario y controlar la latencia y el coste.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Agente de Talk`},help:{"v1-iee5l9-2b":`Agente al que pertenecen las sesiones de Talk creadas sin una clave de sesión explícita vinculada a un agente.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Modo rápido de consulta de Talk`},help:{"v1-syf3xk-2o":`Usa esta opción para establecer el modo rápido en true o false para la ejecución normal del agente que gestiona las consultas en tiempo real de Talk.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Nivel de razonamiento de consulta de Talk`},help:{"v1-1ft5njw-2o":`Usa esta opción para sobrescribir el nivel de razonamiento de la ejecución normal del agente que gestiona las consultas en tiempo real de Talk.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Interrumpir Talk al hablar`},help:{"v1-8n9q4o-3l":`Si se establece en true (valor predeterminado), detiene la voz del asistente cuando el usuario empieza a hablar en el modo Talk. Mantén esta opción activada para alternar los turnos de conversación.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Proveedor activo de Talk`},help:{"v1-wgnxhg-1g":`Identificador del proveedor activo de Talk (por ejemplo, "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Ajustes de proveedores de Talk`},help:{"v1-oh0yuv-30":`Ajustes de Talk específicos de cada proveedor, organizados por identificador de proveedor. Durante la migración, da preferencia a estos ajustes frente a las claves heredadas talk.*.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Configuración del proveedor de Talk`},help:{"v1-36pblg-1r":`Campos de configuración de Talk propios del proveedor cuyo identificador coincide.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Clave de API del proveedor de Talk`},help:{"v1-1a1p9wp-v":`Clave de API del proveedor para el modo Talk.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk en tiempo real`},help:{"v1-c2re7j-3z":`Proveedor, modelo, voz, modo, transporte y estrategia de razonamiento de Talk en tiempo real. Mantén la configuración del proveedor de voz/TTS en talk.provider y talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Razonamiento de Talk en tiempo real`},help:{"v1-opsatw-37":`Estrategia de razonamiento de Talk: agent-consult para obtener ayuda del agente a través de Gateway, direct-tools para llamadas a herramientas locales o none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Enrutamiento de consultas de Talk en tiempo real`},help:{"v1-10qjcvk-5f":`Retransmisión alternativa a través de Gateway para las transcripciones finales del usuario cuando el proveedor en tiempo real omite openclaw_agent_consult. provider-direct conserva las respuestas del proveedor; force-agent-consult enruta a través de OpenClaw.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Instrucciones de Talk en tiempo real`},help:{"v1-1jaaj84-5p":`Instrucciones de sistema adicionales que se añaden al prompt integrado de Talk en tiempo real de OpenClaw. Úsalas para definir el estilo de voz, el tono y otros comportamientos en tiempo real del proveedor, manteniendo intactas las indicaciones de agent-consult.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Modo de Talk en tiempo real`},help:{"v1-1u2xui1-1l":`Modo de ejecución de Talk: realtime, stt-tts o transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Modelo de Talk en tiempo real`},help:{"v1-amou5a-27":`Identificador de modelo alternativo del proveedor en tiempo real para las sesiones de Talk del navegador o gestionadas por Gateway.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Margen de audio previo de Talk en tiempo real (ms)`},help:{"v1-1cwg07n-22":`Milisegundos de audio conservados antes de que se detecte actividad de voz en tiempo real.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Proveedor de Talk en tiempo real`},help:{"v1-wwsmpt-1o":`ID del proveedor de voz en tiempo real activo, como openai o google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Ajustes de proveedores de Talk en tiempo real`},help:{"v1-ruagcu-1r":`Ajustes de voz en tiempo real específicos de cada proveedor, organizados por ID de proveedor.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Configuración del proveedor de Talk en tiempo real`},help:{"v1-edfpxm-1u":`Configuración de voz en tiempo real propia del proveedor con el ID correspondiente.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Clave de API del proveedor de Talk en tiempo real`},help:{"v1-1fbmgpx-z":`Clave de API del proveedor para Talk en tiempo real.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Esfuerzo de razonamiento de Talk en tiempo real`},help:{"v1-157xd3e-2t":`Esfuerzo de razonamiento específico del proveedor para las sesiones de Talk en tiempo real, como minimal, low, medium o high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Duración del silencio de Talk en tiempo real (ms)`},help:{"v1-1grnu06-1y":`Milisegundos de silencio antes de que se confirme un turno del usuario de Talk en tiempo real.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Voz del hablante de Talk en tiempo real`},help:{"v1-1kgb166-2h":`Nombre de voz del hablante que sustituye al predeterminado del proveedor en tiempo real para las sesiones de Talk gestionadas por el navegador o el Gateway.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`ID de voz del hablante de Talk en tiempo real`},help:{"v1-1k8w6vk-2f":`ID de voz del hablante que sustituye al predeterminado del proveedor en tiempo real para las sesiones de Talk gestionadas por el navegador o el Gateway.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Transporte de Talk en tiempo real`},help:{"v1-2otjgn-2g":`Transporte de bytes/sesiones de Talk: webrtc, provider-websocket, gateway-relay o managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Umbral de VAD en tiempo real de Talk`},help:{"v1-nf5l2t-2j":`Umbral de detección de actividad de voz en tiempo real, de 0 (máxima sensibilidad) a 1 (mínima sensibilidad).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Tiempo de espera de silencio de Talk (ms)`},help:{"v1-1kim32f-59":`Milisegundos de silencio del usuario antes de que el modo Talk finalice y envíe la transcripción actual. Déjalo sin configurar para mantener el intervalo de pausa predeterminado de la plataforma (700 ms en macOS y Android, 900 ms en iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Configuración regional de voz de Talk`},help:{"v1-1un3x4l-4c":`Identificador de configuración regional BCP 47 para el reconocimiento de voz de Talk en los nodos de dispositivos y la alternativa de voz del sistema de iOS, por ejemplo, "ru-RU". Déjalo sin configurar para usar el valor predeterminado de cada dispositivo.`}},telemetry:{label:{"v1-sqprmo-9":`Telemetría`},help:{"v1-1o5tru3-55":`Consentimiento explícito para las estadísticas anónimas de uso de funciones que se adjuntan a la comprobación diaria de actualizaciones. Estas estadísticas están desactivadas de forma predeterminada y nunca incluyen mensajes, credenciales ni identificadores.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Marca de tiempo del consentimiento para las estadísticas de uso de funciones`},help:{"v1-1t051az-3t":`Marca de tiempo ISO que registra cuándo el operador aceptó o rechazó las estadísticas anónimas de uso de funciones. Evita que el asistente de configuración vuelva a preguntar.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Estadísticas anónimas de uso de funciones`},help:{"v1-1ptrwuq-4r":`Comparte los nombres de los canales y proveedores habilitados, el número de plugins y el número de sesiones recientes durante la comprobación diaria de actualizaciones. Está desactivado de forma predeterminada y siempre que DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Herramientas`},help:{"v1-1el54kl-5h":`Infraestructura de herramientas y valores predeterminados entre agentes. Las claves del nivel raíz gestionan la infraestructura y los valores predeterminados entre agentes; agents.defaults gestiona el comportamiento del bucle del agente; las entradas de cada agente pueden sobrescribir ambos donde se admita.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Acceso a herramientas entre agentes`},help:{"v1-1ynpa5f-cf":`Política para las llamadas a herramientas de sesión entre agentes: envíos, listado, historial, búsqueda y consultas de estado (habilitada de forma predeterminada). Usa allow para restringir los pares de agentes; enabled=false bloquea el acceso habitual entre agentes. Las sesiones de subagentes nativos y las sesiones secundarias de ACP que pertenecen al solicitante siguen siendo accesibles con la visibilidad tree o all. Para una separación estricta, establece tools.sessions.visibility en agent o self (tree sigue admitiendo las sesiones secundarias nativas/ACP del solicitante), o usa gateways independientes.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Lista de destinos permitidos entre agentes`},help:{"v1-1jt2ari-76":`Identificadores de agentes o patrones con * que pueden participar en llamadas entre agentes; tanto el agente solicitante como el de destino deben coincidir. El acceso entre agentes está habilitado de forma predeterminada, y si allow se omite o está vacío, se permite cualquier par. Define una lista explícita para restringir el acceso; las entradas en blanco lo deniegan.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Habilitar la herramienta entre agentes`},help:{"v1-w950oq-ba":`Habilita el acceso a herramientas de sesión entre agentes (valor predeterminado: true); si allow se omite o está vacío, se permite cualquier par de agentes. Establece false para bloquear el acceso habitual entre agentes; las sesiones de subagentes nativos y las sesiones secundarias de ACP que pertenecen al solicitante siguen siendo accesibles con la visibilidad tree o all. Para una separación estricta, establece tools.sessions.visibility en agent o self (tree sigue admitiendo las sesiones secundarias nativas/ACP del solicitante), o usa gateways independientes.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Lista de herramientas permitidas`},help:{"v1-1is3eaq-4v":`Lista absoluta de herramientas permitidas que sustituye los valores predeterminados derivados del perfil en entornos estrictos. Úsala solo cuando quieras ejecutar deliberadamente un subconjunto cuidadosamente seleccionado de capacidades de herramientas.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Adiciones a la lista de herramientas permitidas`},help:{"v1-1xw9zp8-57":`Entradas adicionales de la lista de herramientas permitidas que se combinan con el perfil de herramientas seleccionado y la política predeterminada. Mantén esta lista breve y explícita para que las auditorías puedan identificar rápidamente las excepciones deliberadas a la política.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Política de herramientas por proveedor`},help:{"v1-1ecljob-4y":`Reglas de permiso o denegación de herramientas por proveedor, con el ID del canal o proveedor como clave, que sustituyen las reglas generales para adaptar las capacidades a cada interfaz. Úsalas cuando un proveedor necesite controles más estrictos que la política global de herramientas.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Modo de código`},help:{"v1-1ecc39k-6k":'Modo de código genérico de OpenClaw. Si se omite a nivel global, el valor predeterminado es `"auto"`; un objeto definido sin `enabled` permanece desactivado. Las ejecuciones de agentes con este modo activado solo exponen `exec` y `wait` al modelo y acceden a las herramientas habituales mediante el puente del catálogo.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Activar el modo de código`},help:{"v1-rgstxz-aj":'Activación global del modo de código de OpenClaw. Si la configuración global está completamente ausente, el valor predeterminado es `"auto"`; un objeto definido sin `enabled` permanece desactivado. `"auto"` activa el modo para los modelos que prefieren el catálogo, mientras que `true` lo activa para las ejecuciones compatibles con herramientas. Las configuraciones de activación específicas del agente y del modelo tienen prioridad. Si el entorno de ejecución no está disponible, una ejecución con este modo activado se bloquea de forma segura en lugar de exponer la lista completa de herramientas.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Ejecutor del modo de código`},help:{"v1-l8nlk2-6x":`Ejecutor de JavaScript: "node" (predeterminado) utiliza vm de Node para código de confianza y no es un entorno aislado de seguridad; "quickjs" utiliza el complemento QuickJS WASM incluido para ejecutar código invitado con seguridad reforzada. Los permisos de las herramientas se aplican a ambos. Si el ejecutor seleccionado no está disponible, se bloquea la ejecución.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Límite de salida del modo de código`},help:{"v1-1hmij9q-1n":`Número máximo de bytes serializados devueltos a través de la salida del modo de código.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Límite de llamadas pendientes a herramientas en modo de código`},help:{"v1-3b5tyd-2i":`Número máximo de llamadas anidadas simultáneas a herramientas que una máquina virtual en modo de código puede iniciar antes de tener que reanudarse más tarde.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Máximo de resultados de búsqueda en modo de código`},help:{"v1-1gpue5r-28":`Número máximo de resultados de búsqueda del catálogo oculto que un programa en modo de código puede solicitar.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Límite de instantáneas en modo de código`},help:{"v1-1mmgkqy-1x":`Número máximo de bytes serializados que se conservan para una instantánea suspendida de QuickJS.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Límite de memoria en modo de código`},help:{"v1-xetora-6n":`Límite del heap del entorno invitado de QuickJS o presupuesto de memoria del heap de V8 del worker de Node, aplicado en la medida de lo posible, en bytes. La sobrecarga del entorno de ejecución de Node y las asignaciones mínimas del motor afectan al presupuesto efectivo; se excluyen los búferes externos y el RSS del proceso. Esto no constituye una garantía de seguridad.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Interfaz del modo de código`},help:{"v1-dsp2b9-2x":'Interfaz expuesta al modelo. Solo se admite "only": expone `exec` y `wait` del modo de código y oculta las herramientas normales.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Resultados de búsqueda predeterminados en modo de código`},help:{"v1-1io42lu-2m":"Número predeterminado de resultados de búsqueda del catálogo oculto que devuelve `catalog.search` en el modo de código."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`TTL de las instantáneas en modo de código`},help:{"v1-1nxfczz-28":"Tiempo durante el cual las ejecuciones suspendidas de Code Mode pueden reanudarse con `wait` antes de que caduquen."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Tiempo de espera del modo de código`},help:{"v1-8csycm-1p":"Tiempo máximo en milisegundos para una llamada a `exec` o `wait` en modo de código."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Lista de herramientas bloqueadas`},help:{"v1-wilr1b-4p":`Lista global de herramientas bloqueadas que impide el uso de las herramientas incluidas, incluso cuando las reglas del perfil o del proveedor las permitirían. Usa reglas de denegación para bloqueos de emergencia y una defensa en profundidad a largo plazo.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Acceso a herramientas con privilegios elevados`},help:{"v1-ehcm0r-5a":`Controles de acceso a herramientas con privilegios elevados para interfaces de comandos privilegiados a las que solo deberían poder acceder remitentes de confianza. Mantén esta opción desactivada a menos que los flujos de trabajo del operador requieran explícitamente acciones con privilegios elevados.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Reglas de autorización para herramientas con privilegios elevados`},help:{"v1-1u9bhih-54":`Reglas de autorización de remitentes para herramientas con privilegios elevados, normalmente con claves basadas en los formatos de identidad del canal o proveedor. Usa identidades explícitas y bien delimitadas para que los usuarios no autorizados no puedan activar comandos con privilegios elevados.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Habilitar el acceso a herramientas con privilegios elevados`},help:{"v1-1n8oyal-4l":`Habilita la vía de ejecución de herramientas con privilegios elevados cuando se superan las comprobaciones del remitente y de las políticas. Mantén esta opción desactivada en canales públicos o compartidos y actívala solo en contextos de confianza gestionados por el propietario.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Herramienta exec`},help:{"v1-p5piic-56":`Conjunto de políticas de la herramienta exec para el host de ejecución de shell, el modo de seguridad, el comportamiento de aprobación y las vinculaciones en tiempo de ejecución. Mantén valores predeterminados conservadores en producción y restringe las vías de ejecución con privilegios elevados.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Lista de modelos permitidos para apply_patch`},help:{"v1-4q5ovf-1x":`Lista opcional de identificadores de modelos permitidos (p. ej., "gpt-5.4" u "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`Habilitar apply_patch`},help:{"v1-1erkir4-31":`Habilita o deshabilita apply_patch para los modelos de OpenAI y OpenAI Codex cuando la política de herramientas lo permita (valor predeterminado: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch solo en el espacio de trabajo`},help:{"v1-x2z207-3o":`Restringe las rutas de apply_patch al directorio del espacio de trabajo (valor predeterminado: true). Establece false para permitir la escritura fuera del espacio de trabajo (peligroso).`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Aviso de ejecución tras la aprobación de exec (ms)`},help:{"v1-1gwwann-4z":`Tiempo de espera en milisegundos antes de mostrar un aviso de ejecución en curso tras conceder una aprobación de exec. Auméntalo para reducir el parpadeo con comandos rápidos o redúcelo para informar al operador con mayor rapidez.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Solicitud de confirmación de exec`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Resaltado de comandos de exec`},help:{"v1-kyxd4o-4n":`Muestra el resaltado de comandos generado por el analizador en las solicitudes de aprobación de exec (valor predeterminado: false). Habilita esta opción para mostrar el texto de los comandos resaltado sin cambiar la política de aprobación de exec.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Caducidad de autorizaciones persistentes (días)`},help:{"v1-5uxe2j-6r":`Duración predeterminada, en días (1-3650), de las autorizaciones persistentes creadas mediante allow-always en las aprobaciones de automatizaciones. Si no se establece, las autorizaciones siguen siendo válidas hasta que se revoquen o cambie la automatización a la que pertenecen. Las condiciones quedan fijadas al crearlas, por lo que los cambios solo afectan a las autorizaciones futuras.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Destino de exec`},help:{"v1-rno1mf-5q":`Selecciona la estrategia de destino de ejecución para los comandos de shell. Usa "auto" para adaptar el comportamiento al entorno de ejecución (sandbox si está disponible; de lo contrario, gateway), o establece explícitamente sandbox/gateway/node cuando necesites un entorno fijo.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Modo de ejecución`},help:{"v1-1wi6t4l-5q":`Selector normalizado de políticas de ejecución. Usa "auto" para que un clasificador revise los casos sin aprobación, "ask" para que los revise una persona, "allowlist" para permitir únicamente comandos seguros según criterios deterministas, o "full" para operaciones locales de confianza.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Vinculación de nodo de ejecución`},help:{"v1-rfnz54-4s":`Configuración de vinculación de nodos para las herramientas de ejecución cuando la ejecución de comandos se delega a través de nodos conectados. Usa una vinculación de nodo explícita solo cuando se requiera enrutamiento entre varios nodos.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Notificar al finalizar la ejecución`},help:{"v1-1ounlvx-3q":`Cuando es true (valor predeterminado), la finalización de las sesiones de ejecución en segundo plano y los eventos del ciclo de vida de ejecución en nodos ponen en cola un evento del sistema y solicitan una señal de actividad.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Notificar ejecuciones exitosas sin salida`},help:{"v1-1wx4xxd-3d":`Cuando es true, las ejecuciones en segundo plano que finalizan correctamente sin salida también ponen en cola un evento del sistema de finalización (valor predeterminado: false).`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Anteponer a PATH para la ejecución`},help:{"v1-s1aimc-1r":`Directorios que se anteponen a PATH para las ejecuciones (gateway/sandbox).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Revisor de ejecución`},help:{"v1-12y548k-4x":`Revisor de exec basado en un modelo que se usa en modo automático antes de recurrir a la aprobación humana. Configure aquí un modelo específico si desea aislar la revisión de exec del modelo del agente principal.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Modo rápido del revisor de ejecución`},help:{"v1-175bx14-8u":`Modo rápido opcional para las revisiones de aprobación de OpenClaw: true solicita procesamiento prioritario en las rutas compatibles de OpenAI Responses y ChatGPT/OAuth; false solicita procesamiento estándar. Omítelo para conservar los valores predeterminados del proveedor. El modo rápido puede tener un coste mayor y está sujeto a la disponibilidad del proveedor. No configura Codex Guardian nativo.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Modelo del revisor de exec`},help:{"v1-1lltiy5-3i":`Anulación opcional de proveedor/modelo para el agente revisor de exec. Omítala para reutilizar el modelo principal configurado para el agente de destino.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Razonamiento del revisor de ejecución`},help:{"v1-yg2gby-6u":`Esfuerzo de razonamiento opcional para las revisiones de aprobación de OpenClaw basadas en modelos: minimal, low, medium, high, xhigh o max. Omítelo para conservar los valores predeterminados del proveedor. Los niveles compatibles se normalizan para el modelo seleccionado. No configura Codex Guardian nativo.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Tiempo de espera del revisor de exec (ms)`},help:{"v1-1o30chi-3w":`Tiempo de espera por etapa del revisor de exec, en milisegundos, para la preparación del modelo y la generación de la respuesta antes de recurrir a la aprobación humana (predeterminado: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Perfiles de binarios seguros de exec`},help:{"v1-4cdcwe-29":`Perfiles opcionales de seguridad por binario (límites de argumentos posicionales + opciones permitidas/denegadas).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Binarios seguros de exec`},help:{"v1-1of1m2s-21":`Permitir que los binarios seguros que solo usan stdin se ejecuten sin entradas explícitas en la lista de permitidos.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Directorios de confianza para binarios seguros de exec`},help:{"v1-zljbcn-2v":`Directorios adicionales declarados explícitamente como de confianza para las comprobaciones de rutas de binarios seguros (las entradas de PATH nunca se consideran de confianza automáticamente).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Seguridad de exec`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Exigir aprobación para la evaluación en línea`},help:{"v1-jkmgo7-5z":"Exigir aprobación explícita para las formas de evaluación en línea de intérpretes, como `python -c`, `node -e`, `ruby -e` u `osascript -e`. Impide la reutilización silenciosa de la lista de permitidos y, para esas formas, sustituye el permiso permanente por una solicitud de aprobación en cada ocasión."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Tiempo de espera de ejecución (segundos)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Herramientas del sistema de archivos limitadas al espacio de trabajo`},help:{"v1-1mhuvka-2s":`Restringir las herramientas del sistema de archivos (read/write/edit/apply_patch) al directorio del espacio de trabajo (valor predeterminado: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`Identidad de GitHub CLI y autor de Git`},help:{"v1-1fl77im-5s":`Perfil local administrado de GitHub CLI y autor de Git opcional para las herramientas del agente. Omite este objeto para conservar la cuenta y el autor nativos del usuario que ejecuta el Gateway; las credenciales remotas del repositorio nunca se sobrescriben.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Correo electrónico del autor de Git`},help:{"v1-kol5g6-1i":`Correo electrónico opcional del autor y del confirmador de Git, limitado al proceso.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Nombre del autor de Git`},help:{"v1-z5bl1f-1h":`Nombre opcional del autor y del confirmador de Git, limitado al proceso.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Tipo de credencial de GitHub`},help:{"v1-qi3qun-3q":`Identifica un perfil OAuth administrado cuya credencial de actualización rotatoria pertenece al Gateway. Los perfiles que omiten este campo usan un token de acceso personal.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`Versión del perfil de GitHub`},help:{"v1-4lzl0-27":`Versión de perfil generada y opaca que se usa para cambiar las credenciales administradas de forma atómica.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Activar la comprensión de enlaces`},help:{"v1-23t2io-59":`Activar el preprocesamiento automático de comprensión de enlaces para que se pueda resumir el contenido de las URL antes del razonamiento del agente. Mantén esta opción activada para obtener un contexto más completo y desactívala cuando se requiera un procesamiento estrictamente mínimo.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Máximo de enlaces para la comprensión de enlaces`},help:{"v1-ksxmcv-52":`Número máximo de enlaces que se expanden por turno durante la comprensión de enlaces. Usa valores más bajos para controlar la latencia y el coste en hilos con muchos mensajes, y valores más altos cuando el contexto de varios enlaces sea fundamental.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Modelos de comprensión de enlaces`},help:{"v1-6j3mnw-5a":`Lista de modelos preferidos para las tareas de comprensión de enlaces, evaluados en orden como alternativas cuando se admita. Usa primero modelos ligeros para los resúmenes habituales y modelos más potentes solo cuando sea necesario.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Ámbito de la comprensión de enlaces`},help:{"v1-183cwpa-55":`Controla cuándo se ejecuta la comprensión de enlaces según el contexto de la conversación y el tipo de mensaje. Mantén un ámbito restringido para evitar consultas innecesarias en mensajes cuyos enlaces no requieran ninguna acción.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Tiempo de espera de la comprensión de enlaces (s)`},help:{"v1-61v30o-4p":`Tiempo de espera máximo en segundos para la comprensión de cada enlace antes de omitir los enlaces no resueltos. Mantén este límite acotado para evitar bloqueos prolongados cuando los sitios externos sean lentos o inaccesibles.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`Detección de bucles de herramientas`},help:{"v1-1e3rls8-5g":`Controla la detección de bucles de herramientas basada en el historial reciente y la protección posterior a la compactación. Omite esta opción para mantener desactivada la detección basada en el historial reciente y activada la protección posterior a la compactación. Establece true para habilitar ambas o false para deshabilitar ambas.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Política de archivos adjuntos para la comprensión de audio`},help:{"v1-1s3t9s5-3o":`Elige qué archivos de audio adjuntos coincidentes se procesan. Procesa solo el primero, salvo que quieras transcribir varios archivos adjuntos.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Formato de reproducción de la transcripción`},help:{"v1-glpdzh-3i":`Da formato a la transcripción enviada al chat con un marcador de posición {transcript}. Mantén intacto el marcador para que el mensaje incluya la transcripción.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Enviar transcripción al chat`},help:{"v1-1dedp8c-3r":`Envía la transcripción del audio al chat de origen antes de que el agente la procese. Activa esta opción cuando los usuarios necesiten verificar lo que escuchó el sistema.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Activar comprensión de audio`},help:{"v1-1v0x7te-2m":`Activa la comprensión de audio para transcribir notas de voz o clips de audio e incorporarlos al contexto del agente.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Idioma de comprensión de audio`},help:{"v1-1ruqt97-3z":`Indicación de idioma predeterminada para los proveedores de transcripción de audio. Configúrala cuando se conozca el idioma hablado principal y la detección del proveedor no sea fiable.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Máximo de bytes para comprensión de audio`},help:{"v1-1mcckc8-43":`Límite de tamaño predeterminado de la entrada de audio para los modelos configurados y detectados automáticamente. Establécelo en el tamaño de la grabación más grande que deban aceptar tus proveedores y tu red.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Máximo de caracteres para comprensión de audio`},help:{"v1-eo1dp-43":`Longitud máxima predeterminada de la transcripción para los modelos configurados y detectados automáticamente. Usa un valor menor para evitar que las notas de voz largas amplíen el contexto del agente.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Modelo preferido de comprensión de audio`},help:{"v1-1n5zya1-3c":`Prioriza una entrada de tools.media.models etiquetada por capacidad para la transcripción de audio antes de recurrir a las demás alternativas compatibles.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Instrucción para la comprensión de audio`},help:{"v1-1v5jtay-4b":`Instrucción predeterminada para la transcripción de audio cuando una entrada de modelo no la sobrescribe. Mantén la instrucción estable cuando los flujos de trabajo posteriores dependan del estilo de la transcripción.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Ámbito de la comprensión de audio`},help:{"v1-1pptfg0-3w":`Restringe la comprensión de audio por canal, tipo de chat o clave de origen. Mantén un ámbito limitado cuando la transcripción automática sea sensible o costosa.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Tiempo de espera de la comprensión de audio (s)`},help:{"v1-n8wc6c-3b":`Tiempo de espera predeterminado para las solicitudes de comprensión de audio. Auméntalo para grabaciones largas o modelos locales de transcripción más lentos.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Concurrencia de la comprensión multimedia`},help:{"v1-13kr9np-58":`Número máximo de operaciones simultáneas de comprensión multimedia por turno entre las tareas de imagen, audio y vídeo. Reduce este valor en implementaciones con recursos limitados para evitar la saturación de la CPU o la red.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Política de archivos adjuntos para la comprensión de imágenes`},help:{"v1-11hofbw-3e":`Elige qué imágenes adjuntas coincidentes se procesan. Procesa solo la primera, a menos que quieras analizar varias imágenes.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Activar la comprensión de imágenes`},help:{"v1-1b2zw34-50":`Activa la comprensión de imágenes para interpretar las imágenes adjuntas o referenciadas como contexto textual. Desactívala si necesitas trabajar solo con texto o quieres evitar los costos de procesamiento de imágenes.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Máximo de bytes para la comprensión de imágenes`},help:{"v1-jwwpd1-3v":`Límite predeterminado del tamaño de las imágenes de entrada para los modelos configurados y detectados automáticamente. Ajusta este valor a los límites de carga útil del proveedor y al ancho de banda del despliegue.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Máximo de caracteres para la comprensión de imágenes`},help:{"v1-ebnxhk-3q":`Longitud máxima predeterminada de las descripciones de imágenes. Usa un valor menor para un contexto compacto o uno mayor para un OCR y un análisis de escenas detallados.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Modelo preferido para la comprensión de imágenes`},help:{"v1-1o2uwo6-3c":`Da preferencia a una entrada de tools.media.models etiquetada por capacidad para la comprensión de imágenes antes de recurrir a las demás alternativas compatibles.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Instrucción para la comprensión de imágenes`},help:{"v1-1jdcu8b-3u":`Instrucción predeterminada para la comprensión de imágenes cuando una entrada no la sobrescribe. Mantén esta instrucción determinista si los consumidores dependen de descripciones estables.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Ámbito de la comprensión de imágenes`},help:{"v1-tievo1-3s":`Restringe la comprensión de imágenes por canal, tipo de chat o clave de origen. Mantén este ámbito limitado en canales con mucha actividad o no confiables para controlar el procesamiento.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Tiempo de espera de la comprensión de imágenes (s)`},help:{"v1-1wcm84x-31":`Tiempo de espera predeterminado para las solicitudes de comprensión de imágenes. Auméntalo para imágenes grandes o modelos de visión locales más lentos.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Modelos compartidos de comprensión multimedia`},help:{"v1-f34u65-47":`Lista canónica de modelos de comprensión multimedia. Usa etiquetas de capacidad de imagen, audio o vídeo en cada entrada para que cada flujo de procesamiento seleccione solo alternativas compatibles.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Política de archivos adjuntos para la comprensión de vídeo`},help:{"v1-1qm1qrc-3e":`Elige qué archivos de vídeo adjuntos que cumplan los criterios se procesan. Procesa solo el primero, a menos que quieras analizar varios vídeos.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Activar la comprensión de vídeo`},help:{"v1-1ltx5gl-58":`Activa la comprensión de vídeo para que los clips puedan resumirse en texto para el razonamiento y las respuestas posteriores. Desactívala cuando el procesamiento de vídeo no esté permitido por la política o resulte demasiado costoso para tu implementación.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Máximo de bytes para la comprensión de vídeo`},help:{"v1-2mp77v-3v":`Límite de tamaño predeterminado de los vídeos de entrada para los modelos configurados y detectados automáticamente. Ajusta este valor a los límites de carga del proveedor y al ancho de banda de la implementación.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Máximo de caracteres para la comprensión de vídeo`},help:{"v1-1j0x40b-3j":`Longitud máxima predeterminada de la descripción del vídeo. Usa un valor menor para un contexto compacto o uno mayor para resúmenes detallados de las escenas.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Modelo preferido de comprensión de vídeo`},help:{"v1-1cygq5k-3c":`Prioriza una entrada de tools.media.models etiquetada por capacidad para la comprensión de vídeo antes de recurrir a las demás alternativas compatibles.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Instrucción para la comprensión de vídeo`},help:{"v1-ul2jx4-3r":`Instrucción predeterminada para la comprensión de vídeo cuando una entrada no la sustituye. Mantenla determinista cuando los consumidores dependan de resúmenes estables.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Ámbito de la comprensión de vídeo`},help:{"v1-7gfrx3-3s":`Restringe la comprensión de vídeo por canal, tipo de chat o clave de origen. Mantén este ámbito limitado en canales con mucha actividad o no confiables para controlar el procesamiento.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Tiempo de espera de la comprensión de vídeo (s)`},help:{"v1-e8rzsy-33":`Tiempo de espera predeterminado para las solicitudes de comprensión de vídeo. Auméntalo para clips más largos o modelos de análisis locales más lentos.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Lista de acciones de mensajes permitidas`},help:{"v1-1iceqwa-5c":`Lista global de acciones de mensajes permitidas para la herramienta de mensajes. Úsala solo cuando todo el entorno de ejecución deba exponer y aceptar un conjunto reducido de acciones; prioriza las listas de acciones permitidas por agente para los agentes públicos o en entornos aislados.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Activar la difusión de mensajes`},help:{"v1-1ms74z7-14":`Activa la acción de difusión (valor predeterminado: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Permitir envíos entre contextos (entre proveedores)`},help:{"v1-276qxo-2s":`Permite envíos entre distintos proveedores (valor predeterminado: true). Establece el valor en false para bloquear los mensajes entre proveedores.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Permitir envíos entre contextos (mismo proveedor)`},help:{"v1-1sg4x49-1z":`Permitir envíos a otros canales del mismo proveedor (valor predeterminado: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Marcador de envíos entre contextos`},help:{"v1-1fg6jrp-1z":`Añadir un marcador de origen visible al enviar entre contextos (valor predeterminado: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Prefijo del marcador de envíos entre contextos`},help:{"v1-eblsru-1p":`Prefijo de texto para los marcadores de envíos entre contextos (admite "{channel}").`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Sufijo del marcador de envíos entre contextos`},help:{"v1-1nk0jub-1p":`Sufijo de texto para los marcadores de envíos entre contextos (admite "{channel}").`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Perfil de herramientas`},help:{"v1-h6k98q-5k":`Nombre del perfil global de herramientas utilizado para seleccionar una política base predefinida de herramientas antes de aplicar ajustes de permisos y denegaciones. Úselo para mantener una configuración coherente del entorno entre agentes y mantenga estables los nombres de los perfiles.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Política de herramientas del entorno aislado`},help:{"v1-ea7awo-4k":`Contenedor de la política de herramientas para las ejecuciones de agentes en entornos aislados, que permite establecer límites de capacidades específicos para dichas ejecuciones. Úselo para reforzar la seguridad en entornos aislados.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Política de permisos y denegaciones de herramientas del entorno aislado`},help:{"v1-ub701o-4t":`Política de permisos y denegaciones de herramientas que se aplica cuando los agentes se ejecutan en entornos aislados. Mantenga las políticas al mínimo para que las tareas del entorno aislado no puedan derivar en acciones externas innecesarias.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Visibilidad de las herramientas de sesión`},help:{"v1-1vtq2rh-c5":`Controla a qué sesiones pueden acceder sessions_list/sessions_history/sessions_search/sessions_send/session_status. ("all", valor predeterminado = cualquier sesión en el Gateway, incluidas las de otros agentes y usuarios; "agent" = cualquier sesión del ID de agente actual; "self" = solo la actual; "tree" = la sesión actual + las sesiones de subagentes creadas). El acceso entre agentes está activado de forma predeterminada y su alcance se define mediante tools.agentToAgent; usa una visibilidad más limitada para restringir el acceso.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Política de herramientas de subagentes`},help:{"v1-1xoug01-4z":`Capa de política de herramientas para los subagentes creados que permite restringir o ampliar la disponibilidad de herramientas respecto a los valores predeterminados del agente principal. Úsala para limitar las capacidades de los agentes delegados al objetivo de la tarea.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Política de herramientas permitidas y denegadas para subagentes`},help:{"v1-7vxsbf-5d":`Política de herramientas permitidas y denegadas aplicada a los entornos de ejecución de los subagentes creados. Mantén su alcance más limitado que el del agente principal. Las herramientas propias del agente principal, como progress_card, siempre se deniegan, incluso mediante allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Enjambre`},help:{"v1-1q96vvs-45":`Orquestación de subagentes en modo recolector. Activada de forma predeterminada; establece false para desactivarla. Los permisos de herramientas siguen aplicándose a agents_wait y a las opciones de creación de enjambres.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Agente predeterminado del enjambre`},help:{"v1-p4alpg-2m":`Agente de destino predeterminado para las creaciones de enjambres que omitan agentId. La lista de subagentes permitidos sigue aplicándose.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Activar enjambre`},help:{"v1-1nnnrq9-2e":`Activa los subagentes en modo recolector y agents_wait. Está activado de forma predeterminada; establece false para desactivarlo.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Procesos hijos activos por grupo de enjambre`},help:{"v1-kfx6qp-1c":`Número máximo de procesos hijos recolectores activos por grupo de enjambre.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`Procesos hijos simultáneos del enjambre`},help:{"v1-1d46jtm-1s":`Número máximo de procesos hijos recolectores que se ejecutan simultáneamente por grupo de enjambre.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Total de procesos hijos por grupo de enjambre`},help:{"v1-1gc9vl1-1e":`Número máximo de procesos recolectores creados durante toda la vida útil de cada grupo de enjambre.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Tiempo máximo de espera del enjambre`},help:{"v1-bog18y-1g":`Tiempo máximo de espera aceptado por agents_wait, en segundos.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Búsqueda de herramientas`},help:{"v1-s0kx04-7y":`Compacta catálogos extensos de herramientas de OpenClaw, MCP y clientes. Los entornos de ejecución de OpenClaw usan automáticamente Tool Search estructurado si no se configura esta opción; Code Mode tiene prioridad cuando está activo y Codex usa su búsqueda nativa. Establece false para deshabilitarlo, true para usar el puente de código o usa el formato de objeto para elegir un modo.`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`Tiempo máximo de ejecución del código de búsqueda de herramientas`},help:{"v1-105r499-34":"Tiempo máximo en milisegundos para una ejecución de `tool_search_code`. El entorno de ejecución limita los valores al intervalo admitido de 1s..60s."}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Activar la búsqueda de herramientas`},help:{"v1-1vm3hfr-4h":"Activa la búsqueda de herramientas. Cuando está activada, OpenClaw oculta los catálogos grandes de herramientas detrás de `tool_search_code` o de herramientas estructuradas de búsqueda, descripción y llamada durante las ejecuciones del entorno integrado."}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Máximo de resultados de búsqueda de herramientas`},help:{"v1-7du4kh-32":`Número máximo de resultados de búsqueda de herramientas que puede solicitar un modelo. En tiempo de ejecución, los valores se limitan al intervalo admitido de 1..50.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Interfaz de búsqueda de herramientas`},help:{"v1-jybcbe-7x":'Elige la interfaz disponible para el modelo: "code" expone `tool_search_code`; "tools" expone herramientas estructuradas de búsqueda, descripción y llamada como alternativa; "directory" mantiene visible un directorio limitado de herramientas, expone un conjunto limitado de esquemas probables o necesarios y deja el resto accesible mediante búsqueda, descripción y llamada.'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Resultados predeterminados de búsqueda de herramientas`},help:{"v1-1uchq7t-39":"Número predeterminado de resultados de búsqueda de herramientas que se devuelven cuando el modelo omite un límite. En tiempo de ejecución, este valor se limita a `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Activar la herramienta de planes estructurados`},help:{"v1-1xgegme-4o":"Herramienta de estado unificada `progress_card` para planes persistentes y notas narrativas en sesiones principales. Activada de forma predeterminada; establece false para desactivarla. Nunca está disponible para subagentes."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Herramientas web`},help:{"v1-fpsy5-4y":`Agrupación de políticas de herramientas web para configurar proveedores de búsqueda y recuperación, límites y comportamiento alternativo. Mantén los ajustes activados en consonancia con la disponibilidad de claves de API y la política de conexiones de red salientes.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`TTL de la caché de recuperación web (min)`},help:{"v1-1hk89qp-17":`TTL de la caché en minutos para los resultados de web_fetch.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Activar la herramienta de recuperación web`},help:{"v1-yrswld-1f":`Activa la herramienta web_fetch (recuperación HTTP ligera).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Encabezados de solicitud de obtención web`},help:{"v1-16bjkv5-me":"Encabezados de solicitud adicionales enviados con las solicitudes directas de web_fetch, por ejemplo, encabezados de enrutamiento del Gateway o de autenticación. Todos los valores configurados se consideran sensibles y se ocultan en la configuración expuesta y en las capturas de depuración. Los valores son cadenas de texto simples, admiten la sustitución ${VAR} y el escape literal global $${VAR}, y se envían a las URL elegidas por el modelo. Las entradas se validan al construir la solicitud, no al cargar la configuración, por lo que los nombres no válidos o los valores que no se pueden enviar se descartan y se registran en lugar de deshabilitar la funcionalidad; también se descartan Accept, Accept-Language, User-Agent y los encabezados de delimitación como Transfer-Encoding. Usa tools.web.fetch.userAgent para cambiar el agente de usuario. Las redirecciones entre orígenes conservan únicamente los encabezados de la lista de permitidos seguros de guarded-fetch, y los cambios en los encabezados realmente enviados generan particiones separadas en la caché de obtención."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Máximo de caracteres de obtención web`},help:{"v1-12d1fw7-1d":`Máximo de caracteres devueltos por web_fetch (se trunca el resultado).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Límite absoluto de caracteres de obtención web`},help:{"v1-cl2mf1-1v":`Límite absoluto de maxChars de web_fetch (se aplica a la configuración y a las llamadas a herramientas).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Máximo de redirecciones de obtención web`},help:{"v1-t6eak9-1h":`Máximo de redirecciones permitidas para web_fetch (predeterminado: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Tamaño máximo de descarga de obtención web (bytes)`},help:{"v1-q6ld9c-10":`Tamaño máximo de descarga antes del truncamiento.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Proveedor de obtención web`},help:{"v1-6pb3nv-v":`ID del proveedor alternativo de obtención web.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Extracción con Readability para la obtención web`},help:{"v1-19exqzx-2c":`Usar Readability para extraer el contenido principal del HTML (recurre a una limpieza básica del HTML como alternativa).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`Política SSRF de obtención web`},help:{"v1-qtn7zx-3c":`Excepciones de alcance limitado a la política SSRF para web_fetch. Mantenga un alcance restringido y actívelas solo en entornos conocidos de proxy de red local.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Nombres de host permitidos para la obtención web`},help:{"v1-1j9ctya-35":`Nombres de host exactos o direcciones IP literales permitidos para web_fetch, incluidos los destinos que de otro modo estarían bloqueados. Mantenga la lista al mínimo.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Permitir el rango local único de IPv6 para la obtención web`},help:{"v1-1eyz55i-3b":`Permitir direcciones locales únicas de IPv6 (fc00::/7) para ofrecer compatibilidad con proxies de IP ficticias de confianza, como sing-box, Clash o Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Permitir el rango de pruebas de rendimiento de RFC 2544 para la obtención web`},help:{"v1-u5asdb-2y":`Permitir las direcciones IP del rango de pruebas de rendimiento de RFC 2544 (198.18.0.0/15) para ofrecer compatibilidad con proxies de IP ficticias, como Clash o Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Nombres de host bloqueados para la obtención web`},help:{"v1-1164vvk-66":`Patrones de nombres de host bloqueados antes de la resolución DNS y de las reglas de permiso en cada redirección de web_fetch. Admite hosts exactos y "*.example.com" solo para subdominios; añade "example.com" por separado para bloquear el dominio raíz. Si está vacío o no se configura, no añade bloqueos.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Permitir acceso peligroso a redes privadas en la obtención web`},help:{"v1-2s6mv7-3t":`Permite que web_fetch acceda a destinos de redes privadas e internas. Mantén esta opción desactivada a menos que las URL seleccionadas por el modelo sean de confianza en este despliegue.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Tiempo de espera de la obtención web (s)`},help:{"v1-1c3yfr4-16":`Tiempo de espera en segundos para las solicitudes de web_fetch.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`User-Agent de la obtención web`},help:{"v1-s7pe8j-1e":`Sustituye el encabezado User-Agent de las solicitudes de web_fetch.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Proxy de entorno de confianza para la obtención web`},help:{"v1-1ypkqj7-54":`Enruta web_fetch a través de un proxy HTTP(S) de confianza configurado mediante variables de entorno y permite que el proxy resuelva el DNS. Activa esta opción solo cuando el operador controle ese proxy y este aplique la política de tráfico saliente después de la resolución DNS.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`TTL de la caché de búsqueda web (min)`},help:{"v1-6trzlf-18":`TTL de la caché en minutos para los resultados de web_search.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Activar la herramienta de búsqueda web`},help:{"v1-n1cm4y-27":`Activa web_search gestionado y la búsqueda nativa opcional de Codex para los modelos compatibles.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Máximo de resultados de búsqueda web`},help:{"v1-mrw7mi-z":`Número de resultados que se devolverán (1-10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Dominios permitidos de Codex`},help:{"v1-1cv4y44-43":`Lista de dominios permitidos para web_search nativo de Codex. En los turnos con búsqueda alojada nativa, también restringe web_fetch gestionado; los turnos con proveedores gestionados no cambian.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Tamaño del contexto de búsqueda de Codex`},help:{"v1-antack-1u":`Indicación del tamaño del contexto de búsqueda nativa de Codex: "low", "medium" o "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Activar la búsqueda web nativa de Codex`},help:{"v1-ek2jzd-1k":`Activar la búsqueda web nativa de Codex para modelos compatibles con Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Modo de búsqueda web de Codex`},help:{"v1-1ahyq9f-32":`Preferencia de búsqueda web nativa de Codex: "cached" (predeterminado; los turnos de Codex sin restricciones lo resuelven como live) o "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Ciudad del usuario de Codex`},help:{"v1-1y95orp-1d":`Ciudad aproximada enviada a la búsqueda web nativa de Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`País del usuario de Codex`},help:{"v1-1xkm5ms-1g":`País aproximado enviado a la búsqueda web nativa de Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Región del usuario de Codex`},help:{"v1-lhar02-1l":`Región o estado aproximados que se envían a la búsqueda web nativa de Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Zona horaria del usuario de Codex`},help:{"v1-fgv9fh-1h":`Zona horaria aproximada que se envía a la búsqueda web nativa de Codex.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Proveedor de búsqueda web`},help:{"v1-10omglr-1x":`ID del proveedor de búsqueda. Si se omite, se detecta automáticamente a partir de las claves de API disponibles.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Tiempo de espera de la búsqueda web (s)`},help:{"v1-i0egvw-17":`Tiempo de espera en segundos para las solicitudes de web_search.`}},transcripts:{label:{"v1-1iqk6o8-b":`Transcripciones`},help:{"v1-1i0sc09-66":`Configuración principal de captura de transcripciones para notas de reuniones, herramientas de agentes con capacidad de grabación y fuentes configuradas de inicio automático para reuniones en directo. Los complementos de reuniones guardan notas persistentes de forma predeterminada; establece enabled en false para desactivar esta función globalmente.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Fuentes de inicio automático de transcripciones`},help:{"v1-1mzsl79-5s":`Fuentes de transcripción en directo gestionadas automáticamente desde el inicio del Gateway. Cada entrada se habilita por el hecho de estar presente; elimina una entrada para deshabilitar esa fuente. Las fuentes capturan de forma continua, salvo que whenOccupied esté habilitado.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`ID de cuenta de transcripción`},help:{"v1-6g2kjj-4b":`Identificador opcional de cuenta del proveedor o de espacio de trabajo para las fuentes de transcripción que necesitan distinguir entre cuentas. Usa el formato de ID de cuenta documentado por el proveedor.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`ID de canal de transcripción`},help:{"v1-1lk9d5o-4u":`ID del canal del proveedor para la fuente de transcripción en directo, como un canal de voz de Discord o un canal de reuniones rápidas de Slack. Verifica la semántica de los ID específicos del proveedor antes de habilitar el inicio automático.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`ID del servidor de Discord`},help:{"v1-fyfgnk-4l":`ID opcional del servidor de Discord para las fuentes de transcripción de voz de Discord. Configúralo con el channelId correspondiente cuando el proveedor necesite buscar canales de voz dentro de un servidor.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`URL de la reunión que se transcribirá`},help:{"v1-1xtt9ci-4f":`URL de reunión opcional para los proveedores que se unen mediante una URL en lugar de un ID de canal. Usa solo enlaces de reuniones de confianza, ya que el inicio automático puede unirse a esa reunión y capturarla.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`ID del proveedor de la fuente de transcripción`},help:{"v1-1uur06p-3s":`ID del proveedor de la fuente de transcripción, como un proveedor de voz de Discord o un futuro proveedor de reuniones rápidas de Slack. Usa el ID exacto que expone el complemento del proveedor.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`ID de la sesión de transcripción`},help:{"v1-xyo4x5-5o":`ID fijo opcional de la sesión de transcripción para esta fuente de inicio automático. Se ignora cuando whenOccupied es true. Déjalo sin configurar para que se generen los ID, a menos que necesites un selector diario estable y puedas evitar conflictos en el mismo día.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Título de la transcripción`},help:{"v1-ycjnmp-5y":`Título opcional para futuras capturas de transcripción. Cambiar solo los títulos mantiene las capturas actuales en ejecución y no modifica el título con el que se iniciaron ni las notas guardadas. Los demás cambios en las fuentes conservan su comportamiento habitual de reinicio.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Captura de transcripción cuando hay participantes`},help:{"v1-34jid4-78":`Inicia una nueva sesión de transcripción cada vez que hay personas presentes en la fuente y la detiene (generando notas) cuando se retira la última persona. Requiere un proveedor que informe de la presencia de participantes, como discord-voice. Valor predeterminado: false (captura continua desde el inicio del Gateway).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Transcripciones habilitadas`},help:{"v1-fyqqr0-6d":`Habilita las notas automáticas persistentes de reuniones, la herramienta transcripts del agente y las fuentes configuradas para el inicio automático. Valor predeterminado: true. Establece false para deshabilitar la persistencia y la herramienta; el modo explícito de transcripción de reuniones conserva su segmento reciente en vivo de tamaño limitado.`}},tts:{label:{"v1-bmxkk9-e":`Texto a voz`},help:{"v1-1o27tk2-4n":`Política de texto a voz para leer en voz alta las respuestas del agente en las interfaces de voz o audio compatibles. Mantenla deshabilitada a menos que la reproducción de voz forme parte del flujo de trabajo del operador o del usuario.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`Perfil de voz TTS`},help:{"v1-1r0opcb-29":`Identificador del perfil de voz TTS predeterminado. Las preferencias locales del perfil de voz TTS pueden sustituir este valor en cada host.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`Perfiles de voz TTS`},help:{"v1-19aybhl-2l":`Perfiles de voz TTS con nombre que definen una identidad vocal estable y asociaciones de voz específicas de cada proveedor.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`Perfil de voz TTS`},help:{"v1-10s52ah-2l":`Un perfil de voz TTS. Usa asociaciones específicas de cada proveedor para definir voces y modelos exactos, así como plantillas de instrucciones.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Vinculaciones de proveedores para perfiles TTS`},help:{"v1-993jop-3e":`Vinculaciones de perfiles TTS específicas de cada proveedor, indexadas por el identificador del proveedor de voz. Se combinan con tts.providers y tienen prioridad para el perfil activo.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`Ajustes de proveedores TTS`},help:{"v1-1k80nl4-4y":`Ajustes TTS específicos de cada proveedor, indexados por el identificador del proveedor de voz. Usa esta opción en lugar de las claves de nivel superior específicas de los proveedores incluidos para mantener los plugins de voz desacoplados del esquema de configuración principal.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`Configuración del proveedor TTS`},help:{"v1-dwapva-3d":`Configuración TTS específica de un proveedor, correspondiente a un identificador de proveedor de voz. Limita los campos al plugin al que pertenece ese proveedor.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`Clave de API del proveedor TTS`},help:{"v1-1m2fj0i-2o":`Clave de API que utiliza ese proveedor de voz cuando su plugin requiere acceso autenticado a TTS.`}},tui:{label:{"v1-c8hus1-b":`Interfaz de terminal`},help:{"v1-1fg9vw2-3s":`Ajustes de visualización de la interfaz de terminal. Usa esta sección para las preferencias de presentación exclusivas del terminal sin cambiar el comportamiento de Gateway ni de otras interfaces.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Pie de la interfaz de terminal`},help:{"v1-6e12l3-3k":`Ajustes de visualización del pie de la interfaz de terminal. Mantén compacto el contexto opcional para que la información de sesión, modelo, objetivo y tokens siga siendo legible.`}},ui:{label:{"v1-ye4dff-2":`Interfaz`},help:{"v1-dt1924-42":`Ajustes de presentación de la interfaz para los colores de acento y las preferencias de visualización del operador. Úsalos para personalizar la legibilidad sin cambiar el comportamiento en tiempo de ejecución.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Color de acento del usuario`},help:{"v1-16klzws-4z":`Color de acento de Control UI: #RRGGBB para un color personalizado, o 'theme' para la paleta del tema seleccionado. Tiene prioridad sobre ui.seamColor; déjalo vacío para heredar el color de unión configurado o el valor predeterminado del tema.`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Color de acento`},help:{"v1-14q3r4h-4g":`Color de acento principal que se utiliza en las superficies de la interfaz para destacar elementos, mostrar distintivos y aportar identidad visual. Usa valores de alto contraste que mantengan la legibilidad tanto en temas claros como oscuros.`}},update:{label:{"v1-k12u1x-7":`Actualizaciones`},help:{"v1-11c5k8v-5c":`Comportamiento del canal de actualizaciones y de la comprobación al iniciar para mantener actualizadas las versiones del entorno de ejecución de OpenClaw. Usa canales conservadores en producción y canales más experimentales solo en entornos controlados.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Actualización automática habilitada`},help:{"v1-49xs2h-3c":`Habilita la actualización automática en segundo plano para las instalaciones de paquetes stable y beta; extended-stable nunca aplica actualizaciones automáticamente (valor predeterminado: false).`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Canal de actualizaciones`},help:{"v1-lqtdvf-5b":`Canal de actualizaciones para instalaciones con git + npm ("stable", "extended-stable", "beta" o "dev"). El canal extended-stable solo admite paquetes: la instalación se realiza únicamente en primer plano, con avisos opcionales de solo lectura al iniciar.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Comprobar actualizaciones al iniciar`},help:{"v1-qy3q9g-5v":`Busca actualizaciones cuando se inicia el Gateway, incluidos los avisos de solo lectura de extended-stable (valor predeterminado: true). Establece el valor en false para deshabilitar la búsqueda y la aplicación automáticas de actualizaciones del Gateway y de los nodos sin interfaz gráfica, así como las notificaciones anónimas de actualización.`}},voicewake:{label:{"v1-txt1wb-a":`Activación por voz`}},web:{label:{"v1-1ae9z56-b":`Canal web`}},wizard:{label:{"v1-28jonk-h":`Preferencias de configuración`},help:{"v1-14jh6rm-3b":`Preferencias de configuración propias del usuario. El historial del asistente y el estado de confirmación propios del equipo se almacenan en la base de datos de estado compartida.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Acceso de detección durante la configuración`},help:{"v1-1nqxt0w-38":`Consentimiento de detección para la configuración guiada: "full" analiza sin preguntar, mientras que "guarded" pide permiso antes de inspeccionar las aplicaciones locales.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Recomendaciones de aplicaciones durante la configuración`},help:{"v1-ub8uoi-30":`Controla si la configuración guiada puede usar las etiquetas de las aplicaciones instaladas para recomendar complementos y habilidades relevantes.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Marca de tiempo de la última ejecución del asistente`},help:{"v1-1y0fbk-1k":`Marca de tiempo de la última ejecución del asistente cuyos cambios se guardaron correctamente.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Comando de la última ejecución del asistente`},help:{"v1-x2pfkk-15":`Comando que inició la última ejecución del asistente.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Commit de la última ejecución del asistente`},help:{"v1-h0jkmt-1i":`Commit del código fuente utilizado en la última ejecución del asistente en desarrollo.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Modo de la última ejecución del asistente`},help:{"v1-16508qy-1r":`Indica si la última ejecución del asistente estaba destinada a una configuración "local" o "remote".`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Versión de la última ejecución del asistente`},help:{"v1-1tr4z9d-19":`Versión de OpenClaw utilizada en la última ejecución del asistente.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Marca de tiempo de la aceptación del aviso de seguridad del asistente`},help:{"v1-86i182-2a":`Marca de tiempo de la aceptación del aviso de seguridad durante la configuración, guardada junto con la configuración de destino.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Aceleración de árboles de trabajo`},help:{"v1-9es3gc-4r":`Usa la aceleración del sistema de archivos para los nuevos árboles de trabajo gestionados cuando sea compatible (valor predeterminado: true). Establece false para usar el proceso normal de checkout de Git y la copia de archivos. Solo se aplica a los nuevos árboles de trabajo.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Directorio raíz de los árboles de trabajo`},help:{"v1-1tgti9j-5d":`Directorio global para los nuevos árboles de trabajo administrados. Usa una ruta absoluta o ~ para tu directorio personal; el valor predeterminado es <state-dir>/worktrees. Los árboles de trabajo existentes conservan sus rutas registradas cuando cambia este valor.`}}}}})))()}export{n,t};